  ui_story_5037_50370101_168_dialog_content = "ゴルディはもう十分有名なアイドルでしょ？\n僕の助けなんて必要ある？",
  ui_story_5037_50370101_169_dialog_content = "フフフ…確かに私は少しは名の知れたアイドルだけど、\nそれはもう過去のことよ。",
  ui_story_5037_50370101_170_dialog_content = "今の私はスターウィッシュ・プロダクションの新人だもの。\n業績で実力を証明しなきゃいけないわ！",
  ui_story_5037_50370101_171_dialog_content = "だから、いろいろとPlayerNameプロデューサーに\nお願いしたいの～。",
  ui_story_5037_50370101_172_dialog_content = "でも…",
  ui_story_5037_50370101_173_dialog_content = "シェオルさんがライバルまで用意してるとは知らなかったわ。",
  ui_story_5037_50370101_174_dialog_content = "こんなの初めてだから、\nちょっと緊張しちゃう…えへへ！",
  ui_story_5037_50370101_175_dialog_content = "それって、僕がうまくできなかったら、\nゴルディの今後の仕事に影響するってことだよね…？",
  ui_story_5037_50370101_176_dialog_content = "急にすごいプレッシャーを感じてきたよ…",
  ui_story_5037_50370101_177_dialog_content = "そんなに先のことまで心配することはないわ。",
  ui_story_5037_50370101_178_dialog_content = "一番大切なのは、目の前のことをきちんとやることよ。",
  ui_story_5037_50370101_179_dialog_content = "そうすれば、最終的に思い通りの結果にならなくても、\n後悔はしないでしょ！",
  ui_story_5037_50370101_180_dialog_content = "そ、そうだね！",
  ui_story_5037_50370101_181_dialog_content = "…本当ならプロデューサーがそういう言葉で\nアイドルを励まさなきゃいけないんだよね…？",
  ui_story_5037_50370101_182_dialog_content = "最初から反対に励まされちゃった…",
  ui_story_5037_50370101_183_dialog_content = "…よし、元気出していかないと！\nゴルディの将来のために、僕も頑張ろう！",
  ui_story_5037_50370101_184_dialog_content = "私1人のためじゃないわ～。",
  ui_story_5037_50370101_185_dialog_content = "えっ？",
  ui_story_5037_50370101_186_dialog_content = "私たち2人のためよ！",
  ui_story_5037_50370101_187_dialog_content = "あ…うん、そうだね。僕たち2人のために！",
  ui_story_5037_50370101_188_dialog_content = "ただ、まだよく分かってないんだけど…\n僕たちの目標って何？具体的には何をすればいいの？",
  ui_story_5037_50370101_189_dialog_content = "私たちの目標は決められた期間のうちに、\n3回のコンサートを成功させることよ。",
  ui_story_5037_50370101_190_dialog_content = "…でも、PlayerNameがそのためにすることは、\nたくさんあるの！",
  ui_story_5037_50370101_191_dialog_content = "たとえば、私に合った練習メニューを作ったり、\nどんなイベントに参加するか決めたり、楽曲を製作したり…いろいろあるわ。",
  ui_story_5037_50370101_192_dialog_content = "…どれも僕にはさっぱり分からない世界だよ…",
  ui_story_5037_50370101_193_dialog_content = "実際にやってみれば、\nきっとすぐにコツが分かるわ！",
  ui_story_5037_50370101_194_dialog_content = "今までのプロデューサーはどうしてたの？\n後輩として、いろいろ聞いてみたいなぁ。",
  ui_story_5037_50370101_195_dialog_content = "えへへ、今までの私はセルフプロデュース…\nつまり私自身がプロデューサーよ。",
  ui_story_5037_50370101_196_dialog_content = "え？それって疲れない？",
  ui_story_5037_50370101_197_dialog_content = "確かに大変だったけど、それも昔の話よ。",
  ui_story_5037_50370101_198_dialog_content = "だって今は、専属のプロデューサーがいるものね～。",
  ui_story_5037_50370101_199_dialog_content = "えへへ…",
  ui_story_5037_50370101_200_dialog_content = "さ、ぐずぐずしてられないわ！\nまずはPlayerNameにプロデューサーの仕事、実際に体験してもらうわね。",
  ui_story_5037_50370101_201_dialog_content = "うん、分かった！",
  ui_story_5037_50370201_1_dialog_content = "コンサートがもうすぐ始まるのに…",
  ui_story_5037_50370201_2_dialog_content = "ゴルディのために用意したのど飴、\n舞台裏に置いとくの忘れてた！",
  ui_story_5037_50370201_3_dialog_content = "<color=#828282>ガサガサ――</color>",
  ui_story_5037_50370201_4_dialog_content = "よかった、参考書の中に混ざってた…",
  ui_story_5037_50370201_5_dialog_content = "とにかく、見つかってよかった。\n急いでゴルディに持っていってあげよう！",
  ui_story_5037_50370201_6_dialog_content = "師匠、いそいで！",
  ui_story_5037_50370201_7_dialog_content = "あれ？今のはフィアの声…？",
  ui_story_5037_50370201_8_dialog_content = "もう舞台裏に控えてるはずじゃ？",
  ui_story_5037_50370201_9_dialog_content = "コンサートが始まるっていうのに、\nなんでこんなところで居眠りしてるの！？",
  ui_story_5037_50370201_10_dialog_content = "あちこち探し回ったんだから！",
  ui_story_5037_50370201_11_dialog_content = "睡眠不足じゃ、ステージで\nパフォーマンスなんてできやしないだろ？",
  ui_story_5037_50370201_12_dialog_content = "もうちょい寝かせてくれ。\nあと少ししたら行くからさ…ふあ～ぁ…",
  ui_story_5037_50370201_13_dialog_content = "<size=45>師～匠～！</size>",
  ui_story_5037_50370201_14_dialog_content = "こんな時になにノンキなこと言ってんの？\n緊張してないの？",
  ui_story_5037_50370201_15_dialog_content = "ゴルディお姉ちゃんとPlayerNameなんて、\nもう何度もリハーサルしてるんだよ！",
  ui_story_5037_50370201_16_dialog_content = "あいつらがやったなら、俺たちはもうナシでいいだろ。",
  ui_story_5037_50370201_17_dialog_content = "みんな揃っておんなじことをするなんて、\n時間と労力のムダってもんさ。",
  ui_story_5037_50370201_18_dialog_content = "はぁ～…またダメ師匠のロクデナシ宣言…",
  ui_story_5037_50370201_19_dialog_content = "もう練習も終わってるんだよ？\nしっかりして、マジメに勝負しなきゃ！",
  ui_story_5037_50370201_20_dialog_content = "PlayerNameたちに負けたら、賞金もらえないんだよ！？",
  ui_story_5037_50370201_21_dialog_content = "そうだ！シーラに替わってもらうのはどうだ？",
  ui_story_5037_50370201_22_dialog_content = "ダメ！",
  ui_story_5037_50370201_23_dialog_content = "分からんなあ…フィアはなんだってそんなに、\n年老いた師匠に無理難題を押し付けようとするんだ？",
  ui_story_5037_50370201_24_dialog_content = "あと少しでアイドルデビューするところだったんだぞ～って、\n大ぼら吹いてたのはどこのどの師匠？",
  ui_story_5037_50370201_25_dialog_content = "おいおいフィア、俺がほらを吹いたってんだ？\nお前の師匠はいつだって事実しか言わないぞ。",
  ui_story_5037_50370201_26_dialog_content = "だったらちょうどいいでしょ？",
  ui_story_5037_50370201_27_dialog_content = "今日はついにデビューできるんだから。\nうれしくないの？",
  ui_story_5037_50370201_28_dialog_content = "別に、テキトーにやればいいさ。\n俺は本当にアイドルになりたいワケじゃないからな。",
  ui_story_5037_50370201_29_dialog_content = "どうせなるなら、\n珍獣トレーナーアイドルって言うのはいいかもな！",
  ui_story_5037_50370201_30_dialog_content = "だったらもっと頑張ってお金稼いで、\n珍獣たちの面倒をしっかり見なきゃ！",
  ui_story_5037_50370201_31_dialog_content = "リアリティ番組のギャラだけじゃ、\n師匠の生活費を稼ぐのでせいいっぱいなんだよ！",
  ui_story_5037_50370201_32_dialog_content = "でも、PlayerNameたちに勝てば、\n珍獣たちの環境も良くしてあげられるでしょ！",
  ui_story_5037_50370201_33_dialog_content = "いや、今までの俺だって、\nマジメに仕事は受けてきただろ…？",
  ui_story_5037_50370201_34_dialog_content = "10年分の稼ぎを合わせたって、\nこの番組1回分の出演料にも届かないよ。",
  ui_story_5037_50370201_35_dialog_content = "つまり…あと10年もしたら、かわいそうな珍獣たちが\n師匠のせいで飢え死にしちゃう！",
  ui_story_5037_50370201_36_dialog_content = "そういうわけだから、今度こそしっかり見張ってるからね！\n最後に賞金をもらうのは、あたしたちだよ！",
  ui_story_5037_50370201_37_dialog_content = "（フィアとヴィックが何を話してるのか、\nよく聞こえないけど…）",
  ui_story_5037_50370201_38_dialog_content = "（フィア、ずいぶんとやる気みたいだなぁ。\nそれに比べて、僕は…）",
  ui_story_5037_50370201_39_dialog_content = "あっ、こののど飴、とってもさわやかな味ね！",
  ui_story_5037_50370201_40_dialog_content = "PlayerName、ホントによく気が利くわ！\nのど飴まで用意してくれるなんて！",
  ui_story_5037_50370201_41_dialog_content = "…",
  ui_story_5037_50370201_42_dialog_content = "あら？プロデューサー？何か考え事？",
  ui_story_5037_50370201_43_dialog_content = "いや、何でもないよ。\n気に入ってもらえてよかった。",
  ui_story_5037_50370201_44_dialog_content = "次はもっといろんな味の、\nおいしくて、のどにもいい物を用意しとくね。",
  ui_story_5037_50370201_45_dialog_content = "あら、準備ができたみたいね？",
  ui_story_5037_50370201_46_dialog_content = "ええ！かならずシェオルさんに\n満足してもらえるステージにするわ！",
  ui_story_5037_50370201_47_dialog_content = "フフ、あなたのそういう自信満々なとこ、好きよ～。\nじゃあ、期待して待ってるわ。",
  ui_story_5037_50370201_48_dialog_content = "あの…シェオルさん！",
  ui_story_5037_50370201_49_dialog_content = "あら、PlayerNameプロデューサー。\nどうかしたの？",
  ui_story_5037_50370201_50_dialog_content = "この後、ヴィックとゴルディが\n同じステージでパフォーマンスするんですか？",
  ui_story_5037_50370201_51_dialog_content = "そうよ、何か問題でも？",
  ui_story_5037_50370201_52_dialog_content = "あ、いえ…ただ流れを確認したかっただけです！",
  ui_story_5037_50370201_53_dialog_content = "コンサートは、あなたが計画した流れの通りに進めればいいわ。",
  ui_story_5037_50370201_54_dialog_content = "でも、ヴィックのコンサート会場はこっちじゃないの。\nもう一つのステージよ。",
  ui_story_5037_50370201_55_dialog_content = "2人のコンサートは\n同じ時間に開催されるわ。",
  ui_story_5037_50370201_56_dialog_content = "え、別のステージなんですか！？\nどうりで裏でヴィックを見かけなかったわけだ…",
  ui_story_5037_50370201_57_dialog_content = "そういうことだったのね。シェオルさん、\nこうなることが初めから分かってて、この場所を作ったの？",
  ui_story_5037_50370201_58_dialog_content = "そっくりのステージが2つ…まるで双子みたいだわ。",
  ui_story_5037_50370201_59_dialog_content = "え？そっくりのステージ？",
  ui_story_5037_50370201_60_dialog_content = "フフ、驚くのも無理ないわ。\n何しろ、私自慢のアイデアだもの。",
  ui_story_5037_50370201_61_dialog_content = "2つのステージの間にあるのは廊下だけ。",
  ui_story_5037_50370201_62_dialog_content = "コンサートが始まったら、お客さんたちは好みに合わせて\n2つのステージの間を自由にいったりきたりできるって仕組みよ。",
  ui_story_5037_50370201_63_dialog_content = "最後にお客さんが多く留まっていた方のステージが、\n勝ちってことになるわ。",
  ui_story_5037_50370201_64_dialog_content = "お客さんたちも今までになかった楽しみ方ができるし、\nリアリティ番組のウリにもなるでしょ。",
  ui_story_5037_50370201_65_dialog_content = "あっ、リリカ。\n今のところは編集でカットしておいてね？",
  ui_story_5037_50370201_66_dialog_content = "了解～！",
  ui_story_5037_50370201_67_dialog_content = "（撮られてることにもずいぶん慣れてきたなぁ。\nリリカがいるってこと、忘れるところだった）",
  ui_story_5037_50370201_68_dialog_content = "それじゃ、成功を祈ってるわね～。",
  ui_story_5037_50370201_69_dialog_content = "…それにしても今の話、\nどうしてもっと早く教えてくれなかったんだろう？",
  ui_story_5037_50370201_70_dialog_content = "もう一度セットリストを考えなおして、もっと魅力的なステージにして、\nお客さんを引きつけられるようにしなきゃ！",
  ui_story_5037_50370201_71_dialog_content = "あ！照明と音響設備のチェックがまだだった…",
  ui_story_5037_50370201_72_dialog_content = "それならさっき、チェックしたでしょ？",
  ui_story_5037_50370201_73_dialog_content = "え？そ、そうだっけ？",
  ui_story_5037_50370201_74_dialog_content = "アハハ…どうしたんだろ？\n自分が何をやってたのか、すっかり忘れちゃってた。",
  ui_story_5037_50370201_75_dialog_content = "PlayerNameプロデューサー、もしかして緊張してる？",
  ui_story_5037_50370201_76_dialog_content = "心配いらないわ。\nだって私たち、今日まですっごく頑張って準備してきたんだもの！",
  ui_story_5037_50370201_77_dialog_content = "だから、今日は勝ち負けなんて考えずに…",
  ui_story_5037_50370201_78_dialog_content = "準備してきたプログラムをやって、お客さんに楽しんでもらえたら、\nそれでもう十分成功って言えるわ！",
  ui_story_5037_50370201_79_dialog_content = "そうだね…うん、そうだ、ゴルディの言う通りだよ！",
  ui_story_5037_50370201_80_dialog_content = "普段通り、実力を発揮すればいいだけのことだよね！",
  ui_story_5037_50370201_81_dialog_content = "もうすぐコンサートが始まります！\n開始まで、あと残り<color=#793f76>5分</color>です！",
  ui_story_5037_50370201_82_dialog_content = "…あああああ！",
  ui_story_5037_50370201_83_dialog_content = "ダメだダメだ！\nまだ色々やり残してる気がしてきちゃった！",
  ui_story_5037_50370201_84_dialog_content = "ふふふ、安心して。\n今は静かにコンサートが始まるのを待つだけでいいの。",
  ui_story_5037_50370201_85_dialog_content = "そ、そう？",
  ui_story_5037_50370201_86_dialog_content = "…ごめん。僕がこんなに緊張してたら、\n君まで緊張しちゃうよね。",
  ui_story_5037_50370201_87_dialog_content = "やっぱり、僕はまだ一人前のプロデューサーには…",
  ui_story_5037_50370201_88_dialog_content = "そんなことないわ！",
  ui_story_5037_50370201_89_dialog_content = "それに、どんなことでも初めてがあるでしょ。",
  ui_story_5037_50370201_90_dialog_content = "PlayerNameプロデューサーは、\n私が初めてステージに上がった時よりずっとしっかりしてるわ！",
  ui_story_5037_50370201_91_dialog_content = "ゴルディが初めてステージに上がった時？",
  ui_story_5037_50370201_92_dialog_content = "そうよ。あの頃は事務所にも入ってなくて…",
  ui_story_5037_50370201_93_dialog_content = "苦労して、やっとの思いでステージに上がるチャンスを手に入れて…",
  ui_story_5037_50370201_94_dialog_content = "――続いて、ゴルディさんの登場です！\n会場が盛り上がる曲を披露していただきます！",
  ui_story_5037_50370201_95_dialog_content = "こ、こんにちは！",
  ui_story_5037_50370201_96_dialog_content = "だれ？",
  ui_story_5037_50370201_97_dialog_content = "見たことない子だなあ。",
  ui_story_5037_50370201_98_dialog_content = "ま、いいや。今のうちにトイレ行っとこ～っと。",
  ui_story_5037_50370201_99_dialog_content = "えっ…",
  ui_story_5037_50370201_100_dialog_content = "（ど、どうしてお客さんたち、席を離れちゃうの？）",
  ui_story_5037_50370201_101_dialog_content = "（残ったお客さんたちが、じっとこっちを見てる…）",
  ui_story_5037_50370201_102_dialog_content = "（そういえば…私、どうしてここに立ってるんだっけ？）",
  ui_story_5037_50370201_103_dialog_content = "（何しに、来たんだっけ…？）",
  ui_story_5037_50370201_104_dialog_content = "あの子、ステージに突っ立って何してるの？\nマイクスタンドのまね？",
  ui_story_5037_50370201_105_dialog_content = "歌わないなら、さっさと下がれ！",
  ui_story_5037_50370201_106_dialog_content = "わ、私は…",
  ui_story_5037_50370201_107_dialog_content = "…それで、お客さんにステージから降ろされたの？",
  ui_story_5037_50370201_108_dialog_content = "ごめん…僕のせいで、辛いことを思い出させちゃったね。",
  ui_story_5037_50370201_109_dialog_content = "大丈夫よ。今はもう、辛いなんて思ってないもの。",
  ui_story_5037_50370201_110_dialog_content = "えっ？",
  ui_story_5037_50370201_111_dialog_content = "何事も最初は難しいものよ。\nだからあの時、私は自分に言い聞かせたの…",
  ui_story_5037_50370201_112_dialog_content = "ミスはしてもいい。\nでも、同じミスは二度としないってね！",
  ui_story_5037_50370201_113_dialog_content = "だから、2回目、3回目ってステージに上がった時は、\n緊張で歌詞を忘れることもなくなったわ。",
  ui_story_5037_50370201_114_dialog_content = "もし、初めてステージに上がった時の恐怖を克服できずに、\nずっとメソメソ悩んでたら…",
  ui_story_5037_50370201_115_dialog_content = "今のゴルディは、きっとなかったと思うの。",
  ui_story_5037_50370201_116_dialog_content = "…ゴルディ、すごいよ！",
  ui_story_5037_50370201_117_dialog_content = "正直に言うと、今でもちょっとは緊張しちゃうんだけどね。\nえへへ。",
  ui_story_5037_50370201_118_dialog_content = "でも、適度な緊張は集中力を高めるものよ。\nそれで普段以上に力を発揮できたりすることもあるの！",
  ui_story_5037_50370201_119_dialog_content = "そうなんだ…？ゴルディが緊張してるなんて、\nぜんぜん分からなかったよ！",
  ui_story_5037_50370201_120_dialog_content = "う～ん、それはプロデューサーが緊張しすぎだから、\n私は大丈夫そうに見えるだけじゃないかしら？",
  ui_story_5037_50370201_121_dialog_content = "フフ、とにかく、いろいろ話しちゃったけど、\n私が言いたかったことはね…",
  ui_story_5037_50370201_122_dialog_content = "ゴルディを信じてってこと！",
  ui_story_5037_50370201_123_dialog_content = "なんたって、私は百戦錬磨のプロのアイドルなのよ？",
  ui_story_5037_50370201_124_dialog_content = "それに、今回は優秀なプロデューサーがこのコンサートにふさわしい\nステキな曲と衣装、それからセットまで用意してくれた。",
  ui_story_5037_50370201_125_dialog_content = "そうそう、すっごくおいしいのど飴もね！",
  ui_story_5037_50370201_126_dialog_content = "だから私、絶対にあなたをガッカリさせたりしないわ！",
  ui_story_5037_50370201_127_dialog_content = "ゴルディ…",
  ui_story_5037_50370201_128_dialog_content = "うん！僕もゴルディをガッカリさせないよ。",
  ui_story_5037_50370201_129_dialog_content = "コンサート開始まであと10秒です。\nカウントダウンを開始します！",
  ui_story_5037_50370201_130_dialog_content = "10…9…8…7…",
  ui_story_5037_50370201_131_dialog_content = "プロデューサー、それじゃあ行ってくるわね！",
  ui_story_5037_50370201_132_dialog_content = "うん！ゴルディ、頑張って！",
  ui_story_5037_50370201_133_dialog_content = "まかせて！",
  ui_story_5037_50370301_1_dialog_content = "ディディ！ディディ！",
  ui_story_5037_50370301_2_dialog_content = "ゴルディ！ゴルディ！",
  ui_story_5037_50370301_3_dialog_content = "すごい盛り上がりだ！",
  ui_story_5037_50370301_4_dialog_content = "コンサートは終わったのに、\n皆ずっとゴルディの名前を叫んでる！",
  ui_story_5037_50370301_5_dialog_content = "プロデューサー、ただいま～！",
  ui_story_5037_50370301_6_dialog_content = "ゴルディ、お疲れ様！",
  ui_story_5037_50370301_7_dialog_content = "あらら～？どうしちゃったの？\n泣きそうな顔してるわよ？",
  ui_story_5037_50370301_8_dialog_content = "やった…僕たち、うまくやったんだ！",
  ui_story_5037_50370301_9_dialog_content = "今日のコンサート、本当に良かったよ！\n会場全体が君の歌の世界に浸りきってた。",
  ui_story_5037_50370301_10_dialog_content = "うん、私も感じたわ。\nステージと自分が一つになったみたいだったの！",
  ui_story_5037_50370301_11_dialog_content = "バラードを歌ってる時なんて、\nたくさんのお客さんが感動で涙を流してたよ。",
  ui_story_5037_50370301_12_dialog_content = "後半のテンポの速い曲になったら、\n今度は皆、リズムに乗って身体を動かしたりしてた…",
  ui_story_5037_50370301_13_dialog_content = "ゴルディ、今日のステージ、まさに完璧だったよ！",
  ui_story_5037_50370301_14_dialog_content = "えへへ、それもこれも、PlayerNameプロデューサーのおかげよ。",
  ui_story_5037_50370301_15_dialog_content = "だって私自身、自分がこんなにいろいろできるなんて\n知らなかったもの！",
  ui_story_5037_50370301_16_dialog_content = "それから、照明と舞台美術もすっごくよかった！\nだから、これだけ感動的なステージになったんだわ。",
  ui_story_5037_50370301_17_dialog_content = "お客さんだけじゃないわ。\n私も本気で楽しんじゃった！",
  ui_story_5037_50370301_18_dialog_content = "それにしても、PlayerNameが新人プロデューサーだなんて、\nホントに信じられないわ。",
  ui_story_5037_50370301_19_dialog_content = "もう一人前の敏腕プロデューサーみたいだもの！",
  ui_story_5037_50370301_20_dialog_content = "へへへ、それほどじゃないよ。\nまだまだ足りないところだってたくさんあるし…",
  ui_story_5037_50370301_21_dialog_content = "コンサートが始まる前に、僕がサイズを測り間違えちゃったせいで\n道具が搬入できなくなるところだったこととか…",
  ui_story_5037_50370301_22_dialog_content = "あの時は、ゴルディが経験者だったおかげで\nなんとか切り抜けられたけど…",
  ui_story_5037_50370301_23_dialog_content = "今度はもう「同じミス」、しないでね？…なんてね！",
  ui_story_5037_50370301_24_dialog_content = "う…うん！",
  ui_story_5037_50370301_25_dialog_content = "ふふふっ…",
  ui_story_5037_50370301_26_dialog_content = "そうだ！シェオルさんがコンサートが終わったら、\n事務所で結果発表するって言ってたよ。",
  ui_story_5037_50370301_27_dialog_content = "わかったわ、じゃあ急ぎましょ！",
  ui_story_5037_50370301_28_dialog_content = "ああもう、師匠！？\nさっきのステージ、ぜんっぜんやる気なかったでしょ！？",
  ui_story_5037_50370301_29_dialog_content = "…とはいえ、師匠の気が抜けたパフォーマンスが\nまさかお客さんにウケるなんて…",
  ui_story_5037_50370301_30_dialog_content = "ひょっとして、そういう演出だとカン違いしてたとか？\nアハハ…",
  ui_story_5037_50370301_31_dialog_content = "まっ、師匠にもホントにちょ～っとだけ、\nアイドルの才能があるってことなのかな…？",
  ui_story_5037_50370301_32_dialog_content = "だから言ったろ、前にもデビューしかけた～って。",
  ui_story_5037_50370301_33_dialog_content = "じゃあ、なんでその時はデビューしなかったの？",
  ui_story_5037_50370301_34_dialog_content = "ああ？どうしてって、そりゃあ…",
  ui_story_5037_50370301_35_dialog_content = "…そっか、フィアがずーっと師匠がしっかり練習するように\n見張ってたからに決まってるよね！",
  ui_story_5037_50370301_36_dialog_content = "ヴィックとフィア、楽しそうに話してるなぁ。",
  ui_story_5037_50370301_37_dialog_content = "あっちのコンサートも成功したみたいね。",
  ui_story_5037_50370301_38_dialog_content = "…",
  ui_story_5037_50370301_39_dialog_content = "ほらほら、そんな暗い顔しないで？今は私もヴィックも、\n同じスターウィッシュ・プロダクションのアイドルなのよ。",
  ui_story_5037_50370301_40_dialog_content = "2人ともデビューコンサートがうまくいったなら、\nいいことじゃない！",
  ui_story_5037_50370301_41_dialog_content = "…うん、そうだね！",
  ui_story_5037_50370301_42_dialog_content = "あら～？みんな揃ってるみたいね。",
  ui_story_5037_50370301_43_dialog_content = "まずはお疲れ様。\nで…まどろっこしい前置きは抜きにして、早速本題に入らせてもらうわね。",
  ui_story_5037_50370301_44_dialog_content = "今回の対決の結果だけど…",
  ui_story_5037_50370301_45_dialog_content = "…",
  ui_story_5037_50370301_46_dialog_content = "結果は…？",
  ui_story_5037_50370301_47_dialog_content = "引き分けよ！",
  ui_story_5037_50370301_48_dialog_content = "えっ？",
  ui_story_5037_50370301_49_dialog_content = "デビューしたての新人アイドルが、\n先輩アイドルと勝負して引き分け…",
  ui_story_5037_50370301_50_dialog_content = "リアリティ番組って、本当に先が読めなくて\nドキドキしちゃうわね～。",
  ui_story_5037_50370301_51_dialog_content = "この調子なら、視聴率の心配はなさそうね。フフフ。",
  ui_story_5037_50370301_52_dialog_content = "ただし、いくつか言っておきたいことがあるの。",
  ui_story_5037_50370301_53_dialog_content = "2人を応援してるお客さんの数、\n今回はほぼ互角だったけど…",
  ui_story_5037_50370301_54_dialog_content = "コンサートは、あと<color=#793f76>2回</color>残ってるの。",
  ui_story_5037_50370301_55_dialog_content = "つまり、あなたたちが競うのは――3回目のコンサート終了後の、\n<color=#793f76>ファンの合計人数</color>…",
  ui_story_5037_50370301_56_dialog_content = "だから、今回の結果がどうであれ…",
  ui_story_5037_50370301_57_dialog_content = "次のコンサートにしっかり備えてね。",
  ui_story_5037_50370301_58_dialog_content = "ゴルディと引き分けか…\nやっぱり俺も捨てたもんじゃないな！",
  ui_story_5037_50370301_59_dialog_content = "だがあいにく、このトシじゃこれ以上の練習には耐えられない。\n俺はここら辺で帰らせてもら――",
  ui_story_5037_50370301_60_dialog_content = "ふふん！それってつまり…",
  ui_story_5037_50370301_61_dialog_content = "師匠に全力を出させれば、\nゴルディお姉ちゃんとPlayerNameに勝てるってことね！！",
  ui_story_5037_50370301_62_dialog_content = "そうと分かれば、イチから全部やり直さなきゃ！",
  ui_story_5037_50370301_63_dialog_content = "師匠！次の対決、手は抜かせないからね！",
  ui_story_5037_50370301_64_dialog_content = "ああ？おい、フィア、どこ行くんだ？",
  ui_story_5037_50370301_65_dialog_content = "リハーサル室！それから練習の続き！",
  ui_story_5037_50370301_66_dialog_content = "おいおい、かわいい愛弟子さんよ、\nいつになったら師匠を休ませてくれるんだ…？",
  ui_story_5037_50370301_67_dialog_content = "キャロ、師匠を引っ張ってきて！",
  ui_story_5037_50370301_68_dialog_content = "ルルル！",
  ui_story_5037_50370301_69_dialog_content = "キャロ、おい！そんな乱暴にするなって…",
  ui_story_5037_50370301_70_dialog_content = "…ヴィックがこんなにいい結果を出すなんて…",
  ui_story_5037_50370301_71_dialog_content = "さすが、私が見込んだ新人だわ！\n初めてのコンサートから大勢のお客さんのハートをつかめるなんて。",
  ui_story_5037_50370301_72_dialog_content = "それにフィアちゃんもプロデューサーとして、\nホントに一生懸命頑張ってたもの。",
  ui_story_5037_50370301_73_dialog_content = "彼女、毎日深夜までヴィックの練習を見張ってたらしいわよ？",
  ui_story_5037_50370301_74_dialog_content = "あ、僕も何度か見かけたことがあるよ。",
  ui_story_5037_50370301_75_dialog_content = "ヴィックが練習の手を抜くたびに、\nキャロにかかとを咬まれてたっけ…",
  ui_story_5037_50370301_76_dialog_content = "へえ？あのキャロっていう珍獣ちゃん、そんなに強いの？",
  ui_story_5037_50370301_77_dialog_content = "うーん、私も一匹捕まえて、かんでもらおうかしら…",
  ui_story_5037_50370301_78_dialog_content = "そ、その必要はないんじゃないかな…？",
  ui_story_5037_50370301_79_dialog_content = "ゴルディは誰かが見張ったりしなくても、十分努力できるんだし！",
  ui_story_5037_50370301_80_dialog_content = "…むしろ、キャロの見張りが必要なのは僕の方かも。",
  ui_story_5037_50370301_81_dialog_content = "優秀なアイドルの君が新人と引き分けなんて、\nきっと僕の努力が足りなかったせいだ。",
  ui_story_5037_50370301_82_dialog_content = "そんなことはないわ、PlayerNameプロデューサー。",
  ui_story_5037_50370301_83_dialog_content = "アイドルの人気っていうのはね、\n説明のつかない、不思議な巡り合わせみたいなものがあるの。",
  ui_story_5037_50370301_84_dialog_content = "少なくとも、私は今日ステージをとっても楽しんだし、\n何の心残りもないわ。だから、それで十分よ！",
  ui_story_5037_50370301_85_dialog_content = "…ありがとう。",
  ui_story_5037_50370301_86_dialog_content = "でも、ゴルディが慰めてくれたからといって、\n自分に甘くしたりはしないよ。",
  ui_story_5037_50370301_87_dialog_content = "えっ？",
  ui_story_5037_50370301_88_dialog_content = "もっと努力して、プロデューサーに必要なスキルを\nきちんと身に付ける！",
  ui_story_5037_50370301_89_dialog_content = "それでもって、もっといいスケジュールと\n練習メニューを作るよ！",
  ui_story_5037_50370301_90_dialog_content = "それからゴルディと一緒に、次はもっと感動的で衝撃的な\nコンサートを開いてみせる！",
  ui_story_5037_50370301_91_dialog_content = "…PlayerName。",
  ui_story_5037_50370301_92_dialog_content = "「次」だけじゃダメよ？コンサートはあと2回あるんだもの。\nそれに…この先もきっと、一緒に頑張るチャンスはたくさんあるはずだしね！",
  ui_story_5037_50370301_93_dialog_content = "そっか、それもそうだね。じゃあ、仕切り直して！",
  ui_story_5037_50370301_94_dialog_content = "ゴルディと一緒に、これから先のコンサートを\nもっと感動的なものにしてみせるよ！",
  ui_story_5037_50370301_95_dialog_content = "うん！",
  ui_story_5037_50370301_96_dialog_content = "ということで、これからも引き続きよろしくね！",
  ui_story_5037_50370301_97_dialog_content = "デビューコンサート直後のインタビュー、\nレディー…",
  ui_story_5037_50370301_98_dialog_content = "アクション！！",
  ui_story_5037_50370301_99_dialog_content = "10点満点とすると、今回のコンサートには何点をつけますか？",
  ui_story_5037_50370301_100_dialog_content = "もちろん、10点満点よ。",
  ui_story_5037_50370301_101_dialog_content = "そうね…8点といったところかしら。\nまだ伸びしろはあると思うわ。",
  ui_story_5037_50370301_102_dialog_content = "あの2人が組んだところで、\n何が起こるっていうの？",
  ui_story_5037_50370301_103_dialog_content = "え？そうよ、コンサートは観に行っていないわ。",
  ui_story_5037_50370301_104_dialog_content = "…今、なんて言ったかしら？\nお客さんの反応が良かった？",
  ui_story_5037_50370301_105_dialog_content = "相手のコンサートには、何点をつけますか？",
  ui_story_5037_50370301_106_dialog_content = "う～ん…同じく、10点かしら？\nフィアとヴィック、とっても頑張っていたもの。",
  ui_story_5037_50370301_107_dialog_content = "やはり8点ね。あちらもまだ伸びしろがあるわ。",
  ui_story_5037_50370301_108_dialog_content = "その質問、どうしても答えなきゃいけないの？",
  ui_story_5037_50370301_109_dialog_content = "自分の応援している友人に、最近何か変化はありましたか？",
  ui_story_5037_50370301_110_dialog_content = "PlayerNameは…そうね、前よりも規則正しい生活を送るようになったわ。\n朝もきちんと早起きしてるの。",
  ui_story_5037_50370301_111_dialog_content = "思った以上に学習能力が高いように感じたわ。\nプロデューサーとは何をすべきなのか、すぐに要領を得たようね。",
  ui_story_5037_50370301_112_dialog_content = "いつも通りって感じだけれど？",
  ui_story_5037_50370301_113_dialog_content = "はーい、撮影終了～！",
  ui_story_5037_50370301_114_dialog_content = "…え、なになに？\nPlayerNameたちがもう練習を始めてる？",
  ui_story_5037_50370301_115_dialog_content = "こうしちゃいられないわ、急いで撮影しに行かなきゃ！",
  ui_story_5037_50370401_1_dialog_content = "プロデューサー、こちらの大きいセットはどちらへ運べばいいですか？",
  ui_story_5037_50370401_2_dialog_content = "ステージの真ん中に運んでもらってもいいかな。\nちょうど真ん中になるように置いてね。",
  ui_story_5037_50370401_3_dialog_content = "プロデューサー、照明の加減はこのぐらいでいいですか？",
  ui_story_5037_50370401_4_dialog_content = "うーん、ちょっとまぶしいかな。\nもう少しだけ弱くしてもらってもいい？",
  ui_story_5037_50370401_5_dialog_content = "プロデューサー、こちらの確認お願いします！",
  ui_story_5037_50370401_6_dialog_content = "プロデューサー、この件は…",
  ui_story_5037_50370401_7_dialog_content = "プロデューサー！プロデューサー！",
  ui_story_5037_50370401_8_dialog_content = "ま、待って…順番に1つずつ聞いて…",
  ui_story_5037_50370401_9_dialog_content = "<color=#828282>しばらくして</color>",
  ui_story_5037_50370401_10_dialog_content = "ふぅ…なんとか一段落したかな。",
  ui_story_5037_50370401_11_dialog_content = "お疲れ様～。",
  ui_story_5037_50370401_12_dialog_content = "あ、ゴルディ！もう準備できたの？",
  ui_story_5037_50370401_13_dialog_content = "ええ、準備バッチリよ！",
  ui_story_5037_50370401_14_dialog_content = "じゃ、いつもの、いる？",
  ui_story_5037_50370401_15_dialog_content = "ええ、いつもの！",
  ui_story_5037_50370401_16_dialog_content = "はい。",
  ui_story_5037_50370401_17_dialog_content = "ありがとう！",
  ui_story_5037_50370401_18_dialog_content = "えっ？何が「いつもの」なの？\n2人とも何を言ってるのか分からないわ！",
  ui_story_5037_50370401_19_dialog_content = "PlayerNameから受け取ったのは何？\n撮り逃しちゃったわ…",
  ui_story_5037_50370401_20_dialog_content = "ふふ、私たち、息ピッタリでしょ？",
  ui_story_5037_50370401_21_dialog_content = "PlayerNameプロデューサーは、\n私の好きなミント味ののど飴をいつも持ち歩いてくれてるの。",
  ui_story_5037_50370401_22_dialog_content = "そののど飴をくれただけのことよ。",
  ui_story_5037_50370401_23_dialog_content = "2人とも、いつの間にそんなに息が合うようになったの？",
  ui_story_5037_50370401_24_dialog_content = "うう～ん、そうね…ここ数日のことかしら？",
  ui_story_5037_50370401_25_dialog_content = "ずっと一緒に練習してるうちに、言葉に出さなくても、\n目を見れば何を言いたいのか分かるようになってきたの。",
  ui_story_5037_50370401_26_dialog_content = "へー…すごい…",
  ui_story_5037_50370401_27_dialog_content = "…って、待って！",
  ui_story_5037_50370401_28_dialog_content = "2人が何も言わなくなったら、\n撮るものが無くなっちゃうわ？",
  ui_story_5037_50370401_29_dialog_content = "…じゃあ、私からPlayerNameに何か話題を振ってみる？",
  ui_story_5037_50370401_30_dialog_content = "それじゃ演技になっちゃうでしょ。",
  ui_story_5037_50370401_31_dialog_content = "うーん、そうね…そうだ！",
  ui_story_5037_50370401_32_dialog_content = "こっちも応援の人たちみたいに\nインタビューしちゃうのはどうかしら！",
  ui_story_5037_50370401_33_dialog_content = "えへへ、あたしってほんと才能有るわ！",
  ui_story_5037_50370401_34_dialog_content = "バイスたちの事？いつの間にそんなことしてたの？",
  ui_story_5037_50370401_35_dialog_content = "ふっふっふっ、放送を見ればわかるわよ～。",
  ui_story_5037_50370401_36_dialog_content = "ということで！ちょっとだけ時間をもらって…はいっ！\nコンサート前の独占インタビューといきましょ！",
  ui_story_5037_50370401_37_dialog_content = "コンサート対決直前、PlayerNameチームの独占インタビュー。\nカメラ、レディー…",
  ui_story_5037_50370401_38_dialog_content = "アクション！！",
  ui_story_5037_50370401_39_dialog_content = "今回のコンサートとデビュー時のコンサートで、\n何か違いますか？",
  ui_story_5037_50370401_40_dialog_content = "デビューコンサートは、自分がスターウィッシュ・プロダクションで\nアイドルとして活動を始めるにふさわしいと証明するためのものだったわ。",
  ui_story_5037_50370401_41_dialog_content = "たとえるなら…そうね、遊園地の入場チケットみたいなものかしら。",
  ui_story_5037_50370401_42_dialog_content = "じゃあ、ゴルディは事務所に入った後、何ができるのか？",
  ui_story_5037_50370401_43_dialog_content = "そういった部分は、パフォーマンスで証明していくしかないわ。",
  ui_story_5037_50370401_44_dialog_content = "コンサート対決は事務所からの試験で…\n期間中僕たちがどれだけのことを学んできたのか、チェックする目的があるんです。",
  ui_story_5037_50370401_45_dialog_content = "でも、僕はむしろ「ディディ推し」の人たちに\n試されてるんじゃないかと思ってます。",
  ui_story_5037_50370401_46_dialog_content = "ふふ、その通りね。だからこそ、みんなに証明してみせたいの。",
  ui_story_5037_50370401_47_dialog_content = "どこにいたって、ゴルディは初心を忘れずにいるからねって！",
  ui_story_5037_50370401_48_dialog_content = "準備期間中、プレッシャーは感じましたか？",
  ui_story_5037_50370401_49_dialog_content = "いいえ、ぜんぜん！",
  ui_story_5037_50370401_50_dialog_content = "…なんて、冗談よ。\nプレッシャーを感じるのは、ごく当然のことだと思うわ。",
  ui_story_5037_50370401_51_dialog_content = "ただ、ホントに心から感謝してるの。\nプロデューサーが色々助けてくれたおかげで…",
  ui_story_5037_50370401_52_dialog_content = "私は練習に専念することができたから。\nとっても気が楽だったわ。",
  ui_story_5037_50370401_53_dialog_content = "練習の成果については…\nこの後のコンサートを見てもらえれば分かると思うわ。",
  ui_story_5037_50370401_54_dialog_content = "プロデューサー業についてはどうですか？",
  ui_story_5037_50370401_55_dialog_content = "正直に言うと、デビューコンサートまでは、\nしばらく本当に辛い日が続いてました。",
  ui_story_5037_50370401_56_dialog_content = "それにデビューコンサートでも、\n準備でたくさんミスをしちゃいましたし。",
  ui_story_5037_50370401_57_dialog_content = "でも、2回目だからだいぶ慣れてきました。\nプロデューサーとしてお仕事もうまくこなせるようになったと思います。",
  ui_story_5037_50370401_58_dialog_content = "二度と同じミスはしません。",
  ui_story_5037_50370401_59_dialog_content = "ええ、それは私が保証するわ！",
  ui_story_5037_50370401_60_dialog_content = "PlayerNameも、\n今じゃすっかりプロのプロデューサーよ。",
  ui_story_5037_50370401_61_dialog_content = "ここのところ毎日忙しくて、\nPlayerName、ほとんど寝てないみたいね。",
  ui_story_5037_50370401_62_dialog_content = "今回のコンサートのために、\nPlayerNameプロデューサーはホントに一生懸命頑張ってたの！",
  ui_story_5037_50370401_63_dialog_content = "これぐらい当然のことです。",
  ui_story_5037_50370401_64_dialog_content = "ゴルディと一緒にすばらしいステージを作り上げて、\n「ディディ推し」の皆に楽しんでもらえれば、それでいいんです。",
  ui_story_5037_50370401_65_dialog_content = "だから、少しも辛いとは思ってません！",
  ui_story_5037_50370401_66_dialog_content = "どのような演出を用意しているのですか？\nよければ、少しだけ教えていただけないでしょうか？",
  ui_story_5037_50370401_67_dialog_content = "今はまだ秘密よ。",
  ui_story_5037_50370401_68_dialog_content = "でも、今までのコンサートで\n見たことないものになるのは間違いナシね！",
  ui_story_5037_50370401_69_dialog_content = "テーマだけなら話してもいいんじゃないかな？",
  ui_story_5037_50370401_70_dialog_content = "あっ、それもそうね！",
  ui_story_5037_50370401_71_dialog_content = "プロデューサーは、3回のコンサートに\nそれぞれ違ったテーマを設定しているんです。",
  ui_story_5037_50370401_72_dialog_content = "デビューコンサートのテーマは<color=#793f76>「芽生え」</color>。\nコンサートを観てくれたお客さんたちにも伝わったかしら？",
  ui_story_5037_50370401_73_dialog_content = "で、今回のテーマは、\n<color=#793f76>「春を待つツボミ」</color>よ！",
  ui_story_5037_50370401_74_dialog_content = "そのテーマを軸にして、プロデューサーのおかげで\n新しいコンサートが仕上げられたと思うわ。",
  ui_story_5037_50370401_75_dialog_content = "お金を払ってわざわざ観に来てくれるお客さんたちに、\n同じものなんて絶対に見せないわ！",
  ui_story_5037_50370401_76_dialog_content = "少し訂正すると、僕はあくまで裏方の仕事しかしてません。\nコンサートがいいものに仕上がったのは、ゴルディのおかげだと思います。",
  ui_story_5037_50370401_77_dialog_content = "最初はカバー曲でもと考えてたけど…",
  ui_story_5037_50370401_78_dialog_content = "ゴルディが今回のコンサートのために、\nたくさんオリジナルの曲を書いてくれたんです。",
  ui_story_5037_50370401_79_dialog_content = "練習中、急にいろんな感情がこみあげてきちゃったのよね。",
  ui_story_5037_50370401_80_dialog_content = "…アイドルになるって決めてから、\n今までずっと、独りで頑張ってきたけど…",
  ui_story_5037_50370401_81_dialog_content = "でも今は、PlayerNameプロデューサーが\n助けてくれるだけじゃなくて…",
  ui_story_5037_50370401_82_dialog_content = "同じ目標に向かって頑張るライバルもいるの。",
  ui_story_5037_50370401_83_dialog_content = "ううん…ライバルじゃないわね。\nヴィックは同じアイドルとして、一緒に頑張る仲間よ。",
  ui_story_5037_50370401_84_dialog_content = "そういうたくさんの思いに心を動かされたからこそ、\n新しい曲をたくさん書けたんだと思うわ。",
  ui_story_5037_50370401_85_dialog_content = "ゴルディの新曲は練習で何度も聞いたけど、\n何度聞いても…",
  ui_story_5037_50370401_86_dialog_content = "すごく感動するものだと思っています！",
  ui_story_5037_50370401_87_dialog_content = "たくさんの心がこもった歌だから、きっと皆にも気に入ってもらえるかなと！",
  ui_story_5037_50370401_88_dialog_content = "プロデューサーは毎日外でビラ配りもしていたとお聞きしましたが、\nゴルディのためにお客さんを集められていたのですか？",
  ui_story_5037_50370401_89_dialog_content = "えっ？そうだったの？",
  ui_story_5037_50370401_90_dialog_content = "そんなの初めて聞いたわ。\nどうして一言も言ってくれなかったの？",
  ui_story_5037_50370401_91_dialog_content = "それは…その、そもそも僕の仕事だし、大したことでもないし。",
  ui_story_5037_50370401_92_dialog_content = "あ、そういえば！",
  ui_story_5037_50370401_93_dialog_content = "食事しに行ってくる、おやつを買いに行ってくるって、\n何度か出かけたことがあったけど…",
  ui_story_5037_50370401_94_dialog_content = "その時こっそりビラ配りに行ってたのね？",
  ui_story_5037_50370401_95_dialog_content = "うん…余計な気を遣わせるんじゃないかと思って、\n言ってなかったんだ。隠しててごめん。",
  ui_story_5037_50370401_96_dialog_content = "…ゴルディはいつも結果は重要じゃない、\nそれまでの過程で精いっぱい頑張ったなら悔いはないって言うけど…",
  ui_story_5037_50370401_97_dialog_content = "それでも僕は、ゴルディにはもっと多くの人に注目されて、\nもっと多くのファンに好かれてほしいって思っています。",
  ui_story_5037_50370401_98_dialog_content = "そうじゃないと、やっぱり僕に悔いが残るので。",
  ui_story_5037_50370401_99_dialog_content = "PlayerNameプロデューサー…",
  ui_story_5037_50370401_100_dialog_content = "…次は私も一緒に行くわ！\n街頭パフォーマンスをやれば、たくさんの人に注目してもらえるもの！",
  ui_story_5037_50370401_101_dialog_content = "忘れないで。私たちはチームなのよ！",
  ui_story_5037_50370401_102_dialog_content = "チームか…うん、そうだね、僕たちはチームだ！",
  ui_story_5037_50370401_103_dialog_content = "今回のコンサート、自信のほどはいかがですか？",
  ui_story_5037_50370401_104_dialog_content = "プロデューサー、私のこと、信じてくれる？",
  ui_story_5037_50370401_105_dialog_content = "練習をずっと見てきたけど、本当に何の文句もつけようがありません。\nまさに完璧です！",
  ui_story_5037_50370401_106_dialog_content = "今日はただ、いつもと違う場所でパフォーマンスするだけです。\nもちろん、ゴルディなら絶対にうまくいくって信じてます！",
  ui_story_5037_50370401_107_dialog_content = "偶然ね、私もPlayerNameプロデューサーのこと、信じてるわ！",
  ui_story_5037_50370401_108_dialog_content = "じゃ、いつもの、いる？",
  ui_story_5037_50370401_109_dialog_content = "ええ、いつもの！",
  ui_story_5037_50370401_110_dialog_content = "ファイト！オー！",
  ui_story_5037_50370401_111_dialog_content = "プロデューサー、このセットはどこに置けばいいですか？",
  ui_story_5037_50370401_112_dialog_content = "あれ、プロデューサーは？",
  ui_story_5037_50370401_113_dialog_content = "プロデューサー！プロデューサー！",
  ui_story_5037_50370401_114_dialog_content = "ええと…お先に失礼しますね！",
  ui_story_5037_50370401_115_dialog_content = "ふぅ…",
  ui_story_5037_50370401_116_dialog_content = "PlayerName抜きじゃ、\nコンサートはもう回らないみたいね。",
  ui_story_5037_50370401_117_dialog_content = "私もしっかり気持ちを整えて、\nステージに上がる準備をしなきゃ！",
  ui_story_5037_50370501_1_dialog_content = "――それじゃ、今回のコンサートの結果を発表するわ。",
  ui_story_5037_50370501_2_dialog_content = "今回の結果は、私の想像をはるかに超えていたわね。",
  ui_story_5037_50370501_3_dialog_content = "（シェオルさんの想像を超える結果って…どんな結果だろう？）",
  ui_story_5037_50370501_4_dialog_content = "（まさか…ヴィックが勝ったとか？）",
  ui_story_5037_50370501_5_dialog_content = "今回の対決の勝者は、デビューコンサート後のプレッシャーにも負けず、\n見事に多くのお客さんを引きつけたわ。",
  ui_story_5037_50370501_6_dialog_content = "それは、アイドル本人の血のにじむような練習の成果であると同時に…",
  ui_story_5037_50370501_7_dialog_content = "プロデューサーの誠心誠意を尽くしたサポートの結果でもあるわね。",
  ui_story_5037_50370501_8_dialog_content = "（「血のにじむような練習」と「誠心誠意を尽くしたサポート」？\nまさに師匠とあたしのことじゃない！？）",
  ui_story_5037_50370501_9_dialog_content = "（努力は裏切らないって言うけど、\n師匠、やっぱりゴルディお姉ちゃんに勝てたの！？）",
  ui_story_5037_50370501_10_dialog_content = "対決の結果は…",
  ui_story_5037_50370501_11_dialog_content = "…",
  ui_story_5037_50370501_12_dialog_content = "エヘヘ～",
  ui_story_5037_50370501_13_dialog_content = "<size=45>ゴルディ＆PlayerNameチームの勝ち！</size>",
  ui_story_5037_50370501_14_dialog_content = "聞いた？私たち、勝ったわ！",
  ui_story_5037_50370501_15_dialog_content = "ぼ、僕たちの勝ち？",
  ui_story_5037_50370501_16_dialog_content = "え？？？ど、どうして！？",
  ui_story_5037_50370501_17_dialog_content = "おっ、ウチに帰れる日にまた一歩近づいたな。",
  ui_story_5037_50370501_18_dialog_content = "対決というのは厳しいものなのよ。\n今回はゴルディ側のお客さんの方が、ヴィックより少し多かったわ。",
  ui_story_5037_50370501_19_dialog_content = "でも、師匠のコンサート、この前よりずっとうまくいってたのに！\nどうしてゴルディお姉ちゃんの勝ちなの？",
  ui_story_5037_50370501_20_dialog_content = "簡単なことよ。ゴルディのコンサートは\n表現力が素晴らしかったの。",
  ui_story_5037_50370501_21_dialog_content = "振り付けに新しい試みがあったし、\n照明や舞台美術にも相当の工夫が見られたわ。",
  ui_story_5037_50370501_22_dialog_content = "なにより重要なことは…ゴルディの歌を聴いたお客さんの多くが\nそのまま「ディディ推し」になったことね。",
  ui_story_5037_50370501_23_dialog_content = "浮遊商会に押し寄せてきて、\nゴルディグッズを奪い合うように買っていったわ。",
  ui_story_5037_50370501_24_dialog_content = "ついでにゴルディとはまったく関係のない商品も、\n色々買いあさって行ったわね。",
  ui_story_5037_50370501_25_dialog_content = "「ディディ推し」から口コミが広がったことで…",
  ui_story_5037_50370501_26_dialog_content = "「ゴルディのコンサート」は、\n「影ノ街で一度は行っておきたい10の場所」の1つに選ばれているわ。",
  ui_story_5037_50370501_27_dialog_content = "スターウィッシュ・プロダクションにも、\n早く次のコンサートを開催してほしいって声がたくさん届いてるわ。",
  ui_story_5037_50370501_28_dialog_content = "まだ知らないかもしれないけど、卒業コンサートのチケットが、\nもうほとんど手に入らないくらい大人気になってるの。",
  ui_story_5037_50370501_29_dialog_content = "それってつまり、もうビラ配りは必要ないってことですか！？",
  ui_story_5037_50370501_30_dialog_content = "私も番組放送前に、スターウィッシュ・プロダクションの\n投資の元手が回収できるなんて思ってもみなかったわ～。",
  ui_story_5037_50370501_31_dialog_content = "そういうことだから、これからは2人とも、\n自分たちで宣伝活動をする必要はないわ。",
  ui_story_5037_50370501_32_dialog_content = "ステージづくりに専念して、\n最高の状態で最後のコンサートに備えてちょうだい！",
  ui_story_5037_50370501_33_dialog_content = "ありがとう、シェオルさん。",
  ui_story_5037_50370501_34_dialog_content = "今まで以上に努力して、最高のステージで\nシェオルさんとファンのみんなの応援に応えてみせるわ！",
  ui_story_5037_50370501_35_dialog_content = "あら…ヴィック、返事が聞こえないようだけど？",
  ui_story_5037_50370501_36_dialog_content = "俺はこの辺でギブアップしていいか？",
  ui_story_5037_50370501_37_dialog_content = "せっかく負けちまったことだしな？\n頼むよ、俺を早めに帰らせてくれ！",
  ui_story_5037_50370501_38_dialog_content = "…信じない。あたしは信じない！",
  ui_story_5037_50370501_39_dialog_content = "どうせ…どうせ、みんなしてフィアと師匠をイジメてるんでしょ！",
  ui_story_5037_50370501_40_dialog_content = "分かってるんだからね！",
  ui_story_5037_50370501_41_dialog_content = "この番組、台本があるんでしょ？",
  ui_story_5037_50370501_42_dialog_content = "リアリティ番組に台本ですって？",
  ui_story_5037_50370501_43_dialog_content = "…フィアちゃん、あなた、本当に賢い子ね。",
  ui_story_5037_50370501_44_dialog_content = "えっ…ト、トーゼンでしょ！えへへ！",
  ui_story_5037_50370501_45_dialog_content = "…え？でも待って。それってつまり…？",
  ui_story_5037_50370501_46_dialog_content = "リアリティ番組に台本を用意しておくなんてこと、\nどうして思いつかなかったのかしら？",
  ui_story_5037_50370501_47_dialog_content = "そうすれば、もっと早く元を取れたかもしれないわ。",
  ui_story_5037_50370501_48_dialog_content = "…でもね、フィアプロデューサー。\n今回の結果にウソやヤラセは一つもないわ。",
  ui_story_5037_50370501_49_dialog_content = "どうしても信じられないって言うなら、\nあとで撮影したステージ映像を確認するといいわ。",
  ui_story_5037_50370501_50_dialog_content = "それを観ても、まだ何か問題があったと思うのなら…\nいつでも私のところへ来てちょうだい。",
  ui_story_5037_50370501_51_dialog_content = "<color=#828282>しばらくして</color>",
  ui_story_5037_50370501_52_dialog_content = "いったいどうやって…？\nこんなステキなステージ、どうやって作ったの！？",
  ui_story_5037_50370501_53_dialog_content = "1秒で服が変わった！？",
  ui_story_5037_50370501_54_dialog_content = "あっ、突然観客席に出てきて…\n今度は空を飛んでステージに戻った！？",
  ui_story_5037_50370501_55_dialog_content = "ゴルディお姉ちゃんのコンサートに比べたら、\n師匠のコンサート、ちょっとダメなんてものじゃない…",
  ui_story_5037_50370501_56_dialog_content = "これじゃ師匠、前にデビューできなかったわけね…",
  ui_story_5037_50370501_57_dialog_content = "オホン…オホン！",
  ui_story_5037_50370501_58_dialog_content = "だが、これで分かったろ？\n師匠にいくら才能があったって、本物のアイドルにゃ勝てっこないのさ。",
  ui_story_5037_50370501_59_dialog_content = "今から負けを認めても遅くはない！\nさあ、荷物をまとめて帰るぞ～！",
  ui_story_5037_50370501_60_dialog_content = "待って！",
  ui_story_5037_50370501_61_dialog_content = "師匠に言われなくたって、\n自分でもよく分かってるよ…",
  ui_story_5037_50370501_62_dialog_content = "今回のコンサートで勝てなかったのは、\n師匠のせいじゃない。",
  ui_story_5037_50370501_63_dialog_content = "…師匠の練習の見張りばかりして、\nステージ作りや演出をおろそかにしちゃったフィアのせい。",
  ui_story_5037_50370501_64_dialog_content = "フィア、ずっと、コンサート成功のカギは\n師匠だと思ってた…",
  ui_story_5037_50370501_65_dialog_content = "でも、ゴルディお姉ちゃんのコンサートを観てわかった。\nコンサートって、こんなふうに作るものだったんだ！",
  ui_story_5037_50370501_66_dialog_content = "ねえ、師匠。\n今日の師匠のパフォーマンス、ホントによかったと思う。",
  ui_story_5037_50370501_67_dialog_content = "だからこそ、フィアが完璧なステージを\n用意できなかったのがいけなかったの。",
  ui_story_5037_50370501_68_dialog_content = "俺にとっちゃ、無事に終わっただけで上出来ってもんだ。\nだからそう気にするなって。な？さ、帰ろうぜ…",
  ui_story_5037_50370501_69_dialog_content = "ダメ！フィアはまだ帰れない！",
  ui_story_5037_50370501_70_dialog_content = "まだ最後のコンサートが残ってるんだよ。\n巻き返すチャンスはきっとある！",
  ui_story_5037_50370501_71_dialog_content = "師匠のアイドルになるって言う夢、\nフィアが絶対、悔いが残らないようにかなえてみせるから！",
  ui_story_5037_50370501_72_dialog_content = "…んん？",
  ui_story_5037_50370501_73_dialog_content = "コンサートの映像、私も観たわ。",
  ui_story_5037_50370501_74_dialog_content = "ヴィック、あなたのパフォーマンス、\nもうプロのレベルと言っていいわ。",
  ui_story_5037_50370501_75_dialog_content = "ただ、曲の振り付けが甘くて、\nあなたの魅力を十分に引き出せてなかったと思うの。",
  ui_story_5037_50370501_76_dialog_content = "え、ホントに？どの曲？",
  ui_story_5037_50370501_77_dialog_content = "それは…そうね、あとで私の感想をまとめておくから、\nそれを見せてあげるわね。",
  ui_story_5037_50370501_78_dialog_content = "そうそう、最近バラードを1曲書いたんだけど、\nヴィックに合ってるんじゃないかなって思うから…",
  ui_story_5037_50370501_79_dialog_content = "それも一緒に持ってくるわね！",
  ui_story_5037_50370501_80_dialog_content = "うん、ありがとう！",
  ui_story_5037_50370501_81_dialog_content = "でも…ホントにいいの？",
  ui_story_5037_50370501_82_dialog_content = "ライバルなのに、どうして協力してくれるの？",
  ui_story_5037_50370501_83_dialog_content = "アイドルっていうのはね、\nみんなに希望とやさしさを届ける仕事なの。",
  ui_story_5037_50370501_84_dialog_content = "それなのに、自分の近くにいる人にやさしくできなかったら、\nアイドルって言えるかしら？",
  ui_story_5037_50370501_85_dialog_content = "確かインタビューの時にも、\nゴルディが言ってたわ…",
  ui_story_5037_50370501_86_dialog_content = "ライバルじゃないわ。\nヴィックは同じアイドルとして一緒に頑張る仲間よ。",
  ui_story_5037_50370501_87_dialog_content = "かっこいい…",
  ui_story_5037_50370501_88_dialog_content = "すっごくかっこいい！！",
  ui_story_5037_50370501_89_dialog_content = "本物のアイドルって、そういうものだったんだ！",
  ui_story_5037_50370501_90_dialog_content = "あっ！！",
  ui_story_5037_50370501_91_dialog_content = "だったら、この前のインタビューであたしが師匠に言わせたことなんて、\nゴルディお姉ちゃんに比べたらただのお笑いじゃ…？",
  ui_story_5037_50370501_92_dialog_content = "（フィア、いったい何を言わせたんだろう…？）",
  ui_story_5037_50370501_93_dialog_content = "リリカお姉ちゃん、このあいだ撮影した事前インタビュー、\nカットしてもう一回やり直せないかな？",
  ui_story_5037_50370501_94_dialog_content = "それは難しいわね…",
  ui_story_5037_50370501_95_dialog_content = "だって、これはリアリティ番組だもの！",
  ui_story_5037_50370501_96_dialog_content = "キャロ！ちょっと来て！",
  ui_story_5037_50370501_97_dialog_content = "ルルル！",
  ui_story_5037_50370501_98_dialog_content = "な、何をする気！？",
  ui_story_5037_50370501_99_dialog_content = "キャロにかまれたって、\nぜったい言う通りにはしないからねー！",
  ui_story_5037_50370501_100_dialog_content = "ああっ、逃げないでー！",
  ui_story_5037_50370501_101_dialog_content = "やり直させてくれれば、\nキャロと遊ばせてあげるから！",
  ui_story_5037_50370501_102_dialog_content = "おい…？\nフィアのヤツ、俺のこと完全に忘れてやしないか？",
  ui_story_5037_50370501_103_dialog_content = "まぁいいか、これでやっとゆっくり眠れるぞ…",
  ui_story_5037_50370501_104_dialog_content = "じゃ、またな～！",
  ui_story_5037_50370501_105_dialog_content = "ふぅ…PlayerNameプロデューサー、\n今回のコンサートも無事に終わったわね。",
  ui_story_5037_50370501_106_dialog_content = "ゴルディ、本当にお疲れ様！",
  ui_story_5037_50370501_107_dialog_content = "今日のコンサート、とっても良かったよ！\n史上最高って言ってもいいんじゃないかな？",
  ui_story_5037_50370501_108_dialog_content = "PlayerNameプロデューサー、\nそんなに甘い評価をしちゃダメよ？",
  ui_story_5037_50370501_109_dialog_content = "だって、まだ最後のコンサートが残ってるでしょ？",
  ui_story_5037_50370501_110_dialog_content = "あはは、そうだったね。\n最高のコンサートは、いつだって次のコンサートだ！",
  ui_story_5037_50370501_111_dialog_content = "ふふふっ、大きく出たわね。",
  ui_story_5037_50370501_112_dialog_content = "もしかして、最後のコンサートのテーマ、もう決まってるの？",
  ui_story_5037_50370501_113_dialog_content = "あっ、そうだった！\n急いで予定表を作らなくちゃ。",
  ui_story_5037_50370501_114_dialog_content = "ゴルディ、僕のことは気にしないで、\n早く戻ってゆっくり休んでね！",
  ui_story_5037_50370501_115_dialog_content = "は～い。プロデューサーも、早めに休んでね！",
  ui_story_5037_50370501_116_dialog_content = "…ねぇ、マシュマロ。",
  ui_story_5037_50370501_117_dialog_content = "ワン！",
  ui_story_5037_50370501_118_dialog_content = "コンサート会場に、スリがいたみたいなの。",
  ui_story_5037_50370501_119_dialog_content = "あなたは気付いてた？",
  ui_story_5037_50370501_120_dialog_content = "ワンワン！",
  ui_story_5037_50370501_121_dialog_content = "私のコンサートで悪事を働くなんて…",
  ui_story_5037_50370501_122_dialog_content = "マシュマロ、準備はいい？",
  ui_story_5037_50370501_123_dialog_content = "今夜は手早く片付けるわ。\n正義の裁きを下してあげる！",
  ui_story_5037_50370501_124_dialog_content = "ワンワン！",
  ui_story_5037_50370501_125_dialog_content = "第2回コンサート終了後の友人インタビュー。\nレディー…",
  ui_story_5037_50370501_126_dialog_content = "アクション！！",
  ui_story_5037_50370501_127_dialog_content = "前回と同じく10点満点とすると、今回のコンサートには何点をつけますか？",
  ui_story_5037_50370501_128_dialog_content = "12点！満点以上ね！",
  ui_story_5037_50370501_129_dialog_content = "ほぼ10点かしら。",
  ui_story_5037_50370501_130_dialog_content = "想像したくもないわ…\nあの人がステージで歌ったり踊ったりだなんて…",
  ui_story_5037_50370501_131_dialog_content = "点数なんてつけたくないわ。",
  ui_story_5037_50370501_132_dialog_content = "なぜって…あの大バカ2人に調子に乗ってもらったら困るもの。",
  ui_story_5037_50370501_133_dialog_content = "相手のコンサートについては、どう思いましたか？",
  ui_story_5037_50370501_134_dialog_content = "10点満点！",
  ui_story_5037_50370501_135_dialog_content = "ヴィックさんたちのステージも完璧だったわ。\nただ、ゴルディのコンサートの方が盛り上がった印象ね。",
  ui_story_5037_50370501_136_dialog_content = "9点ね。",
  ui_story_5037_50370501_137_dialog_content = "観てないわ。フィアたちよりひどかったとか？",
  ui_story_5037_50370501_138_dialog_content = "友人に何か伝えたいことは？",
  ui_story_5037_50370501_139_dialog_content = "がんばれ、PlayerName！空ファンの皆も応援してるわよ～！",
  ui_story_5037_50370501_140_dialog_content = "努力は決して裏切らないものよ。",
  ui_story_5037_50370501_141_dialog_content = "確か、賞金が出るんでしょ？",
  ui_story_5037_50370501_142_dialog_content = "必ず勝って、賞金を持って帰ってきなさい！",
  ui_story_5037_50370501_143_dialog_content = "でないと…ふっ、ふふ…",
  ui_story_5037_50370501_144_dialog_content = "あ、あの！すみません！\n触手をカメラに巻き付けるのはやめてくださ～い！",
  ui_story_5037_50370601_1_dialog_content = "卒業コンサート、PlayerNameチーム事前インタビュー。\nレディー…",
  ui_story_5037_50370601_2_dialog_content = "アクション！！",
  ui_story_5037_50370601_3_dialog_content = "最後のコンサートのテーマを聞かせていただけますか？",
  ui_story_5037_50370601_4_dialog_content = "卒業コンサートのテーマは「咲き誇る青春」です。",
  ui_story_5037_50370601_5_dialog_content = "でもみんな、安心してね！",
  ui_story_5037_50370601_6_dialog_content = "「卒業コンサート」とは言ってるけど、\nスターウィッシュ・プロダクションから「卒業」しちゃうわけじゃないの。",
  ui_story_5037_50370601_7_dialog_content = "その通り！「芽生え」に始まって、\n「春を待つツボミ」から「咲き誇る青春」までの3回のコンサートは…",
  ui_story_5037_50370601_8_dialog_content = "リアリティ番組の枠の中で、視聴者の皆に\nアイドルっていう職業がどんなものかを見せただけです。",
  ui_story_5037_50370601_9_dialog_content = "番組が終わった後も、ゴルディはアイドルとして\n皆の前で歌い続けるので、安心してください。",
  ui_story_5037_50370601_10_dialog_content = "そうそう、これからもみんなに\nもっといい作品とステージを届けるわ！",
  ui_story_5037_50370601_11_dialog_content = "その時のプロデューサーは、\n僕じゃないですけどね。",
  ui_story_5037_50370601_12_dialog_content = "…",
  ui_story_5037_50370601_13_dialog_content = "ふふふ、そうね。\nスターウィッシュ・プロダクションのプロデューサーになるのって、大変なの。",
  ui_story_5037_50370601_14_dialog_content = "事務所に履歴書を送って、\nいろ～んな審査に合格しなきゃいけないの。",
  ui_story_5037_50370601_15_dialog_content = "PlayerNameみたいな優秀なプロデューサーでも、\n不安になっちゃうくらいにね！",
  ui_story_5037_50370601_16_dialog_content = "こういう番組でもなかったら、才能ある人がたくさんいる影ノ街で\n僕がプロデューサーになるチャンスなんて…きっと無かったと思います。",
  ui_story_5037_50370601_17_dialog_content = "これが終われば、僕はきっともう他の誰かとコンサートを競い合うことも、\n本物のプロデューサーになることもないと思います。",
  ui_story_5037_50370601_18_dialog_content = "だけど、ゴルディと一緒に成長できただけで十分です。",
  ui_story_5037_50370601_19_dialog_content = "PlayerName…",
  ui_story_5037_50370601_20_dialog_content = "もう、感動的なセリフは、もっと後に残しておかなきゃ！",
  ui_story_5037_50370601_21_dialog_content = "ゴルディさんは、今回のコンサートのために何か新曲を作られましたか？",
  ui_story_5037_50370601_22_dialog_content = "もちろん！",
  ui_story_5037_50370601_23_dialog_content = "そうね…プロデューサーから卒業コンサートのテーマを\n「咲き誇る青春」に決めたって聞いて…",
  ui_story_5037_50370601_24_dialog_content = "思わず自分に問いかけたの。青春って、なんだろうって。",
  ui_story_5037_50370601_25_dialog_content = "そうしたら、頭の中にたくさんのシーンが浮かんできて…",
  ui_story_5037_50370601_26_dialog_content = "何の悩みもなく影ノ街で駆け回って遊んでたことかな？",
  ui_story_5037_50370601_27_dialog_content = "眠気を我慢しながら、教室で授業を聞いてた時のことかな？",
  ui_story_5037_50370601_28_dialog_content = "それとも、早くから独り立ちして、\n生活と夢のために苦労しながら働いてたことかな？…って。",
  ui_story_5037_50370601_29_dialog_content = "でも、分かったの。青春に決まった形はないんだって。",
  ui_story_5037_50370601_30_dialog_content = "どんな青春もみんな、輝きを放って、咲き誇ってるの！",
  ui_story_5037_50370601_31_dialog_content = "頭に浮かんだたくさんのシーンを歌にして、\nこのコンサートでみんなに披露するわ！",
  ui_story_5037_50370601_32_dialog_content = "PlayerNameプロデューサーはその新曲について、\nどう思いますか？",
  ui_story_5037_50370601_33_dialog_content = "ゴルディの作った曲は全部いい曲です！",
  ui_story_5037_50370601_34_dialog_content = "でも、今度のコンサートで披露する新曲は、\nその中でも最高にすばらしい曲ばかりだと思ってます。",
  ui_story_5037_50370601_35_dialog_content = "特に『さよなら』っていう曲は…",
  ui_story_5037_50370601_36_dialog_content = "シェオルさんがこの番組の\nエンディングテーマに選んだぐらい、いい曲です。",
  ui_story_5037_50370601_37_dialog_content = "人生にはたくさんの別れがつきものだけど…",
  ui_story_5037_50370601_38_dialog_content = "私はいつだって、みんなの目の前で、\nみんなと一緒に成長できるように頑張り続けるわ！",
  ui_story_5037_50370601_39_dialog_content = "だからみんなも、ゴルディの成長を見守ってね！",
  ui_story_5037_50370601_40_dialog_content = "ゴルディさんからプロデューサーに何か伝えたいことはありますか？",
  ui_story_5037_50370601_41_dialog_content = "え？まだコンサートが終わってないのに？",
  ui_story_5037_50370601_42_dialog_content = "大丈夫よ、構わないわ。",
  ui_story_5037_50370601_43_dialog_content = "それに、コンサートが終わっちゃったら、\nかえって伝えられなくなっちゃいそうだもの。えへへ…",
  ui_story_5037_50370601_44_dialog_content = "えっ？",
  ui_story_5037_50370601_45_dialog_content = "オッホン、私からプロデューサーに伝えたいことはね…",
  ui_story_5037_50370601_46_dialog_content = "ずっと一緒にいてくれてありがとう…かしら。",
  ui_story_5037_50370601_47_dialog_content = "正直に言うと…ずっと独りでやってきたから、\nプロデューサーがいるってこと、最初はなじめなかったの。",
  ui_story_5037_50370601_48_dialog_content = "最初の頃は、ただ番組の都合で\nプロデューサーになってもらっただけだったけど…",
  ui_story_5037_50370601_49_dialog_content = "一緒にやっていくうちに、PlayerNameは何も分からない状態から、\n本物のプロデューサーに成長したわ。",
  ui_story_5037_50370601_50_dialog_content = "スケジュールを立てたり、ゴシップ記者の対応をしてくれただけじゃない。\n細かいところにまで気を遣って、一緒にコンサートを作ってくれた…",
  ui_story_5037_50370601_51_dialog_content = "私が安心して、創作と練習に専念できるようにね。",
  ui_story_5037_50370601_52_dialog_content = "今じゃもう、PlayerNameプロデューサーなしでは\nやっていけない気がするわ。",
  ui_story_5037_50370601_53_dialog_content = "番組が終わったら、私のプロデューサーじゃなくなっちゃうけど…\nそれでもPlayerNameに、伝えておきたいの。",
  ui_story_5037_50370601_54_dialog_content = "あなたは私の、最高のプロデューサーよ！",
  ui_story_5037_50370601_55_dialog_content = "――今のところはね、なんて。",
  ui_story_5037_50370601_56_dialog_content = "でも、ゴルディもプロデューサーをつけたのは\n僕が初めてなんだよね？",
  ui_story_5037_50370601_57_dialog_content = "話はまだ終わってないわよ～？\n…今後あなたがどこへ行こうと、何をしようと、私、信じてるの！",
  ui_story_5037_50370601_58_dialog_content = "あなたならきっと、何をしてもすばらしい結果を残せるわ。",
  ui_story_5037_50370601_59_dialog_content = "その時には私も…",
  ui_story_5037_50370601_60_dialog_content = "私も…",
  ui_story_5037_50370601_61_dialog_content = "ゴルディ？",
  ui_story_5037_50370601_62_dialog_content = "…コホンッ…",
  ui_story_5037_50370601_63_dialog_content = "<size=30>リリカ、今のところ――カットしてね。\nもう一度やり直すわ！</size>",
  ui_story_5037_50370601_64_dialog_content = "――今後あなたがどこへ行こうと、何をしようと、私、信じてるの！",
  ui_story_5037_50370601_65_dialog_content = "あなたならきっと、何をしてもすばらしい結果を残せるわ。",
  ui_story_5037_50370601_66_dialog_content = "その時には私も、自分の選んだ道で、\nPlayerNameがしてくれたことに応えられる結果を出してみせるわ！",
  ui_story_5037_50370601_67_dialog_content = "プロデューサーからゴルディさんに何か伝えたいことはありますか？",
  ui_story_5037_50370601_68_dialog_content = "僕もゴルディに感謝したい気持ちでいっぱいだよ。",
  ui_story_5037_50370601_69_dialog_content = "君が励ましてくれたからこそ、\n自分でも思いもよらなかったことをやり遂げられたんだ。",
  ui_story_5037_50370601_70_dialog_content = "ゴルディと僕が今日まで一緒にやってこられたのは、\nきっとゴルディ本人がすごく輝いてるからだよ。",
  ui_story_5037_50370601_71_dialog_content = "もし、僕に何か進歩や成長したところがあるのだとしたら…",
  ui_story_5037_50370601_72_dialog_content = "それは間違いなく、ゴルディの放つ輝きのおかげだ！",
  ui_story_5037_50370601_73_dialog_content = "ありがとう、PlayerNameも輝いてるわよ！",
  ui_story_5037_50370601_74_dialog_content = "ゴルディ、ずっとそばにはいられないかもしれないけど…",
  ui_story_5037_50370601_75_dialog_content = "君はずっとずっとキラキラ輝く、完璧なアイドルだよ！",
  ui_story_5037_50370601_76_dialog_content = "君なら最高に輝くアイドルになって、\nアストラ大陸の伝説になれる！",
  ui_story_5037_50370601_77_dialog_content = "僕もずっと、ゴルディが進む道に幸運があるよう祈り続けるよ。",
  ui_story_5037_50370601_78_dialog_content = "卒業コンサート、PlayerNameチーム事前インタビュー…",
  ui_story_5037_50370601_79_dialog_content = "カット！",
  ui_story_5037_50370601_80_dialog_content = "…",
  ui_story_5037_50370601_81_dialog_content = "…",
  ui_story_5037_50370601_82_dialog_content = "…あら？なんでこんなに空気が重いの？",
  ui_story_5037_50370601_83_dialog_content = "あたし、何か聞いちゃいけないことでも聞いちゃった…？",
  ui_story_5037_50370601_84_dialog_content = "今のインタビュー、もしかしてメンタルに影響しちゃった？",
  ui_story_5037_50370601_85_dialog_content = "あ！コンサートでのパフォーマンスに支障が出ちゃう…？",
  ui_story_5037_50370601_86_dialog_content = "いいえ、安心して、リリカ。",
  ui_story_5037_50370601_87_dialog_content = "ほら！ぜんぜん、元気にしてるでしょ？",
  ui_story_5037_50370601_88_dialog_content = "よかった！笑顔が戻ったわね！",
  ui_story_5037_50370601_89_dialog_content = "PlayerNameプロデューサー！",
  ui_story_5037_50370601_90_dialog_content = "はい。",
  ui_story_5037_50370601_91_dialog_content = "ありがとう！",
  ui_story_5037_50370601_92_dialog_content = "あっ、また取り逃しちゃった…",
  ui_story_5037_50370601_93_dialog_content = "ふぅ…",
  ui_story_5037_50370601_94_dialog_content = "ミント味ののど飴、やっぱり落ち着くわ。",
  ui_story_5037_50370601_95_dialog_content = "すみません、ゴルディのコンサート会場はどっちですか？",
  ui_story_5037_50370601_96_dialog_content = "え、お客さんがどうして舞台裏に？",
  ui_story_5037_50370601_97_dialog_content = "この通路をまっすぐ行って、\n突き当りを左に行けば会場よ。",
  ui_story_5037_50370601_98_dialog_content = "あれ！？超ラッキー！\nゴルディ本人じゃないか！？",
  ui_story_5037_50370601_99_dialog_content = "え、本当に？服にサインをもらえませんか！？",
  ui_story_5037_50370601_100_dialog_content = "北境から観に来たんです！",
  ui_story_5037_50370601_101_dialog_content = "俺もだ！R・Wから来たんだぜ！",
  ui_story_5037_50370601_102_dialog_content = "うちは雲島からや！",
  ui_story_5037_50370601_103_dialog_content = "俺はユーフォリアから来たんだ！",
  ui_story_5037_50370601_104_dialog_content = "皆さん、すみません。",
  ui_story_5037_50370601_105_dialog_content = "コンサート終了後にサインと写真撮影の時間が用意されていますので…",
  ui_story_5037_50370601_106_dialog_content = "まずはコンサート会場でお待ちください。\nもうすぐ始まりますよ。",
  ui_story_5037_50370601_107_dialog_content = "サインと写真撮影の時間があるんですか！？",
  ui_story_5037_50370601_108_dialog_content = "へえ～、じゃあ先に会場に行ってるか！",
  ui_story_5037_50370601_109_dialog_content = "急げ、先に会場に着けばサイン入りの写真をもらえるぞ！",
  ui_story_5037_50370601_110_dialog_content = "あわてないでください、\n全員にチャンスがありますので！",
  ui_story_5037_50370601_111_dialog_content = "ふぅ～…皆、急いで行っちゃった。\n僕の話なんて聞こえなかったみたいだ。",
  ui_story_5037_50370601_112_dialog_content = "それにしても、今回は本当にお客さんが多いね。\n色々な所から集まってるみたいだ。",
  ui_story_5037_50370601_113_dialog_content = "ゴルディのアストラ大陸一周ツアーも、\n夢じゃなさそうだね！",
  ui_story_5037_50370601_114_dialog_content = "あれ？ゴルディ、どうしたの？",
  ui_story_5037_50370601_115_dialog_content = "緊張しちゃった…",
  ui_story_5037_50370601_116_dialog_content = "な、なんだか、初めてステージに上がった時みたいな気分なの…",
  ui_story_5037_50370601_117_dialog_content = "ゴルディ、会場のお客さんたちを見て。",
  ui_story_5037_50370601_118_dialog_content = "みんな君のことが好きで、来てくれたんだ！",
  ui_story_5037_50370601_119_dialog_content = "ゴルディはこれだけのファンに好かれる価値のある人なんだよ。",
  ui_story_5037_50370601_120_dialog_content = "PlayerNameプロデューサー…",
  ui_story_5037_50370601_121_dialog_content = "…ええ、そうね！",
  ui_story_5037_50370601_122_dialog_content = "私はもう、あの時の私じゃないわ。",
  ui_story_5037_50370601_123_dialog_content = "PlayerNameプロデューサー。\nしっかり見ててね。",
  ui_story_5037_50370601_124_dialog_content = "私は最高の状態で…",
  ui_story_5037_50370601_125_dialog_content = "このコンサートをやり遂げて見せる！",
  ui_story_5037_50370701_1_dialog_content = "これで、無事に全部、終わりだね…",
  ui_story_5037_50370701_2_dialog_content = "セットや照明にミスやトラブルはなかったし、\nゴルディの歌は言うまでもなく、すばらしかった。",
  ui_story_5037_50370701_3_dialog_content = "それ以外の色々やりたかった細かい演出も全部完璧にできたし。",
  ui_story_5037_50370701_4_dialog_content = "お客さんもゴルディの名前を叫びながら、\n会場から出ていくのをギリギリまで惜しんでた…",
  ui_story_5037_50370701_5_dialog_content = "ステージとお客さんが一体になって、\n会場全体が感動と興奮に包まれてて…最高のステージだった。",
  ui_story_5037_50370701_6_dialog_content = "なのに、どうしてだろう…？",
  ui_story_5037_50370701_7_dialog_content = "何だか心にぽっかり穴が開いたような…",
  ui_story_5037_50370701_8_dialog_content = "あっ！",
  ui_story_5037_50370701_9_dialog_content = "…うっかり忘れるところだった！\nシェオルさんの最終結果発表！",
  ui_story_5037_50370701_10_dialog_content = "このままじゃ遅刻かも！？",
  ui_story_5037_50370701_11_dialog_content = "ぜえ…はあ…はあ…",
  ui_story_5037_50370701_12_dialog_content = "すみません、遅くなりました！",
  ui_story_5037_50370701_13_dialog_content = "あらあら、PlayerNameプロデューサー。もう少し遅かったら\n対決を辞退したのかと思うところだったわよ～？",
  ui_story_5037_50370701_14_dialog_content = "ところで…ゴルディはどうしたの？\nどうしてあなた1人なのかしら？",
  ui_story_5037_50370701_15_dialog_content = "ゴルディなら、ファンの対応でまだ会場にいます。",
  ui_story_5037_50370701_16_dialog_content = "フン、それがどうしたの？\n師匠だって、写真撮影でファンに囲まれて大変なんだから！",
  ui_story_5037_50370701_17_dialog_content = "フフ、うちのアイドル、どちらも人気者のようね。",
  ui_story_5037_50370701_18_dialog_content = "いい事だわ、本当に。",
  ui_story_5037_50370701_19_dialog_content = "2人が戻ったら、直接おめでとうって伝えないとね。",
  ui_story_5037_50370701_20_dialog_content = "でもこの後、映画製作会社の社長と商談があるのよねぇ…",
  ui_story_5037_50370701_21_dialog_content = "シェオルさん、本当に忙しそうですね…",
  ui_story_5037_50370701_22_dialog_content = "だったら待つことないよ。\n早く結果を聞かせて！",
  ui_story_5037_50370701_23_dialog_content = "あらあら、ずいぶんせっかちさんね。",
  ui_story_5037_50370701_24_dialog_content = "ま、悪いことじゃないわ。\nヴィックの卒業コンサートから見ても…",
  ui_story_5037_50370701_25_dialog_content = "フィアちゃん、この短期間で\n立派にコンサートの企画能力を身に付けたものね。",
  ui_story_5037_50370701_26_dialog_content = "中間コンサートの時に比べて、今度のコンサートには\n舞台効果の面でも、選曲の面でも、飛躍的な進歩があったわ。",
  ui_story_5037_50370701_27_dialog_content = "当然でしょ？\nフィア、本当に頑張ったもん！",
  ui_story_5037_50370701_28_dialog_content = "ゴルディの方も、前回の時点でこれ以上のものはないってぐらいの\nステージをすでに見せてくれてたにも関わらず…",
  ui_story_5037_50370701_29_dialog_content = "PlayerNameプロデューサーは舞台設計の面で、\nそれ以上のものを見せてくれたわ。",
  ui_story_5037_50370701_30_dialog_content = "ゴルディの作った新曲も、\nお客さんに真心と感動を届けられたみたいね。",
  ui_story_5037_50370701_31_dialog_content = "チェ～っ！\nほめられるのはフィアだけだと思ってたのに…",
  ui_story_5037_50370701_32_dialog_content = "…ってことで、\n今回の対決の結果はフィアチームが…",
  ui_story_5037_50370701_33_dialog_content = "なになになになに？",
  ui_story_5037_50370701_34_dialog_content = "フィアが勝ったの！？",
  ui_story_5037_50370701_35_dialog_content = "フィアちゃん…あせっちゃいけないわ。",
  ui_story_5037_50370701_36_dialog_content = "今回の対決の結果はフィアチームが…ほんのわずかに及ばず。\nPlayerNameチームの勝ちよ。",
  ui_story_5037_50370701_37_dialog_content = "票数の差、2ケタも無かったのよ。",
  ui_story_5037_50370701_38_dialog_content = "えっ？",
  ui_story_5037_50370701_39_dialog_content = "3回のコンサート成績を総合して、\n最終的に賞金は…",
  ui_story_5037_50370701_40_dialog_content = "<size=45>PlayerNameとゴルディのものよ！</size>",
  ui_story_5037_50370701_41_dialog_content = "…",
  ui_story_5037_50370701_42_dialog_content = "ううっ、うわあああ～ん…",
  ui_story_5037_50370701_43_dialog_content = "フィア、ホントに…すっごく頑張ったのに…",
  ui_story_5037_50370701_44_dialog_content = "ロクデナシの師匠をずっと見張って、\n夜遅くまで、コンサートの企画の仕方を勉強したのに…",
  ui_story_5037_50370701_45_dialog_content = "ほらほら、フィアプロデューサー。\n発表はまだ終わってないのよ？",
  ui_story_5037_50370701_46_dialog_content = "えっ？",
  ui_story_5037_50370701_47_dialog_content = "フィアとヴィックの2人も本当に頑張って、ファンをたくさん集めたわ。\nおかげで、浮遊商会で売ってるグッズの売り上げも好調よ。",
  ui_story_5037_50370701_48_dialog_content = "というわけで、2人の頑張りに対して…",
  ui_story_5037_50370701_49_dialog_content = "特別に賞金を出しちゃうわ！",
  ui_story_5037_50370701_50_dialog_content = "特別に…",
  ui_story_5037_50370701_51_dialog_content = "賞金、もらえるの！？",
  ui_story_5037_50370701_52_dialog_content = "うう、よかった…フィアと師匠の努力もムダじゃなかったんだ！\n頑張れば、かならず報われるんだね…ううぅ…うわあああ～ん！",
  ui_story_5037_50370701_53_dialog_content = "フフ、まだまだ続きがあるわよ～？",
  ui_story_5037_50370701_54_dialog_content = "さらにこの番組の製作過程で、\n「努力したアイドル賞」を獲得したのは…",
  ui_story_5037_50370701_55_dialog_content = "ヴィックよ！",
  ui_story_5037_50370701_56_dialog_content = "え？師匠！？師匠が賞をとったの？",
  ui_story_5037_50370701_57_dialog_content = "「最も努力したアイドル」！？",
  ui_story_5037_50370701_58_dialog_content = "師匠がゴルディお姉ちゃんに勝って、\nみんなから認められるなんて！",
  ui_story_5037_50370701_59_dialog_content = "ダメ師匠もなかなかやるじゃない！",
  ui_story_5037_50370701_60_dialog_content = "ふふん、それもこれもフィアとキャロの努力あってこそだよね！",
  ui_story_5037_50370701_61_dialog_content = "ル～！",
  ui_story_5037_50370701_62_dialog_content = "PlayerName、ごめんね～？\nあたしたちが賞をもらっちゃって！えへへへ…",
  ui_story_5037_50370701_63_dialog_content = "ヴィック、確かにすごく頑張ってたもんね。\n賞をもらって当然だと思うよ。",
  ui_story_5037_50370701_64_dialog_content = "…続いて、「プロデューサー賞」の受賞者は…",
  ui_story_5037_50370701_65_dialog_content = "<size=45>PlayerNameよ！</size>",
  ui_story_5037_50370701_66_dialog_content = "えっ？",
  ui_story_5037_50370701_67_dialog_content = "…僕が？",
  ui_story_5037_50370701_68_dialog_content = "…！！！",
  ui_story_5037_50370701_69_dialog_content = "ふ、フンだ！",
  ui_story_5037_50370701_70_dialog_content = "…フィアも認めてあげるよ。たしかにPlayerNameの方が覚えも早かったし、\nスキルも身につけてた。",
  ui_story_5037_50370701_71_dialog_content = "でも、フィアより年上だもん！\nそんなのトーゼンだもんね！",
  ui_story_5037_50370701_72_dialog_content = "フィアがPlayerNameと同じ歳ぐらいになったら、\nぜったいPlayerNameよりすごいプロデューサーになってるもん！！",
  ui_story_5037_50370701_73_dialog_content = "フィア…？",
  ui_story_5037_50370701_74_dialog_content = "どこかに行っちゃった…",
  ui_story_5037_50370701_75_dialog_content = "大丈夫よ、きっと師匠のところへ行ったんでしょう。",
  ui_story_5037_50370701_76_dialog_content = "あの子、口先では強がってるけど、\n根は優しい子だもの。",
  ui_story_5037_50370701_77_dialog_content = "シェオルさん、フィアのことをよく分かってるんですね。",
  ui_story_5037_50370701_78_dialog_content = "そうねぇ、私は空の末裔じゃないから、感知能力はないけど…",
  ui_story_5037_50370701_79_dialog_content = "PlayerNameより人の心は読めるのかもしれないわね？",
  ui_story_5037_50370701_80_dialog_content = "そうでもなきゃ、1人で今の浮遊商会を作り上げるなんて、\nできっこないでしょう？",
  ui_story_5037_50370701_81_dialog_content = "…",
  ui_story_5037_50370701_82_dialog_content = "リリカ。",
  ui_story_5037_50370701_83_dialog_content = "はーい！何かしら？",
  ui_story_5037_50370701_84_dialog_content = "あなたの撮影した素材、とっても素晴らしいわ。大満足よ。",
  ui_story_5037_50370701_85_dialog_content = "しっかり編集して、必ず多くの人を引きつける、\n魅力的な一本に仕上げてちょうだい。",
  ui_story_5037_50370701_86_dialog_content = "そうすればあなたも、\n監督として評価されてひっぱりだこになるわ。",
  ui_story_5037_50370701_87_dialog_content = "…ええ！きっといい編集をするわ！",
  ui_story_5037_50370701_88_dialog_content = "何か希望があれば、何でも言って！",
  ui_story_5037_50370701_89_dialog_content = "フフ、そうね…コンサートが終わった後も、\n色々と面白いことが起こるはずよ。",
  ui_story_5037_50370701_90_dialog_content = "しっかりと目を光らせて、\n最後の最後までいい素材を逃さないようにしてちょうだいね？",
  ui_story_5037_50370701_91_dialog_content = "分かったわ！",
  ui_story_5037_50370701_92_dialog_content = "安心して、リリカにお任せ！",
  ui_story_5037_50370701_93_dialog_content = "PlayerName、あなたもこのまま\nプロデューサーになりたいなら、私は大歓迎よ。",
  ui_story_5037_50370701_94_dialog_content = "その場合は忘れずに\n履歴書を事務所に送ってちょうだいね？",
  ui_story_5037_50370701_95_dialog_content = "は、はい！",
  ui_story_5037_50370701_96_dialog_content = "さて、時間もちょうどいいわ…\n私は次の用事があるから。",
  ui_story_5037_50370701_97_dialog_content = "いい知らせを楽しみにしてるわ～。",
  ui_story_5037_50370701_98_dialog_content = "ありがとうございました！",
  ui_story_5037_50370701_99_dialog_content = "ふぅ…僕のプロデューサーとしての仕事は、\nここで終わりかな？",
  ui_story_5037_50370701_100_dialog_content = "…",
  ui_story_5037_50370701_101_dialog_content = "リリカ？\nどうして僕にカメラを向けてるの？",
  ui_story_5037_50370701_102_dialog_content = "だって、撮影がまだ終わってないもの。",
  ui_story_5037_50370701_103_dialog_content = "終わってない以上、仕事を続けなきゃ！",
  ui_story_5037_50370701_104_dialog_content = "でも、コンサートはもう終わったし、\n僕ももうやることはないし…",
  ui_story_5037_50370701_105_dialog_content = "いったい何を撮るの？",
  ui_story_5037_50370701_106_dialog_content = "もちろん、あなたを撮るのよ！",
  ui_story_5037_50370701_107_dialog_content = "プロデューサー賞の受賞者さんをね！",
  ui_story_5037_50370701_108_dialog_content = "えっと…な、何かした方がいい？",
  ui_story_5037_50370701_109_dialog_content = "それはあなた自身の心に聞かなきゃ。",
  ui_story_5037_50370701_110_dialog_content = "僕自身の？",
  ui_story_5037_50370701_111_dialog_content = "そう。たとえば…今、一番会いたい人は誰？",
  ui_story_5037_50370701_112_dialog_content = "一番会いたい人？",
  ui_story_5037_50370701_113_dialog_content = "そうか。だって今日は、まだ終わってない！",
  ui_story_5037_50370701_114_dialog_content = "会いたい人…そうだなあ…",
  ui_story_5037_50370701_115_option_content = "ゴルディ",
  ui_story_5037_50370701_116_dialog_content = "僕たちが勝ったってこと、早く知らせてあげなくちゃ！",
  ui_story_5037_50370701_117_option_content = "ヴィックとフィア",
  ui_story_5037_50370701_118_dialog_content = "ヴィックにおめでとうって言いたいな！",
  ui_story_5037_50370701_119_option_content = "バイスとカレン",
  ui_story_5037_50370701_120_dialog_content = "2人にお礼を言いたいな…",
  ui_story_5037_50370701_121_dialog_content = "僕たちが勝ったってこと、\n早くゴルディに知らせてあげなくちゃ！",
  ui_story_5037_50370701_122_dialog_content = "それから、伝えたいことも…",
  ui_story_5037_50370701_123_dialog_content = "あ！",
  ui_story_5037_50370701_124_dialog_content = "それはもう事前インタビューで伝えてたっけ！？",
  ui_story_5037_50370701_125_dialog_content = "じゃ、じゃあ、賞金の話でもしようかな…？",
  ui_story_5037_50370701_126_dialog_content = "「ゴルディ、これでたくさん服が買えるね！」とか…？",
  ui_story_5037_50370701_127_dialog_content = "うーん、それもヘンだなぁ…",
  ui_story_5037_50370701_128_dialog_content = "「ゴルディ、賞金をもらえたのは君のおかげだよ！」…かな？",
  ui_story_5037_50370701_129_dialog_content = "うーん、これもダメ。何だかよそよそしい気がする。",
  ui_story_5037_50370701_130_dialog_content = "「ゴルディ、お疲れ様！」…",
  ui_story_5037_50370701_131_dialog_content = "ちょっとアッサリしすぎかな…",
  ui_story_5037_50370701_132_dialog_content = "ディディ！ディディ！",
  ui_story_5037_50370701_133_dialog_content = "みんな、ありがとう～！",
  ui_story_5037_50370701_134_dialog_content = "1人ずつよ、転ばないように気を付けて～！",
  ui_story_5037_50370701_135_dialog_content = "コンサートが終わってもうだいぶ経つのに、\nまだファンがこんなに！？",
  ui_story_5037_50370701_136_dialog_content = "ゴルディとファンの皆、楽しそうに話してるなぁ…\n僕の入るスキはなさそうだ。",
  ui_story_5037_50370701_137_dialog_content = "ここはジャマしないでおこう。",
  ui_story_5037_50370701_138_dialog_content = "そうだ！今のうちにゴルディと何を話すか、\n考えておこう！",
  ui_story_5037_50370701_139_dialog_content = "<size=45>PlayerNameプロデューサー！</size>",
  ui_story_5037_50370701_140_dialog_content = "あれ？今、ゴルディが僕を呼んだような…？",
  ui_story_5037_50370701_141_dialog_content = "<size=50>PlayerNameプロデューサー、早く早く～！</size>",
  ui_story_5037_50370701_142_dialog_content = "僕にもファンとトークしてってことかな…？",
  ui_story_5037_50370701_143_dialog_content = "うーん…やめておこう。\nだって、ゴルディのファンは僕になんか興味ないだろうし…",
  ui_story_5037_50370701_144_dialog_content = "みんな、ちょっと待っててね～。\nすぐに戻ってくるから！",
  ui_story_5037_50370701_145_dialog_content = "ディディ！ディディ！",
  ui_story_5037_50370701_146_dialog_content = "えっ？",
  ui_story_5037_50370701_147_dialog_content = "えっ、ゴルディがこっちに向かって…？",
  ui_story_5037_50370701_148_dialog_content = "PlayerNameプロデューサー、ここで何してるの？",
  ui_story_5037_50370701_149_dialog_content = "ぼ、僕はただ、結果を伝えたいなって…",
  ui_story_5037_50370701_150_dialog_content = "その、僕たち、勝ったよ！",
  ui_story_5037_50370701_151_dialog_content = "PlayerNameプロデューサー、\n今頃知ったの？ちょっと遅いんじゃな～い？",
  ui_story_5037_50370701_152_dialog_content = "えっ、ゴルディは知ってたの？",
  ui_story_5037_50370701_153_dialog_content = "ふふ、最後の1曲を歌ってる時から分かってたわ…",
  ui_story_5037_50370701_154_dialog_content = "3回のコンサート、私たちは何の悔いもなくやり遂げた。",
  ui_story_5037_50370701_155_dialog_content = "私たちは自分たちに勝ったの。\nそれだけでもう、大勝利よ！",
  ui_story_5037_50370701_156_dialog_content = "そっか、ゴルディはそんなふうに考えてたんだね。",
  ui_story_5037_50370701_157_dialog_content = "さっきからたくさんのファンの子が、ステージの設計がよかったって言ってるの。\nあなたもみんなと話してみない？",
  ui_story_5037_50370701_158_dialog_content = "でも、僕は…",
  ui_story_5037_50370701_159_dialog_content = "ファンを待たせるなんて、\nアイドルもアイドルプロデューサーも失格よ～？",
  ui_story_5037_50370701_160_dialog_content = "みんな、お待たせ～！",
  ui_story_5037_50370701_161_dialog_content = "今からみんなに、ある人を紹介するわね。",
  ui_story_5037_50370701_162_dialog_content = "ジャジャジャジャーン！",
  ui_story_5037_50370701_163_dialog_content = "こ、こんにちは！",
  ui_story_5037_50370701_164_dialog_content = "そう、この恥ずかしがり屋さんが\nウワサの空の末裔――PlayerNameよ！",
  ui_story_5037_50370701_165_dialog_content = "しかも、PlayerNameはコンサートに向けて\nずっと私のそばで色々助けてくれたプロデューサーでもあるの！",
  ui_story_5037_50370701_166_dialog_content = "みんながステキなコンサートを観られたのは、\nPlayerNameのおかげなのよ！",
  ui_story_5037_50370701_167_dialog_content = "いや、それは言いすぎだよ…\nプロデューサーといっても、僕はちょっとかじった程度だし。",
  ui_story_5037_50370701_168_dialog_content = "そのモヤシみたいな人がゴルディのプロデューサー？\nちょっと意外ですね…",
  ui_story_5037_50370701_169_dialog_content = "人は見かけによらねぇって言うが、\n小僧、やるじゃねーか！",
  ui_story_5037_50370701_170_dialog_content = "僕はデビュー当時からのディディ推しなんです。",
  ui_story_5037_50370701_171_dialog_content = "今までもゴルディは何をやってもすばらしかったんですが、\nあなたというプロデューサーが付いてから…",
  ui_story_5037_50370701_172_dialog_content = "彼女はさらに成長したような気がします。\nしかも、将来の方向性を見つけたって感じすらしますね！",
  ui_story_5037_50370701_173_dialog_content = "そういうのは、俺にはよく分かんねぇが…",
  ui_story_5037_50370701_174_dialog_content = "ただ、今まで生きてきて、\nこんないいコンサートは観たことなかったぜ！",
  ui_story_5037_50370701_175_dialog_content = "PlayerNameプロデューサーのおかげだ！",
  ui_story_5037_50370701_176_dialog_content = "PlayerName！PlayerName！PlayerName！PlayerName！",
  ui_story_5037_50370701_177_dialog_content = "…",
  ui_story_5037_50370701_178_dialog_content = "（こんなに大勢の人が僕の名前を…\n何だか、照れちゃうなぁ…）",
  ui_story_5037_50370701_179_dialog_content = "（僕は裏方として、できることをやっただけ…\nこんなふうに表立ってほめられちゃってもいいのかな？）",
  ui_story_5037_50370701_180_dialog_content = "PlayerNameプロデューサー…",
  ui_story_5037_50370701_181_dialog_content = "あなたには、みんなから讃えられるだけの価値があるわ。",
  ui_story_5037_50370701_182_dialog_content = "今までずっと、ホントにお疲れ様！",
  ui_story_5037_50370701_183_dialog_content = "（え？今、僕が何を考えてたか分かって…？）",
  ui_story_5037_50370701_184_dialog_content = "（おまけに、僕が言いたかったこと、\n先に言われちゃった！！）",
  ui_story_5037_50370701_185_dialog_content = "ほら、PlayerNameプロデューサー。\nみんなからあなたに伝えたいことがあるみたいよ！",
  ui_story_5037_50370701_186_dialog_content = "え？",
  ui_story_5037_50370701_187_dialog_content = "PlayerNameプロデューサー、サインください！",
  ui_story_5037_50370701_188_dialog_content = "「空ファン」じゃねぇが、\nPlayerNameプロデューサーのサイン、俺ももらいてぇな！",
  ui_story_5037_50370701_189_dialog_content = "私も！",
  ui_story_5037_50370701_190_dialog_content = "僕も！",
  ui_story_5037_50370701_191_dialog_content = "え…ええ！？",
  ui_story_5037_50370701_192_dialog_content = "こんなことなら、\nちゃんとサインの練習しておけばよかった…",
  ui_story_5037_50370701_193_dialog_content = "ひゃあ！",
  ui_story_5037_50370701_194_dialog_content = "フィア、こんなにたくさんの白夜コイン、初めて見たよ！",
  ui_story_5037_50370701_195_dialog_content = "お金を数えて手が震えるって、こんな感じなんだね…",
  ui_story_5037_50370701_196_dialog_content = "それにしてもシェオルさんって、ホント太っ腹だよね！",
  ui_story_5037_50370701_197_dialog_content = "フィア、誰と話してるの？",
  ui_story_5037_50370701_198_dialog_content = "他に誰もいないみたいだけど。",
  ui_story_5037_50370701_199_dialog_content = "誰って、ダメ師匠と話してるに決まってるでしょ！",
  ui_story_5037_50370701_200_dialog_content = "師匠？",
  ui_story_5037_50370701_201_dialog_content = "…って、あれ？PlayerNameに言われて気づいたけど…",
  ui_story_5037_50370701_202_dialog_content = "ダメ師匠、またテーブルの下で寝てる！",
  ui_story_5037_50370701_203_dialog_content = "キャロ、引きずり出して！",
  ui_story_5037_50370701_204_dialog_content = "ルッ！",
  ui_story_5037_50370701_205_dialog_content = "あっ、ていうか…",
  ui_story_5037_50370701_206_dialog_content = "PlayerName、どうしてここにいるの？",
  ui_story_5037_50370701_207_dialog_content = "ドアが開いてたから、そのまま入ってきたんだよ。",
  ui_story_5037_50370701_208_dialog_content = "ええっ！？あたし、よりにもよってお金を数えてる時に\nドアを閉め忘れてたの！？",
  ui_story_5037_50370701_209_dialog_content = "大丈夫だよ、僕がさっき閉めておいたから。",
  ui_story_5037_50370701_210_dialog_content = "コ、コソドロとか入ってきてないよね…？",
  ui_story_5037_50370701_211_dialog_content = "たいへん！もう一回数え直さなきゃ！",
  ui_story_5037_50370701_212_dialog_content = "ルル！",
  ui_story_5037_50370701_213_dialog_content = "うう…もう練習はこりごりだ…",
  ui_story_5037_50370701_214_dialog_content = "ヴィック？",
  ui_story_5037_50370701_215_dialog_content = "モジャ、逃げるぞ！",
  ui_story_5037_50370701_216_dialog_content = "まだ寝てる…？ということは、寝言？",
  ui_story_5037_50370701_217_dialog_content = "83、84、85…",
  ui_story_5037_50370701_218_dialog_content = "フィア、何回数えたって白夜コインは増えないよ？",
  ui_story_5037_50370701_219_dialog_content = "それより、師匠の様子を見てあげたら？",
  ui_story_5037_50370701_220_dialog_content = "…そもそも、キャロに引きずられてるのに、\nなんでちっとも反応しないの！？",
  ui_story_5037_50370701_221_dialog_content = "ちょっと待ってて！100まで数えてから…",
  ui_story_5037_50370701_222_dialog_content = "98、99、100！",
  ui_story_5037_50370701_223_dialog_content = "…で、なにか言った？",
  ui_story_5037_50370701_224_dialog_content = "…うん。早く師匠の様子を見てあげたらって言ったんだ。",
  ui_story_5037_50370701_225_dialog_content = "全然反応がないみたいだから…",
  ui_story_5037_50370701_226_dialog_content = "え？師匠なら寝てるだけだよ。",
  ui_story_5037_50370701_227_dialog_content = "ここ数日でだいぶヘトヘトになってたから…",
  ui_story_5037_50370701_228_dialog_content = "ま、今までロクに働いてこなかったからトーゼンだけど！",
  ui_story_5037_50370701_229_dialog_content = "いかん、早く逃げないと！！",
  ui_story_5037_50370701_230_dialog_content = "あ、ヴィック、目が覚めた？",
  ui_story_5037_50370701_231_dialog_content = "…PlayerName？なんでここにいるんだ…？",
  ui_story_5037_50370701_232_dialog_content = "…いや、それより逃げるぞ！キャロがおかしくなっちまったんだ！\n俺にずっと練習をさせようと…！",
  ui_story_5037_50370701_233_dialog_content = "それはたぶん、夢じゃないかな？",
  ui_story_5037_50370701_234_dialog_content = "ん？フィアもいるのか…？",
  ui_story_5037_50370701_235_dialog_content = "それに目の前にある、白夜コインの山はどういうことだ？",
  ui_story_5037_50370701_236_dialog_content = "…ははーん、さてはこれも夢だな！？",
  ui_story_5037_50370701_237_dialog_content = "だがまあ、さっきまでの夢に比べたらいい夢だな…",
  ui_story_5037_50370701_238_dialog_content = "うーん…どうすれば、夢じゃないって\nヴィックに分かってもらえるんだろう…？",
  ui_story_5037_50370701_239_dialog_content = "ふふん！キャロの出番みたいだね！",
  ui_story_5037_50370701_240_dialog_content = "！！！",
  ui_story_5037_50370701_241_dialog_content = "おお！フィア、我が愛弟子よ！\n師匠は今、いつになく頭がハッキリしてるぞ！",
  ui_story_5037_50370701_242_dialog_content = "かわいそうに…\nヴィック、キャロ恐怖症になっちゃったみたいだね…",
  ui_story_5037_50370701_243_dialog_content = "ん？…ってことは、この白夜コインは本物か！",
  ui_story_5037_50370701_244_dialog_content = "シェオルさん、ホントに太っ腹だよ。",
  ui_story_5037_50370701_245_dialog_content = "あたしも師匠も何日か撮影されただけなのに、\nこんなにたくさんお金をくれて…",
  ui_story_5037_50370701_246_dialog_content = "それでこれなら、本物のアイドルはどれくらい稼げるんだろ？",
  ui_story_5037_50370701_247_dialog_content = "フィア、なんだって他人の稼ぎなんか気にするんだ？\n俺たちは俺たちらしく生きてりゃいいだろ。",
  ui_story_5037_50370701_248_dialog_content = "う～ん、それはそうかも…？",
  ui_story_5037_50370701_249_dialog_content = "師匠がマトモなこと言うなんて、めずらしい…",
  ui_story_5037_50370701_250_dialog_content = "それはさておき…これだけ金があれば、\n影ノ街に新しく開店したっていう豪華レストランで思いっきり食え――",
  ui_story_5037_50370701_251_dialog_content = "…それはダメ！",
  ui_story_5037_50370701_252_dialog_content = "なんでだ？",
  ui_story_5037_50370701_253_dialog_content = "ここのところ、ず～っとお前の言うことを聞いてただろ？",
  ui_story_5037_50370701_254_dialog_content = "練習だー、スタイル維持だーって言われて、\n長いことマトモな食事をとれてないんだ。",
  ui_story_5037_50370701_255_dialog_content = "おかげで大金が入ったんだし、\n自分にごほうびをやるぐらい、いいじゃないか？",
  ui_story_5037_50370701_256_dialog_content = "はあ…師匠はやっぱり、ことの重大さを理解してないんだね。",
  ui_story_5037_50370701_257_dialog_content = "このお金、たしかにたくさんあるように\n見えるかもしれないけど…",
  ui_story_5037_50370701_258_dialog_content = "師匠がずっと先延ばしにしてるドラゴライオンのおやつ代でしょ、\n普段の食事代に家の修繕費、それからフィアへのツケを差し引いたら…",
  ui_story_5037_50370701_259_dialog_content = "半分以上消えちゃうんだよ。",
  ui_story_5037_50370701_260_dialog_content = "そのうえ師匠が頼りないから、\n今後の収入も見込めないってことを考えると…",
  ui_story_5037_50370701_261_dialog_content = "このぐらいのお金じゃ、\nそのうちすぐに底をついちゃうの！",
  ui_story_5037_50370701_262_dialog_content = "今後の収入？",
  ui_story_5037_50370701_263_dialog_content = "ヴィック、アイドルの素質があるんだから、\nアイドルを続けるっていうのは？",
  ui_story_5037_50370701_264_dialog_content = "おいおい、PlayerName。\nカンベンしてくれよ。",
  ui_story_5037_50370701_265_dialog_content = "この数日もっただけでも、俺にとっちゃあ奇跡なんだ。\nこれからも毎日こんなことを続けろって言うのか？",
  ui_story_5037_50370701_266_dialog_content = "ムリムリ、考えただけで毎晩悪夢を見そうだぜ…",
  ui_story_5037_50370701_267_dialog_content = "…PlayerNameの言う通りかも！",
  ui_story_5037_50370701_268_dialog_content = "どうせ師匠は家にいたって、珍獣のお世話するワケでも\n仕事を見つけてお金を稼げるワケでもないんだから…",
  ui_story_5037_50370701_269_dialog_content = "いっそ、このまま本物のアイドルになればいいんじゃない！？",
  ui_story_5037_50370701_270_dialog_content = "撮った番組が放送されれば、\nきっと師匠のファンも増えるはずだし！",
  ui_story_5037_50370701_271_dialog_content = "ああフィア、俺のかわいい愛弟子よ…",
  ui_story_5037_50370701_272_dialog_content = "頼むからそれだけは止めてくれ！",
  ui_story_5037_50370701_273_dialog_content = "はいはい、師匠は本物のアイドルとしてデビュー決定！",
  ui_story_5037_50370701_274_dialog_content = "フィア！？",
  ui_story_5037_50370701_275_dialog_content = "ほら師匠、まだ時間はあるんだし練習再開だよ！",
  ui_story_5037_50370701_276_dialog_content = "もう、そんな力は俺のどこにも…",
  ui_story_5037_50370701_277_dialog_content = "ほらキャロ、一緒に師匠の練習に付き合ってあげようね～！",
  ui_story_5037_50370701_278_dialog_content = "か、カンベンしてくれ――！！",
  ui_story_5037_50370701_279_dialog_content = "あっ、逃げた…あんなに走って…",
  ui_story_5037_50370701_280_dialog_content = "やっぱり、力が残ってないっていうのはウソだったんだ！\n師匠！！走る元気があるなら練習だよ！！",
  ui_story_5037_50370701_281_dialog_content = "ヴィック…",
  ui_story_5037_50370701_282_dialog_content = "…がんばって！！",
  ui_story_5037_50370701_283_dialog_content = "それにしても、プロデューサー賞…",
  ui_story_5037_50370701_284_dialog_content = "へへ…まさか、僕自身も賞をもらえるなんて思わなかったな。",
  ui_story_5037_50370701_285_dialog_content = "始めたばかりの頃は何も分からなくて、\nゴルディに迷惑かけちゃうんじゃないかって思ってたけど…",
  ui_story_5037_50370701_286_dialog_content = "最終的にちゃんと3回のコンサートをやり遂げて、\nしかもシェオルさんにも認めてもらえたなんて！",
  ui_story_5037_50370701_287_dialog_content = "バイスとカレンにも報告しようっと！きっと驚くだろうな…",
  ui_story_5037_50370701_288_dialog_content = "たぶん、この辺にいるはずなんだけど…",
  ui_story_5037_50370701_289_dialog_content = "この部屋かな？",
  ui_story_5037_50370701_290_dialog_content = "<color=#828282>トントントン！</color>",
  ui_story_5037_50370701_291_dialog_content = "今いいかな？入るよ。",
  ui_story_5037_50370701_292_dialog_content = "この部屋、いつもは明かりがついてるのに…\n今日はどうして真っ暗なんだろう？",
  ui_story_5037_50370701_293_dialog_content = "バイス？カレン？おかしいな…ここじゃないのかな？",
  ui_story_5037_50370701_294_dialog_content = "<color=#828282>パッ！</color>",
  ui_story_5037_50370701_295_dialog_content = "え！？",
  ui_story_5037_50370701_296_dialog_content = "おめでとう！",
  ui_story_5037_50370701_297_dialog_content = "卒業コンサート、大成功だったわね～！",
  ui_story_5037_50370701_298_dialog_content = "PlayerName、見事にやり遂げたわね。\nおめでとう。",
  ui_story_5037_50370701_299_dialog_content = "え？これは…",
  ui_story_5037_50370701_300_dialog_content = "最近新しく開いた高級レストランに依頼して、\n料理と飲み物を用意してもらったわ。",
  ui_story_5037_50370701_301_dialog_content = "特大サイズのショートケーキもあるわよ！",
  ui_story_5037_50370701_302_dialog_content = "PlayerName、プロデューサーの勉強を始めて、\nここしばらくまともな食事をとっていなかったでしょう？",
  ui_story_5037_50370701_303_dialog_content = "だから、私たちでサプライズパーティーを準備したのよ。\nほら、好きなものばかりでしょ？",
  ui_story_5037_50370701_304_dialog_content = "バイス、カレン…",
  ui_story_5037_50370701_305_dialog_content = "でも、いつの間に…？",
  ui_story_5037_50370701_306_dialog_content = "全然気づかなかったよ！",
  ui_story_5037_50370701_307_dialog_content = "ふふふ、実はだいぶ前から考えてたの。",
  ui_story_5037_50370701_308_dialog_content = "今日はずっと、コンサートの準備で忙しかったでしょう？\nおかげで、準備する「隙」がたっぷりあったわ。",
  ui_story_5037_50370701_309_dialog_content = "…ということは、対決の結果、もう知ってるんだね？",
  ui_story_5037_50370701_310_dialog_content = "ううん、それはまだ知らないわ。",
  ui_story_5037_50370701_311_dialog_content = "でも…もし僕たちが負けてたら、\nせっかく準備したパーティがムダになっちゃうんじゃ…？",
  ui_story_5037_50370701_312_dialog_content = "いいえ。私とバイスは、今日の結果がどうであろうと…",
  ui_story_5037_50370701_313_dialog_content = "自分の限界を超えようと、\nあなたが努力していたことを知っているわ。",
  ui_story_5037_50370701_314_dialog_content = "あきらめずに勉強を続けて、最後までやり遂げた。\nそれだけでもう、十分すごいことじゃない！",
  ui_story_5037_50370701_315_dialog_content = "だから、負けたとしてもお祝いしなきゃ！",
  ui_story_5037_50370701_316_dialog_content = "2人とも…もう！\nそんな感動させることを言うから…",
  ui_story_5037_50370701_317_dialog_content = "…目にホコリが入っちゃったよ。",
  ui_story_5037_50370701_318_dialog_content = "…それで、勝負はどうだったの？",
  ui_story_5037_50370701_319_dialog_content = "そこは大事じゃないんじゃなかった？",
  ui_story_5037_50370701_320_dialog_content = "フフフッ、それはPlayerNameを信じてるって意味よ！",
  ui_story_5037_50370701_321_dialog_content = "さっき部屋の外で、「きっと驚くだろう」と言っているのは\n聞こえていたけれど、どういう驚きの報告があるのかしら？",
  ui_story_5037_50370701_322_dialog_content = "えへへ…対決は、僕とゴルディの勝ちだよ！",
  ui_story_5037_50370701_323_dialog_content = "あと、シェオルさんから「プロデューサー賞」をもらったんだ！",
  ui_story_5037_50370701_324_dialog_content = "へえ！そんな賞もあったのね！？",
  ui_story_5037_50370701_325_dialog_content = "彼女は人の才能を見抜く力を持っているわ。\nきっと、PlayerNameの伸びしろを見抜いていたのよ。",
  ui_story_5037_50370701_326_dialog_content = "…ところで、その賞って賞金はあるの？",
  ui_story_5037_50370701_327_dialog_content = "賞金は…ないけど…",
  ui_story_5037_50370701_328_dialog_content = "フフフ、それもそうよね。\nでも、名誉っていうのは、お金で買えるものじゃないわ。",
  ui_story_5037_50370701_329_dialog_content = "それに実績ができたのだから、\n今後の仕事が見つけやすくなるでしょうね。",
  ui_story_5037_50370701_330_dialog_content = "そうよね。PlayerNameの今の能力なら、\n本物のプロデューサーと肩を並べられるもの。",
  ui_story_5037_50370701_331_dialog_content = "君たちが色々と助けてくれなかったら、\n僕も今日までやり遂げる自信はなかったよ。",
  ui_story_5037_50370701_332_dialog_content = "バイス、カレン。期間中ずっとそばにいてくれて、\n見返りも無いのに色々と手助けしてくれて、本当にありがとう。",
  ui_story_5037_50370701_333_dialog_content = "うーん？1つ間違ってるわね。",
  ui_story_5037_50370701_334_dialog_content = "え？",
  ui_story_5037_50370701_335_dialog_content = "私たちは「期間中」そばにいたわけじゃないもの。",
  ui_story_5037_50370701_336_dialog_content = "そうよ。いつも一緒にいるでしょう？",
  ui_story_5037_50370701_337_dialog_content = "あっ、それもそうだね…",
  ui_story_5037_50370701_338_dialog_content = "じゃあ、言い直すよ！",
  ui_story_5037_50370701_339_dialog_content = "その必要は無いわ、私たち3人の仲じゃない。\nそんな堅苦しいことは抜きにしましょ！",
  ui_story_5037_50370701_340_dialog_content = "それに…知ってる？",
  ui_story_5037_50370701_341_dialog_content = "資料を調べに戻った時に見たんだけど、\n啓光の皆もアイドルに興味を持ちはじめてるみたいなの。",
  ui_story_5037_50370701_342_dialog_content = "ビビアン長官なんて、何かイベントを企画してるみたいよ。\n啓光を代表するアイドルをデビューさせたいんですって！",
  ui_story_5037_50370701_343_dialog_content = "え！？啓光のアイドル…？",
  ui_story_5037_50370701_344_dialog_content = "いななけ、このシーンに命を吹き込め！",
  ui_story_5037_50370701_345_dialog_content = "おや？どうした、静まりかえっているな。",
  ui_story_5037_50370701_346_dialog_content = "さては私の演技に圧倒されて、拍手も歓声も忘れてしまったのかな？",
  ui_story_5037_50370701_347_dialog_content = "ハーッハッハッハッ！",
  ui_story_5037_50370701_348_dialog_content = "うっ…",
  ui_story_5037_50370701_349_dialog_content = "あら？PlayerName、何か考え事？\n急に冷や汗をかいてるみたいね…？",
  ui_story_5037_50370701_350_dialog_content = "何でもないよ！",
  ui_story_5037_50370701_351_dialog_content = "ほ、本当に！啓光でアイドルのイベントなんて、\nきっと盛り上がるだろうな～って思っただけ！",
  ui_story_5037_50370701_352_dialog_content = "私も、白夜城での選考会の開催を\n城主様に提案してみようかと考えているところよ。",
  ui_story_5037_50370701_353_dialog_content = "え？でも、白夜城の貴族の人たち、許可してくれるかな…？",
  ui_story_5037_50370701_354_dialog_content = "難しいでしょうね。",
  ui_story_5037_50370701_355_dialog_content = "ただ、私も今回さまざまな経験をして、\n多くのことを学んだわ。",
  ui_story_5037_50370701_356_dialog_content = "正々堂々と己の魅力を他人に見せつけるというのも、\n悪いことではないと思うようになったの。",
  ui_story_5037_50370701_357_dialog_content = "長い間悩んでいたことが、突然消えた気分よ。",
  ui_story_5037_50370701_358_dialog_content = "あっ、分かったわ！",
  ui_story_5037_50370701_359_dialog_content = "カレンが追い求めている「王道」にまた一歩近づいたのね！",
  ui_story_5037_50370701_360_dialog_content = "えっと…アイドルと王道と、どういう関係があるの？",
  ui_story_5037_50370701_361_dialog_content = "…言われてみれば、一理あるわ。",
  ui_story_5037_50370701_362_dialog_content = "えっ？",
  ui_story_5037_50370701_363_dialog_content = "ああ、ちょっとちょっと！料理が冷めちゃうわ。\n早く食べましょ！",
  ui_story_5037_50370701_364_dialog_content = "それもそうね。まずは乾杯しましょう。",
  ui_story_5037_50370701_365_dialog_content = "PlayerName、「プロデューサー賞」おめでとう！",
  ui_story_5037_50370701_366_dialog_content = "乾杯！",
  ui_story_5037_50370701_367_option_content = "乾杯！",
  ui_story_5037_50370801_1_dialog_content = "ダンスの特訓に歌の練習、記者の取材…\nそれから、握手会会場のオーナーにも連絡しないと…",
  ui_story_5037_50370801_2_dialog_content = "？",
  ui_story_5037_50370801_3_dialog_content = "オーナーには少なくともお昼と夕食の間に連絡したいけど、\n午後には取材が来るし…",
  ui_story_5037_50370801_4_dialog_content = "…",
  ui_story_5037_50370801_5_dialog_content = "ゴルディの休憩時間も確保して…っと、それから、\n着替えとメイク直しの時間も必要だから、こうするしかないか…",
  ui_story_5037_50370801_6_dialog_content = "…？",
  ui_story_5037_50370801_7_dialog_content = "でも…これじゃ、朝から晩まで働き詰めだ！",
  ui_story_5037_50370801_8_dialog_content = "PlayerName？",
  ui_story_5037_50370801_9_dialog_content = "うわあ！？",
  ui_story_5037_50370801_10_dialog_content = "なんだ、ゴルディか。\nびっくりしたよ…",
  ui_story_5037_50370801_11_dialog_content = "さっきから何をブツブツ言ってるの？",
  ui_story_5037_50370801_12_dialog_content = "なんだか元気がないみたいね、\n私と一緒にダンスの練習でもする？",
  ui_story_5037_50370801_13_dialog_content = "運動はスタイルと健康を保つのにいいのよ！",
  ui_story_5037_50370801_14_dialog_content = "プロデューサーの健康状態はアイドルの仕事にも、\nコンサートの最終的なクオリティにも影響するんだから！",
  ui_story_5037_50370801_15_dialog_content = "はぁ…今、スケジュールを作ってたんだけどね…",
  ui_story_5037_50370801_16_dialog_content = "毎日やることがありすぎて、1つ終わったかと思うと、\nすぐに次の仕事に入らなきゃならない状況で…",
  ui_story_5037_50370801_17_dialog_content = "少しでも休憩時間を確保したいんだけど、\nそれもままならないんだ！",
  ui_story_5037_50370801_18_dialog_content = "やっぱり僕が、プロデューサーとしてまだまだヒヨッコだから…",
  ui_story_5037_50370801_19_dialog_content = "いいえ、PlayerNameは十分よくやってるわ！",
  ui_story_5037_50370801_20_dialog_content = "まだ初めて数日なのに、日常の仕事は難なくこなせるようになってるじゃない。\nそれって、誰にでもできることじゃないわ！",
  ui_story_5037_50370801_21_dialog_content = "だから、気を落としちゃダメ。マシュマロでもなでておく？",
  ui_story_5037_50370801_22_dialog_content = "フワフワしてて、やわらかいのよ。\nきっと心が癒されるわ。",
  ui_story_5037_50370801_23_dialog_content = "ワンワン！",
  ui_story_5037_50370801_24_dialog_content = "ありがとう。じゃあ、遠慮なく――",
  ui_story_5037_50370801_25_dialog_content = "あ、待って！",
  ui_story_5037_50370801_26_dialog_content = "どうしたの？",
  ui_story_5037_50370801_27_dialog_content = "明日取材に来る新聞社に連絡して、\n時間を決めなきゃいけないんだった！",
  ui_story_5037_50370801_28_dialog_content = "ごめん、僕はこれで！",
  ui_story_5037_50370801_29_dialog_content = "…",
  ui_story_5037_50370801_30_dialog_content = "<color=#828282>しばらくして</color>",
  ui_story_5037_50370801_31_dialog_content = "ふぅ…よかった、間に合って。",
  ui_story_5037_50370801_32_dialog_content = "大手の新聞社だし、うっかり約束を破ったりしたら\nゴルディの評判に傷がついちゃうところだったよ。",
  ui_story_5037_50370801_33_dialog_content = "PlayerName、用事は済んだの？",
  ui_story_5037_50370801_34_dialog_content = "あ、ゴルディ！さっきはごめんね。\nあわてて立ち去っちゃって…",
  ui_story_5037_50370801_35_dialog_content = "気にしないで。\nだって、私のために忙しく動いてくれてるんだもの。",
  ui_story_5037_50370801_36_dialog_content = "プロデューサーって、本当に大変なんだね。\nここ数日で、少しずつ仕事のリズムには慣れてきたけど――",
  ui_story_5037_50370801_37_dialog_content = "仕事の中身が難しくって、なかなか慣れないや。",
  ui_story_5037_50370801_38_dialog_content = "ただスケジュールを立てるだけなら、\nそう難しいことはないんだろうけど…",
  ui_story_5037_50370801_39_dialog_content = "ゴシップ記者相手にうまく話を引き出されないよう\n気をつけなきゃいけないし…",
  ui_story_5037_50370801_40_dialog_content = "すごく、難しいね…",
  ui_story_5037_50370801_41_dialog_content = "ホントにお疲れ様。",
  ui_story_5037_50370801_42_dialog_content = "でも、どんなに疲れてても、\nPlayerNameはきちんと自分の仕事をやり遂げてるわ。",
  ui_story_5037_50370801_43_dialog_content = "それだけでも、もうとってもすごいことよ！",
  ui_story_5037_50370801_44_dialog_content = "ありがとう。\nほめられたおかげで、疲れも吹っ飛んだ気がするよ。",
  ui_story_5037_50370801_45_dialog_content = "ふふ、でしょ？\nみんなね、誰かの応援が必要なのよ！",
  ui_story_5037_50370801_46_dialog_content = "そういえば、ゴルディは今までずっと\n1人で頑張ってきたんだよね？",
  ui_story_5037_50370801_47_dialog_content = "アイドルの仕事だけじゃなく、\nプロデュースも自分でこなしてたんだよね…",
  ui_story_5037_50370801_48_dialog_content = "練習しながらスケジュールも組んで、\nゴシップの対応もしなきゃいけないなんて…",
  ui_story_5037_50370801_49_option_content = "考えただけでも、本当すごいよ！",
  ui_story_5037_50370801_50_dialog_content = "ふふ…それくらい、大したことないわ！",
  ui_story_5037_50370801_51_option_content = "考えただけでも、大変そうだね…",
  ui_story_5037_50370801_52_dialog_content = "そうね。でも、乗り越えて来られたわ。",
  ui_story_5037_50370801_53_dialog_content = "私だって、1人2役は簡単なことじゃなかったけどね。",
  ui_story_5037_50370801_54_dialog_content = "大変なこともたくさんあったし、\n何度もあきらめようと思った時だってあるの。",
  ui_story_5037_50370801_55_dialog_content = "ゴルディもあきらめそうになった時があるの？\n想像がつかない…",
  ui_story_5037_50370801_56_dialog_content = "私たちだけの秘密よ！ほかの人に言っちゃダメだからね！",
  ui_story_5037_50370801_57_dialog_content = "絶対に言わないよ。僕はいま、君のプロデューサーなんだから。\n君の悪口を言いふらしたりしない、約束するよ！",
  ui_story_5037_50370801_58_dialog_content = "ふふ、それならよかった！",
  ui_story_5037_50370801_59_dialog_content = "…私ね、デビュー前はずっと1人で頑張ってたの。",
  ui_story_5037_50370801_60_dialog_content = "練習とスケジュールを立てるだけでも大変なのに、\nいつ出て来るか分からないゴシップ記者からも逃げなきゃいけなくて…",
  ui_story_5037_50370801_61_dialog_content = "あの頃は忙しくて、\n1、2時間しか眠れないこともよくあったわ！",
  ui_story_5037_50370801_62_dialog_content = "それで寝不足なのに、次の日も朝早くから起きて、\n前の日の練習でできなかった分を取り返そうとしたり…",
  ui_story_5037_50370801_63_dialog_content = "そんなに大変だったの！？",
  ui_story_5037_50370801_64_dialog_content = "僕も夜更かしは得意な方だけど…1、2時間しか寝られなかったら、\n次の日は布団から出ることもできないと思う…",
  ui_story_5037_50370801_65_dialog_content = "ふふ、それは私も同じよ。",
  ui_story_5037_50370801_66_dialog_content = "1日や2日ぐらいなら大丈夫だけど、\nこれが何年も続いたらどうしようって思ったりしたわ。",
  ui_story_5037_50370801_67_dialog_content = "練習が終わって、もう体力も気力も空っぽになるたび、\nそんなことを思ってた…",
  ui_story_5037_50370801_68_dialog_content = "でも、ゴルディは最後には高い壁を越えて、\n今の人気アイドルになったんだよね？",
  ui_story_5037_50370801_69_dialog_content = "ええ！",
  ui_story_5037_50370801_70_dialog_content = "あきらめそうになるたびに、幸運の弾丸を投げてたの。\n頭を下にして落ちたら、いいことがあるって願掛けして。",
  ui_story_5037_50370801_71_dialog_content = "幸運の弾丸は、いつも弾頭のほうを下にして落ちたわ。\nだからこうして、あきらめずに頑張って来て…今の私があるのよ！",
  ui_story_5037_50370801_72_dialog_content = "まさに不屈の精神だね…",
  ui_story_5037_50370801_73_dialog_content = "ふふ。",
  ui_story_5037_50370801_74_dialog_content = "でも、今は違うわ。",
  ui_story_5037_50370801_75_dialog_content = "私にはPlayerNameっていう、\n信頼できるプロデューサーがついてるもの。",
  ui_story_5037_50370801_76_dialog_content = "他のことを考える必要なしに、\n心置きなく練習にはげめてるわ！",
  ui_story_5037_50370801_77_dialog_content = "おかげで、すっごく成長できてるのよ！",
  ui_story_5037_50370801_78_dialog_content = "僕…本当に、君の助けになれてるの？",
  ui_story_5037_50370801_79_dialog_content = "もちろん！",
  ui_story_5037_50370801_80_dialog_content = "それなら…よかった！",
  ui_story_5037_50370801_81_dialog_content = "今までずっと、自分は何一つできてないヒヨッコで、\n君に迷惑しかかけてないんじゃないかって思ってたんだ。",
  ui_story_5037_50370801_82_dialog_content = "でも、君の話を聞いて…自信を取り戻せた気がする。",
  ui_story_5037_50370801_83_dialog_content = "これからも頑張って、いいプロデューサーになるよ。\nだからゴルディ、これからもよろしくね！",
  ui_story_5037_50370801_84_dialog_content = "こちらこそ！",
  ui_story_5037_50370901_1_dialog_content = "<color=#828282>午前中、練習の後</color>",
  ui_story_5037_50370901_2_dialog_content = "お疲れ様、PlayerName！",
  ui_story_5037_50370901_3_dialog_content = "午前の練習はこれで終了ね。\nお昼は少しゆっくり休みましょ。",
  ui_story_5037_50370901_4_dialog_content = "ゴルディこそ、お疲れ様！",
  ui_story_5037_50370901_5_dialog_content = "<color=#828282>トントントン！</color>",
  ui_story_5037_50370901_6_dialog_content = "どうぞ――",
  ui_story_5037_50370901_7_dialog_content = "PlayerName～、それからゴルディ～！",
  ui_story_5037_50370901_8_dialog_content = "ガルーさん！こんにちは！",
  ui_story_5037_50370901_9_dialog_content = "ガルー？どうしてここに？",
  ui_story_5037_50370901_10_dialog_content = "買い物に来たら、PlayerNameがプロデューサーをやってるって\n聞いたから、ついでに様子を見に来たってワケ！",
  ui_story_5037_50370901_11_dialog_content = "あ、あと、最新のゲームも持ってきたよ～！\nどう？負け犬クン、対戦しない？",
  ui_story_5037_50370901_12_dialog_content = "もちろん――",
  ui_story_5037_50370901_13_dialog_content = "あっ…やっぱり今日はやめとくよ。",
  ui_story_5037_50370901_14_dialog_content = "ええ？乗ってこないなんて珍しいね～。",
  ui_story_5037_50370901_15_dialog_content = "午後にもまだ予定がたくさん入ってるんだ。\nゲームに夢中になって時間を忘れたりしたら、大変なことになりそうだし。",
  ui_story_5037_50370901_16_dialog_content = "確かにね！\nじゃ、仕事のジャマはしないようにするよ～。",
  ui_story_5037_50370901_17_dialog_content = "頑張ってね～、PlayerName、ゴルディ！",
  ui_story_5037_50370901_18_dialog_content = "コンサート、楽しみにしてるから！",
  ui_story_5037_50370901_19_dialog_content = "ええ、楽しみにしててね！",
  ui_story_5037_50370901_20_dialog_content = "バイバ～イ！",
  ui_story_5037_50370901_21_dialog_content = "またね！",
  ui_story_5037_50370901_22_dialog_content = "よしっ、じゃあ僕も午後の準備を始めようかな。",
  ui_story_5037_50370901_23_dialog_content = "待って、今はお昼休みでしょ？\n休むときはしっかり休んで。仕事のことは考えちゃダメよ。",
  ui_story_5037_50370901_24_dialog_content = "それはそうかもだけど…でも、コンサートの日も近いんだよ？",
  ui_story_5037_50370901_25_dialog_content = "当日が近づいて、やることも多くなってるし…\n休み時間の返上ぐらい…",
  ui_story_5037_50370901_26_dialog_content = "…PlayerName、もしかしてここのところずっと、\nお昼休みや睡眠時間を削って仕事してる？",
  ui_story_5037_50370901_27_dialog_content = "うっ…そ、そうだね…",
  ui_story_5037_50370901_28_dialog_content = "それはダメよ！",
  ui_story_5037_50370901_29_dialog_content = "十分に休息をとらないと、効率が下がって、\n長い目で見たらかえっていい仕事ができなくなるの！",
  ui_story_5037_50370901_30_dialog_content = "そういうことだから、今まで休んでなかったぶん、\nPlayerName、今日の午後はお休み！",
  ui_story_5037_50370901_31_dialog_content = "少し外に出て新鮮な空気を吸えば、\nきっと元気が出てくるわ！",
  ui_story_5037_50370901_32_dialog_content = "いや、大丈夫だよ、本当に…",
  ui_story_5037_50370901_33_dialog_content = "反論は受けつけませ～ん！\nあなたの健康と効率的なお仕事のためよ！",
  ui_story_5037_50370901_34_dialog_content = "でも…プロデューサーが休んでたら、\n君はどうするの？",
  ui_story_5037_50370901_35_dialog_content = "安心して。今までずっと自分でやってたんだから、\nこれぐらいのこと、なんてことないわ！",
  ui_story_5037_50370901_36_dialog_content = "さ、そうと決まったら休んで。\n明日の朝まで事務所には戻らなくていいから！",
  ui_story_5037_50370901_37_dialog_content = "<color=#828282>バタン</color>",
  ui_story_5037_50370901_38_dialog_content = "（ゴルディに追い出されちゃった…）",
  ui_story_5037_50370901_39_dialog_content = "（こうなったら、ちょっと散歩でもして休もうかな）",
  ui_story_5037_50370901_40_dialog_content = "<color=#828282>数分後、カフェ店内</color>",
  ui_story_5037_50370901_41_dialog_content = "ご注文はいかがなさいますか？",
  ui_story_5037_50370901_42_dialog_content = "ええと…",
  ui_story_5037_50370901_43_dialog_content = "へえ、3色ケーキなんてあるんだ…",
  ui_story_5037_50370901_44_dialog_content = "私たちの目標は決められた期間のうちに、\n3回のコンサートを成功させることよ。",
  ui_story_5037_50370901_45_dialog_content = "…そうだ、まだコンサートは2回も残って…",
  ui_story_5037_50370901_46_dialog_content = "…また仕事のこと考えちゃった。\nいけないいけない…注文しなきゃ！",
  ui_story_5037_50370901_47_dialog_content = "…こっちの双子ケーキも…",
  ui_story_5037_50370901_48_dialog_content = "コンサートが始まったら、お客さんたちは好みに合わせて\n2つのステージの間を自由にいったりきたりできるって仕組みよ。",
  ui_story_5037_50370901_49_dialog_content = "最後にお客さんが多く留まっていた方のステージが、\n勝ちってことになるわ。",
  ui_story_5037_50370901_50_dialog_content = "うーん…どうやったら、\nたくさんのお客さんに来てもらえるんだろう…？",
  ui_story_5037_50370901_51_dialog_content = "へえ？あのキャロっていう珍獣ちゃん、そんなに強いの？",
  ui_story_5037_50370901_52_dialog_content = "うーん、私も一匹捕まえて、かんでもらおうかしら…",
  ui_story_5037_50370901_53_dialog_content = "ダメだ…やっぱり落ち着かない！",
  ui_story_5037_50370901_54_dialog_content = "すみません、もう少し考えてから注文してもいいですか？",
  ui_story_5037_50370901_55_dialog_content = "かしこまりました。\nお決まりになりましたら、またお呼びください。",
  ui_story_5037_50370901_56_dialog_content = "事務所にいなくても、\nコンサートのことばかり考えちゃう…",
  ui_story_5037_50370901_57_dialog_content = "明日のスケジュールも考えなきゃいけないと思うと、\n落ち着いていられないや…",
  ui_story_5037_50370901_58_dialog_content = "はぁ…気になることがあるせいで、\nコーヒーもケーキもおいしそうに思えなくなっちゃうな。",
  ui_story_5037_50370901_59_dialog_content = "練習は、今頃どんな感じだろう…？",
  ui_story_5037_50370901_60_dialog_content = "…こっそり戻って、様子を見るくらいなら問題ないよね？",
  ui_story_5037_50370901_61_dialog_content = "<color=#828282>事務所の外</color>",
  ui_story_5037_50370901_62_dialog_content = "レッスン室の入り口までくれば、\n窓越しに中の様子くらい見えるよね。",
  ui_story_5037_50370901_63_dialog_content = "ん？あれってゴルディだよね？そばにいるのって――",
  ui_story_5037_50370901_64_dialog_content = "大人気アイドルのゴルディさんですよね？\n自分、『アストラスポーツ』の者になります。",
  ui_story_5037_50370901_65_dialog_content = "つかぬことをお伺いしますが、さきほど、プロデューサーの方を\n事務所から締め出されていましたよね？",
  ui_story_5037_50370901_66_dialog_content = "あなたとプロデューサーの間に不仲説がささやかれていますが、\n今後プロデューサーの助けなしにやっていくというのは本当でしょうか？",
  ui_story_5037_50370901_67_dialog_content = "PlayerNameはとてもいいプロデューサーよ。\nずっとうまくやってるわ。",
  ui_story_5037_50370901_68_dialog_content = "では、さきほどの行為をどう説明なさるんですか？",
  ui_story_5037_50370901_69_dialog_content = "あなたに追い出されたプロデューサー、\n1人で通りにたたずむ姿に、思わず胸が痛みましたよ！",
  ui_story_5037_50370901_70_dialog_content = "それは――",
  ui_story_5037_50370901_71_dialog_content = "まずい！いつもしつこくゴルディを追いかけてる\n迷惑なゴシップ記者だ！",
  ui_story_5037_50370901_72_dialog_content = "ゴルディには会わせないようにしてたから、あしらい方も知らないはず…\nこのままじゃ、あることないことを書かれちゃう！",
  ui_story_5037_50370901_73_dialog_content = "助けに入らないと！",
  ui_story_5037_50370901_74_dialog_content = "プロデューサーさんが可哀想だとは思わないのですか？\nあなたに追い出されて、しかも何の説明もな――",
  ui_story_5037_50370901_75_dialog_content = "何を話してるの？",
  ui_story_5037_50370901_76_dialog_content = "PlayerName！？",
  ui_story_5037_50370901_77_dialog_content = "あ、あなたは！？",
  ui_story_5037_50370901_78_dialog_content = "さっき、僕とゴルディの不仲がどうとか言ってましたよね？",
  ui_story_5037_50370901_79_option_content = "はっきり否定する",
  ui_story_5037_50370901_80_dialog_content = "そんなのデタラメですよ。\n僕とゴルディは最強のタッグです！",
  ui_story_5037_50370901_81_option_content = "きちんと説明する",
  ui_story_5037_50370901_82_dialog_content = "僕たちは息の合った仕事ができてますし、\n不仲でもありません。",
  ui_story_5037_50370901_83_dialog_content = "むっ…",
  ui_story_5037_50370901_84_dialog_content = "その通りよ！",
  ui_story_5037_50370901_85_dialog_content = "根も葉もないうわさで名誉を棄損するようなら、\nしかるべき罰を受けてもらうことになりますよ！",
  ui_story_5037_50370901_86_dialog_content = "そ、そうですか！",
  ui_story_5037_50370901_87_dialog_content = "いやいや大変失礼しました！では、自分はこれで！",
  ui_story_5037_50370901_88_dialog_content = "ふぅ…戻ってきてくれて助かったわ。",
  ui_story_5037_50370901_89_dialog_content = "でないと、どう対応すればいいか分からなかったもの。",
  ui_story_5037_50370901_90_dialog_content = "今どきのゴシップ記者がここまで高い「プロ意識」の持ち主だなんて、\n思ってもみなかったよ。",
  ui_story_5037_50370901_91_dialog_content = "ちょっと事務所を離れただけで、\nあんなデマをでっち上げられそうになるなんて…",
  ui_story_5037_50370901_92_dialog_content = "そういえば、PlayerNameは今日はお休みって言わなかったかしら？",
  ui_story_5037_50370901_93_dialog_content = "どうして戻ってきたの？",
  ui_story_5037_50370901_94_dialog_content = "うっ…そ、それは…",
  ui_story_5037_50370901_95_dialog_content = "はぁ…正直に言うと、休めっていわれても\nどうしても落ち着いて休んでいられないんだ。",
  ui_story_5037_50370901_96_dialog_content = "コンサートのことが、\n気になってしょうがなくて…",
  ui_story_5037_50370901_97_dialog_content = "食べ物も水ものどを通らないぐらいなのに、\n休むなんてできっこないよ。",
  ui_story_5037_50370901_98_dialog_content = "そうだったの？",
  ui_story_5037_50370901_99_dialog_content = "…だから、まずはコンサートが無事に終わってから、\n休もうと思うんだ。",
  ui_story_5037_50370901_100_dialog_content = "う～ん…",
  ui_story_5037_50370901_101_dialog_content = "…ホントのことを言うとね、私も同じような気持ちなの。",
  ui_story_5037_50370901_102_dialog_content = "それに、今まで1人でやってた時は、\nゴシップ記者にだって自分でうまく対応してきたの。",
  ui_story_5037_50370901_103_dialog_content = "でも、PlayerNameと一緒に仕事するようになって、\nそういうことはぜんぶ頼りきりになっちゃってたから…",
  ui_story_5037_50370901_104_dialog_content = "自分でどうにかしようとしても、\nとっさに対応できなくなっちゃってたわ。",
  ui_story_5037_50370901_105_dialog_content = "だとしたら、僕のせいだよね…",
  ui_story_5037_50370901_106_dialog_content = "違うわ！PlayerNameが手伝ってくれてるようになってから、\n私は前より伸びてるの！",
  ui_story_5037_50370901_107_dialog_content = "前よりずっと練習に専念できるようになったから、\nいろんなスキルが成長してるのよ！",
  ui_story_5037_50370901_108_dialog_content = "今の私はもう昔の私じゃないわ。\nスーパー☆ゴルディよ！",
  ui_story_5037_50370901_109_dialog_content = "そっか…よかった。僕、足を引っ張ってなかったんだね。",
  ui_story_5037_50370901_110_dialog_content = "あなたは優秀なプロデューサーなのよ？\n足なんか引っ張るわけないでしょ！",
  ui_story_5037_50370901_111_dialog_content = "ただ、休憩時間のことは…",
  ui_story_5037_50370901_112_dialog_content = "心配いらないよ。確かに忙しいけど、\nちゃんと睡眠をとって体調管理はするから大丈夫！",
  ui_story_5037_50370901_113_dialog_content = "分かったわ。じゃあ今回は、プロデューサーの言う通りにするわね！",
  ui_story_5037_50370901_114_dialog_content = "あなたを信じるわ！",
  ui_story_5037_50371001_1_dialog_content = "――無事にコンサート、合格ね！",
  ui_story_5037_50371001_2_dialog_content = "本当によかった！最大の難関を突破したね！",
  ui_story_5037_50371001_3_dialog_content = "ほっとしたら、急に疲れが出てきちゃった…",
  ui_story_5037_50371001_4_dialog_content = "だったら今日は、ゆっくり休むといいわ！",
  ui_story_5037_50371001_5_dialog_content = "そうだね、確かにしっかり休むべきかも。",
  ui_story_5037_50371001_6_dialog_content = "せっかく休んでもらうのだから、なにか…",
  ui_story_5037_50371001_7_dialog_content = "そうだ！PlayerName、歌は聴きたいかしら？",
  ui_story_5037_50371001_8_dialog_content = "最後のコンサートのために新曲を作ったの！",
  ui_story_5037_50371001_9_dialog_content = "まだサビが仕上がってないけど、\n他の部分は出来てるわ。",
  ui_story_5037_50371001_10_dialog_content = "いいね！ゴルディの書いた新曲なら、きっといい曲なんだろうな。",
  ui_story_5037_50371001_11_dialog_content = "じゃあ、歌うわね――",
  ui_story_5037_50371001_12_dialog_content = "♪少しの間だけ離れていたってかまわない",
  ui_story_5037_50371001_13_dialog_content = "♪遠く離れていても、同じ星の光が照らしてくれる",
  ui_story_5037_50371001_14_dialog_content = "♪だから泣かないで、未来は目の前にある",
  ui_story_5037_50371001_15_dialog_content = "♪「さよなら」は次に会う約束だから",
  ui_story_5037_50371001_16_dialog_content = "（きれいな曲だな…）",
  ui_story_5037_50371001_17_dialog_content = "（でも、これは別れの歌だ…\nメロディーも今までにないくらい、優しくて柔らかい…）",
  ui_story_5037_50371001_18_dialog_content = "PlayerName、どうだった？",
  ui_story_5037_50371001_19_option_content = "とてもよかったよ！",
  ui_story_5037_50371001_20_dialog_content = "ふふ、ありがとう！",
  ui_story_5037_50371001_21_option_content = "今までの曲とちょっと違うね？",
  ui_story_5037_50371001_22_dialog_content = "ふふ、やっぱり気づいた？",
  ui_story_5037_50371001_23_dialog_content = "だって、「卒業コンサート」のための曲だもの。\n胸いっぱいの感謝の気持ちを込めて書かなきゃでしょ！",
  ui_story_5037_50371001_24_dialog_content = "でも、感謝以外の気持ちも…込められてる気がした。",
  ui_story_5037_50371001_25_dialog_content = "悲しみっていうか、名残惜しさというか…\nうまく言えないけど…",
  ui_story_5037_50371001_26_dialog_content = "それは、お別れの歌だからよ。",
  ui_story_5037_50371001_27_dialog_content = "お別れ…誰と誰が？",
  ui_story_5037_50371001_28_dialog_content = "そうだ、前から気になってたんだ。\n「卒業コンサート」の「卒業」って、どういう意味？",
  ui_story_5037_50371001_29_dialog_content = "アイドルの「卒業」っていうのはね、\n事務所を辞めて、アイドルじゃなくなるって意味よ。",
  ui_story_5037_50371001_30_dialog_content = "だから、卒業コンサートは\nファンのみんなとお別れするためのコンサートなの。",
  ui_story_5037_50371001_31_dialog_content = "え！？",
  ui_story_5037_50371001_32_dialog_content = "つまり、コンサートの後、\nゴルディはアイドルをやめるってこと！？",
  ui_story_5037_50371001_33_dialog_content = "もちろん、それにはまだ早いわ。\n私のアイドルの道は始まったばかりだもの！",
  ui_story_5037_50371001_34_dialog_content = "今回はあくまで番組としての「卒業コンサート」よ。\n本当の「卒業」じゃないわ！",
  ui_story_5037_50371001_35_dialog_content = "PlayerNameにアイドルのデビューから卒業までの過程を、\n新人プロデューサーとして体験してもらうためのね！",
  ui_story_5037_50371001_36_dialog_content = "私はこれからもアイドルを続けるわ！",
  ui_story_5037_50371001_37_dialog_content = "そっか、びっくりしたよ…",
  ui_story_5037_50371001_38_dialog_content = "一瞬、本当にアイドルを辞めちゃうのかと思った…",
  ui_story_5037_50371001_39_dialog_content = "もう、そんなはずないでしょ！？",
  ui_story_5037_50371001_40_dialog_content = "私にとっては…そうね、この活動の「まとめ」のための\nコンサートって感じかしら。",
  ui_story_5037_50371001_41_dialog_content = "PlayerNameと一緒に仕事してた期間に経験したことや、\n進歩したことのまとめを披露する、ってことよ。",
  ui_story_5037_50371001_42_dialog_content = "なるほどね。",
  ui_story_5037_50371001_43_dialog_content = "アイドルじゃないゴルディなんて、想像もできないよ…",
  ui_story_5037_50371001_44_dialog_content = "僕にとってゴルディこそ、\n「アイドル」そのものだから。",
  ui_story_5037_50371001_45_dialog_content = "そんなふうに言ってもらえるなんて、うれしいわ。",
  ui_story_5037_50371001_46_dialog_content = "それってつまり、アイドルとしてのゴルディが\n心に残ってるってことだもの！",
  ui_story_5037_50371001_47_dialog_content = "でも…そうだとしても、\n「アイドル」としての私を脱ぎ捨てれば、中には普通の私がいるの。",
  ui_story_5037_50371001_48_dialog_content = "いつかはホントの「卒業コンサート」で、\nファンのみんなとお別れして、アイドルを辞める日がくるわ…",
  ui_story_5037_50371001_49_dialog_content = "そんな悲しいこと…",
  ui_story_5037_50371001_50_dialog_content = "悲しい？私は、そうは思わないわ。",
  ui_story_5037_50371001_51_dialog_content = "えっ？",
  ui_story_5037_50371001_52_dialog_content = "だって、アイドルならいつか必ず通る道だもの。\nイヤだって思ってたって、その日は必ず来るの。",
  ui_story_5037_50371001_53_dialog_content = "だったら、逃げずに真正面から向き合って、\n「卒業コンサート」をどう成功させるか考えた方がいいでしょ！",
  ui_story_5037_50371001_54_dialog_content = "どうすれば、自分もファンも、悔いなく卒業できるのか…",
  ui_story_5037_50371001_55_dialog_content = "どうすれば、最後に見せる、一番輝いてる自分を\nファンのみんなの心に焼きつけられるのか…",
  ui_story_5037_50371001_56_dialog_content = "そのためにも私は、\nデビューから卒業までずっと努力し続けるの。",
  ui_story_5037_50371001_57_dialog_content = "さすがゴルディだね！",
  ui_story_5037_50371001_58_dialog_content = "でも…アイドルを辞めたあと、ゴルディは何をするつもり？",
  ui_story_5037_50371001_59_dialog_content = "うう～ん…それは…まだ決めてないわ！",
  ui_story_5037_50371001_60_dialog_content = "いろいろ考えてはいるけど…\n一番はやっぱり、ペットカフェを開くことね！",
  ui_story_5037_50371001_61_dialog_content = "そうすれば、仕事をしながら一緒にいられるから、\nマシュマロも寂しくないわ！",
  ui_story_5037_50371001_62_dialog_content = "それはいい案だね！",
  ui_story_5037_50371001_63_dialog_content = "ペットと遊びながらコーヒーを飲めるなんて、\n幸せだろうなぁ…",
  ui_story_5037_50371001_64_dialog_content = "でしょう？",
  ui_story_5037_50371001_65_dialog_content = "疲れた時にマシュマロの柔らかいフワフワの毛をなでると、\nスッと気持ちが楽になるの。",
  ui_story_5037_50371001_66_dialog_content = "アイドルが歌やダンスでみんなに喜びを届ける職業なら…",
  ui_story_5037_50371001_67_dialog_content = "ペットカフェは動物たちと一緒に、\nみんなにあたたかさと幸せを届ける仕事ね！",
  ui_story_5037_50371001_68_dialog_content = "どっちの毎日もきっと、私は大好き！",
  ui_story_5037_50371101_1_dialog_content = "（今日、事務所にヴィックから僕宛ての手紙が届いてた）",
  ui_story_5037_50371101_2_dialog_content = "（手紙には、聞きたいことがあるから\n1人でダンスレッスン室で待っていてくれ、と書いてあったけど…）",
  ui_story_5037_50371101_3_dialog_content = "あっ、やっと来た！",
  ui_story_5037_50371101_4_dialog_content = "え？その声はフィア？",
  ui_story_5037_50371101_5_dialog_content = "アイタッ…イタタタタ…フィア、放してくれ！\n耳がちぎれちまうだろ！",
  ui_story_5037_50371101_6_dialog_content = "…何やってるの？",
  ui_story_5037_50371101_7_dialog_content = "何って、フィアに耳をひっぱられて…イテテテ！",
  ui_story_5037_50371101_8_dialog_content = "いくらPlayerNameがあたしと師匠のトモダチだからって、\nこういうことはハッキリさせておかないとダメ！",
  ui_story_5037_50371101_9_dialog_content = "えっと、その…いったい何のこと？",
  ui_story_5037_50371101_10_dialog_content = "PlayerName、毎日あたしたちを追いかけまわしてる\nあのゴシップ記者、どういうこと？",
  ui_story_5037_50371101_11_dialog_content = "ゴシップ記者？",
  ui_story_5037_50371101_12_dialog_content = "ああ、あのヒゲをはやした、\nいかにも怪しそうなおじさんのこと？",
  ui_story_5037_50371101_13_dialog_content = "そうだよ！やっぱり知り合いなんだね！",
  ui_story_5037_50371101_14_dialog_content = "あいつ、毎日レッスン室に来て\nダメ師匠の練習のジャマばっかりしてるの！",
  ui_story_5037_50371101_15_dialog_content = "しかも、どんなにフィアが追い返しても次の日にはかならず\nダメ師匠をこき下ろして、ゴルディお姉ちゃんをほめちぎる記事が出るんだよ！",
  ui_story_5037_50371101_16_dialog_content = "あんたたちの回し者でしょ！？",
  ui_story_5037_50371101_17_dialog_content = "ええ…どうして僕たちがそんなことしなきゃいけないの…？",
  ui_story_5037_50371101_18_dialog_content = "あの人には、\n僕とゴルディも毎日困ってるんだ！",
  ui_story_5037_50371101_19_dialog_content = "えっ、そうなの？",
  ui_story_5037_50371101_20_dialog_content = "やれやれ、だから言ったろ。",
  ui_story_5037_50371101_21_dialog_content = "それにあの新聞な、俺をけなすだけじゃなくて\nゴルディのことも悪く言ってるんだ。",
  ui_story_5037_50371101_22_dialog_content = "そ、そうなの！？",
  ui_story_5037_50371101_23_dialog_content = "あたし、いつもダメ師匠の記事しか、\nちゃんと読んでなかったから…",
  ui_story_5037_50371101_24_dialog_content = "そういえばゴルディの記事だけじゃなくて、\nヴィックの記事も読んだことがあった気がする…",
  ui_story_5037_50371101_25_dialog_content = "じゃあ、どっちとも関係ないなら、\nあいつはいったいどこから…？",
  ui_story_5037_50371101_26_dialog_content = "きっと自分で勝手に、ゴシップが転がってそうな場所に\n見当をつけてきたんじゃないかな。",
  ui_story_5037_50371101_27_dialog_content = "いつも事務所を離れる前にはレッスン室のドアにしっかり鍵をかけてるんだけど、\nどういうわけか、いつも入って来てるんだよね…",
  ui_story_5037_50371101_28_dialog_content = "ホントに困っちゃうよ。",
  ui_story_5037_50371101_29_dialog_content = "ホントだよ！あいつのせいで、ファンが減っちゃうじゃない！",
  ui_story_5037_50371101_30_dialog_content = "でも、そっか…誤解だったんだね…",
  ui_story_5037_50371101_31_dialog_content = "…ごめんなさい。",
  ui_story_5037_50371101_32_dialog_content = "大丈夫、気にしないで。\n他になにか用事はある？",
  ui_story_5037_50371101_33_dialog_content = "ううん、ないよ。\nあたしもダメ師匠と一緒に練習に戻らなきゃ。",
  ui_story_5037_50371101_34_dialog_content = "あんたたちも、頑張ってね。",
  ui_story_5037_50371101_35_dialog_content = "うん、じゃあ――",
  ui_story_5037_50371101_36_dialog_content = "<size=45>ちょっと待った！</size>",
  ui_story_5037_50371101_37_dialog_content = "ヴィック？どうかしたの？",
  ui_story_5037_50371101_38_dialog_content = "PlayerName…実はちょっと頼みたいことがあるんだ。",
  ui_story_5037_50371101_39_dialog_content = "な、何？",
  ui_story_5037_50371101_40_dialog_content = "…ゴシップ書きのあしらい方を教えてくれ！",
  ui_story_5037_50371101_41_dialog_content = "うわ！？ちょちょちょっと、離れてって！",
  ui_story_5037_50371101_42_dialog_content = "僕のヘアバンドで涙を拭かないで！",
  ui_story_5037_50371101_43_dialog_content = "うう、ぐすっ…",
  ui_story_5037_50371101_44_dialog_content = "あいつが毎回あることないこと記事にするもんだから、\nファンがゴッソリいなくなるだろ…",
  ui_story_5037_50371101_45_dialog_content = "するとファンの数を取り戻すには、\nもっと練習して一生懸命アイドル活動するしかなくなって…",
  ui_story_5037_50371101_46_dialog_content = "でもって、俺がフィアに毎日見張られるハメになる…\n練習をサボる時間なんてどこにもありゃしない…",
  ui_story_5037_50371101_47_dialog_content = "この間もな、ちょっと休憩しようとしただけで、\nフィアのヤツ、キャロに俺の太ももをかませたんだぞ！？",
  ui_story_5037_50371101_48_dialog_content = "あちこちかまれて、もう俺の太ももは傷だらけだ。\nぐすっ…PlayerName、助けてくれぇ…",
  ui_story_5037_50371101_49_dialog_content = "分かった分かった、教えるから！",
  ui_story_5037_50371101_50_dialog_content = "さすがPlayerNameだ！\n君なら見捨てないで助けてくれるって信じてたぞ！",
  ui_story_5037_50371101_51_dialog_content = "とりあえず、何から話せばいいかな…？",
  ui_story_5037_50371101_52_dialog_content = "まずは最新版の『アストラスポーツ』の記事でも見てみようか――",
  ui_story_5037_50371101_53_dialog_content = "「永遠の18歳と語るヴィック、\n実年齢を大幅サバ読み」！？",
  ui_story_5037_50371101_54_dialog_content = "うーん、確かにヴィックが言いそうなことだね…",
  ui_story_5037_50371101_55_dialog_content = "ああ、あの時のことか、覚えてるぞ！\n確かに永遠の18歳だって言ったっけな…",
  ui_story_5037_50371101_56_dialog_content = "それだけなら、誰が聞いても\n真に受けるとは思えないけど。",
  ui_story_5037_50371101_57_dialog_content = "俺のトシは秘密だから、まあ仕方ないだろ？",
  ui_story_5037_50371101_58_dialog_content = "それなら、これからも年齢は秘密だって\n言い続けてれば大丈夫だよ。",
  ui_story_5037_50371101_59_dialog_content = "でも、記事には「ヴィックは、今大人気のゴルディよりも\n若くはつらつとした魅力があると自分で思っている」ってあるね。",
  ui_story_5037_50371101_60_dialog_content = "ああ？それは俺の言ったことじゃないな。\nその記者が俺をほめた時にそう言ったんだ。",
  ui_story_5037_50371101_61_dialog_content = "で、どう答えたの？",
  ui_story_5037_50371101_62_dialog_content = "どうって、ほめられたんだぞ？\n喜んでそのまま受け止めたに決まってる！",
  ui_story_5037_50371101_63_dialog_content = "記者の言葉に乗っかっちゃったら、\nわざわざデマの種を提供するようなものだよ。",
  ui_story_5037_50371101_64_dialog_content = "じゃ…じゃあ、なんて答えりゃよかったんだ？",
  ui_story_5037_50371101_65_dialog_content = "こういう場合、相手は「自分は他の人より優秀だ」って\n言わせようとしてるんだ。",
  ui_story_5037_50371101_66_dialog_content = "今後似たようなことを言われたら、謙虚に答えたほうがいいね。\nそうすれば、記事にしようがないから。",
  ui_story_5037_50371101_67_dialog_content = "なるほどな…よし、今度から気を付けるぞ！",
  ui_story_5037_50371101_68_dialog_content = "他には、そうだなぁ…",
  ui_story_5037_50371101_69_dialog_content = "「ヴィックのプロデューサー、\n危険な野生動物をけしかけ丸腰の記者に脅迫行為」？",
  ui_story_5037_50371101_70_dialog_content = "フィア、これは？",
  ui_story_5037_50371101_71_dialog_content = "な、なんでこっちを見るの？",
  ui_story_5037_50371101_72_dialog_content = "あたしはただ、あまりにもうざったいから\nキャロに記者をくわえて、外まで放りだしてもらっただけだよ！",
  ui_story_5037_50371101_73_dialog_content = "それは良くないね。",
  ui_story_5037_50371101_74_dialog_content = "いくら記者がうっとうしくても、\n暴力で対応するのはいけないよ。",
  ui_story_5037_50371101_75_dialog_content = "そんなことをすれば、それが弱みになって、\nもっと好き勝手に記事を書かれちゃうから。",
  ui_story_5037_50371101_76_dialog_content = "じゃ、じゃあどうすればいいの？",
  ui_story_5037_50371101_77_dialog_content = "追い返すのもダメで、逃げることもできないんじゃ、\n蚊に刺されっぱなしみたいじゃない！",
  ui_story_5037_50371101_78_dialog_content = "そういう時は、とにかく取材を断り続けるだけでいいんだ。\nキッパリ、正々堂々とね。",
  ui_story_5037_50371101_79_dialog_content = "そうすれば、ヴィックを悪く言う記事を書こうとしたって、\n確かな証拠がないから、ただのデタラメにしかならないでしょ？",
  ui_story_5037_50371101_80_dialog_content = "それから…やっぱり、ヴィック自身の実力を磨くことも大事かな。\n結局、それさえあれば、どんな誹謗中傷も無力だからね。",
  ui_story_5037_50371101_81_dialog_content = "…うん、わかった。",
  ui_story_5037_50371101_82_dialog_content = "PlayerName、ありがとう。\n君は命の恩人だ！",
  ui_story_5037_50371101_83_dialog_content = "お礼なんていいよ。\n今はライバルかもしれないけど、僕たちは友だちなんだから。",
  ui_story_5037_50371101_84_dialog_content = "対決中だから…なんて理由で、\n困ってるのを放ってはおけないよ！",
  ui_story_5037_50371101_85_dialog_content = "ううっ…君は本当にいいヤツだ！",
  ui_story_5037_50371101_86_dialog_content = "PlayerName、今日はお礼を言っとくよ、ありがと…",
  ui_story_5037_50371101_87_dialog_content = "しかし、アイドル兼珍獣マスターの名誉にかけて、\nこのまま手ぶらで帰すわけにはいかないな！",
  ui_story_5037_50371101_88_dialog_content = "フィアがプロデューサーの勉強をするために、\n読んでいた本が2冊ほどある…きっと君の役に立つはずだ。",
  ui_story_5037_50371101_89_dialog_content = "どっちか1冊、好きな方を選ぶといい。\n助けてもらった礼だ。",
  ui_story_5037_50371101_90_dialog_content = "あー！？それ、あたしの本！？\n師匠が服の中に隠してたの！？どうりで見つからないと思った！",
  ui_story_5037_50371101_91_dialog_content = "でもまあ、今はもう必要ないし…\nPlayerName、好きな方を選んで。",
  ui_story_5037_50371101_92_dialog_content = "ありがとう。じゃあ――",
  ui_story_5037_50371101_93_option_content = "『新人アイドルスピード養成術』にする",
  ui_story_5037_50371101_94_option_content = "『プロデューサーの心得』にする",
  ui_story_5037_50371101_95_dialog_content = "じゃあ、あたしたちも帰るね！",
  ui_story_5037_50371101_96_dialog_content = "ほら行くよ、ダメ師匠。\n戻って練習の続き！",
  ui_story_5037_50371101_97_dialog_content = "ああ！？ま、まだやるのか！？",
  ui_story_5037_50371101_98_dialog_content = "決まってるでしょ！\nPlayerNameと話してたぶん、ちゃんと取り戻さなきゃ！",
  ui_story_5037_50371101_99_dialog_content = "カンベンしてくれ～！",
  ui_story_5037_50371201_1_dialog_content = "コンサートを控えた大事な時に、\nヴィックに呼び出された…",
  ui_story_5037_50371201_2_dialog_content = "しかもフィアには内緒で、1人で来いって…",
  ui_story_5037_50371201_3_dialog_content = "いったい、何をたくらんでるんだろう？",
  ui_story_5037_50371201_4_dialog_content = "おお、来たか！PlayerNameなら\n時間通りに来てくれるって信じてたぞ！",
  ui_story_5037_50371201_5_dialog_content = "ヴィック、わざわざ呼び出しなんて、何の用？",
  ui_story_5037_50371201_6_dialog_content = "いや、特にこれと言って緊急の用事じゃないんだが――",
  ui_story_5037_50371201_7_dialog_content = "頼む！俺を1日かくまってくれ！",
  ui_story_5037_50371201_8_dialog_content = "え…！？",
  ui_story_5037_50371201_9_dialog_content = "コンサート対決も近いのに、\n練習もしないで隠れるつもり？どういうこと？",
  ui_story_5037_50371201_10_dialog_content = "その練習が問題なんだよ。\nまずは俺がここんとこ、どんな毎日を送ってるか聞いてくれ…",
  ui_story_5037_50371201_11_dialog_content = "毎朝毎朝、まだ日も出ないうちに練習だなんだと\nフィアにたたき起こされてな…",
  ui_story_5037_50371201_12_dialog_content = "ダメ師匠、さっさと起きて！練習の時間だよ！",
  ui_story_5037_50371201_13_dialog_content = "まずは体力のトレーニングで、森の周りを10周ね！",
  ui_story_5037_50371201_14_dialog_content = "ふわぁ～…眠い…",
  ui_story_5037_50371201_15_dialog_content = "もう少し寝かせてくれ…",
  ui_story_5037_50371201_16_dialog_content = "起きないつもり？\nじゃあ…キャロ、やっちゃって！",
  ui_story_5037_50371201_17_dialog_content = "ルルル！！",
  ui_story_5037_50371201_18_dialog_content = "うわあああ！！",
  ui_story_5037_50371201_19_dialog_content = "か、かまないでくれ！す、すぐに起きる！",
  ui_story_5037_50371201_20_dialog_content = "…そうして走り終わったら顔を洗って、朝メシを食うんだが…",
  ui_story_5037_50371201_21_dialog_content = "今日の朝ご飯はおがくずパンと牛乳、\nそれからゆでたニンジンだよ！",
  ui_story_5037_50371201_22_dialog_content = "なあフィア、3日連続でゆでたニンジンじゃないか。\n他のモンに変えてくれよ…",
  ui_story_5037_50371201_23_dialog_content = "油が乗ってて、チリソースのたっぷりかかった、\nサンドワームの串焼きとかさ。",
  ui_story_5037_50371201_24_dialog_content = "師匠は今、アイドルなんだよ？だったらスタイルを保たなきゃ！\nお昼ご飯もお夕飯も、ゆでたニンジンだからね！",
  ui_story_5037_50371201_25_dialog_content = "うう…",
  ui_story_5037_50371201_26_dialog_content = "それから――",
  ui_story_5037_50371201_27_dialog_content = "うん…どんな目に遭ってるかは、\n大体想像がついたよ…",
  ui_story_5037_50371201_28_dialog_content = "…ってことで、俺の身の安全のためにも、PlayerName！\nどうかここで1日休ませてくれ！",
  ui_story_5037_50371201_29_dialog_content = "本当にたった1日でいいんだ。\n今の生活は、もう光霊の送る生活じゃない！",
  ui_story_5037_50371201_30_dialog_content = "このままじゃ、世界が偉大な珍獣の研究者を1人失っちまう！",
  ui_story_5037_50371201_31_dialog_content = "君って人は…はぁ…",
  ui_story_5037_50371201_32_dialog_content = "まぁ、勝てるようにってすごく頑張ってるのは分かるけど、\n確かにフィアもちょっと厳しすぎるかもね。",
  ui_story_5037_50371201_33_dialog_content = "ここで休ませてあげてもいいけど、\n条件を2つ出させてもらうよ。",
  ui_story_5037_50371201_34_dialog_content = "休んだらすぐにフィアのところに戻ること。\nでないと、心配させちゃうからね。",
  ui_story_5037_50371201_35_dialog_content = "それから、厳しすぎると思うことについては、\nフィアにちゃんと伝えて、話し合うこと。",
  ui_story_5037_50371201_36_dialog_content = "それくらい任せとけ！1日でもサボ…休めるなら、\nどんな条件だって飲むさ！",
  ui_story_5037_50371201_37_dialog_content = "じゃあ、ヴィックはゆっくり休んでて。\n僕はこの後、ゴルディの今日のスケジュールを立てなきゃいけないから。",
  ui_story_5037_50371201_38_dialog_content = "了解了解、俺に構わず、気にせず仕事しててくれ！",
  ui_story_5037_50371201_39_dialog_content = "おっ、このソファー、いいな。\n寝るのにちょうどよさそうだ。",
  ui_story_5037_50371201_40_dialog_content = "モジャ、大きくなれ。\nお前を抱き枕にして、ゆっくり寝るとするか～。",
  ui_story_5037_50371201_41_dialog_content = "ウキュッ！",
  ui_story_5037_50371201_42_dialog_content = "すぅ…すぅ…",
  ui_story_5037_50371201_43_dialog_content = "（もう寝ちゃった…さすがヴィック…）",
  ui_story_5037_50371201_44_dialog_content = "（じゃ、僕は仕事に戻ろう）",
  ui_story_5037_50371201_45_dialog_content = "<color=#828282>しばらくして</color>",
  ui_story_5037_50371201_46_dialog_content = "（よし、スケジュールはこれでほぼオッケー。\nこの仕事にもだいぶ慣れてきたかも！）",
  ui_story_5037_50371201_47_dialog_content = "<color=#828282>トントントン！</color>",
  ui_story_5037_50371201_48_dialog_content = "（ん？誰だろう？）",
  ui_story_5037_50371201_49_dialog_content = "どちら様ですか？",
  ui_story_5037_50371201_50_dialog_content = "PlayerName、あたし！フィアだよ！",
  ui_story_5037_50371201_51_dialog_content = "（フィア！？）",
  ui_story_5037_50371201_52_dialog_content = "（まずい、ヴィックがいる！）",
  ui_story_5037_50371201_53_dialog_content = "<color=#828282>トントントン！</color>",
  ui_story_5037_50371201_54_dialog_content = "PlayerName？",
  ui_story_5037_50371201_55_dialog_content = "ちょっと待ってて、すぐに開けるから！",
  ui_story_5037_50371201_56_dialog_content = "ヴィック、起きて！",
  ui_story_5037_50371201_57_dialog_content = "むにゃ…ああ？モジャ、ハハハ、おとなしくしてろって…",
  ui_story_5037_50371201_58_dialog_content = "僕より起きない人なんて初めて見た…",
  ui_story_5037_50371201_59_dialog_content = "（仕方ない。とにかくまずはヴィックを隠そう）",
  ui_story_5037_50371201_60_dialog_content = "（…周りは…雑誌の山の中でいいか…）",
  ui_story_5037_50371201_61_dialog_content = "よし…フィア、お待たせ、今開けるね！",
  ui_story_5037_50371201_62_dialog_content = "…何してたの？",
  ui_story_5037_50371201_63_dialog_content = "ごめんごめん、ちょっとその…部屋の片づけをしてたんだ！",
  ui_story_5037_50371201_64_dialog_content = "ふ～ん？確かにずいぶん散らかってるね。\nガラクタが山みたいになってるし、たしかにお片づけが必要かもね。",
  ui_story_5037_50371201_65_dialog_content = "アハハ…ところで、僕に何の用？",
  ui_story_5037_50371201_66_dialog_content = "そうだった、ねえ、師匠を見かけなかった？",
  ui_story_5037_50371201_67_dialog_content = "え…あ？み、見てないよ。",
  ui_story_5037_50371201_68_dialog_content = "ホントに？",
  ui_story_5037_50371201_69_dialog_content = "ずっと部屋の片づけをしたり、ゴルディのスケジュールを立てたりしてたから…\nヴィックは見かけなかったかな。",
  ui_story_5037_50371201_70_dialog_content = "ふ～ん、そう。\nあんたのところにもいないなんて、おかしいなぁ。",
  ui_story_5037_50371201_71_dialog_content = "だとしたらダメ師匠、どこに行ったんだろ…？",
  ui_story_5037_50371201_72_dialog_content = "ちょっとの間だけ逃げ出してサボってるだけじゃないかな？\n少しすれば、きっと戻ってくるよ。",
  ui_story_5037_50371201_73_dialog_content = "コンサートまであと何日もないんだよ！\nなのにサボりなんて、師匠はどういう神経してるの！？",
  ui_story_5037_50371201_74_dialog_content = "帰ってきたらビシビシ練習させないと！",
  ui_story_5037_50371201_75_dialog_content = "アハハ…でも、もしかしたら練習がキツすぎるのがいやで、\nどこかに行っちゃったのかもしれないよ？",
  ui_story_5037_50371201_76_dialog_content = "フィアの練習は厳しいって聞いてるし。\nいいことだとは思うけど、休息とのバランスも大切だよ。",
  ui_story_5037_50371201_77_dialog_content = "…そうなの？",
  ui_story_5037_50371201_78_dialog_content = "でも、フィアも今日は1日お休みにして、\nたまにはゆっくり休んでもらおうと思ってたんだ…",
  ui_story_5037_50371201_79_dialog_content = "なのに、いなくなっちゃって。\n影ノ街じゅう探したんだけど、それでも見つからなくて…",
  ui_story_5037_50371201_80_dialog_content = "（えっ、今日は休ませてあげるつもりだったの？\nフィアもちゃんと考えて、計画を立ててたんだね…）",
  ui_story_5037_50371201_81_dialog_content = "心配しなくても大丈夫だよ。\n僕も皆に頼んで探してあげるから。",
  ui_story_5037_50371201_82_dialog_content = "…うん。じゃあ、また探しに行ってくる。",
  ui_story_5037_50371201_83_dialog_content = "…ちょっと待って、あそこ…",
  ui_story_5037_50371201_84_dialog_content = "（まずい！ヴィックを隠してる本の山に気づかれた！）",
  ui_story_5037_50371201_85_dialog_content = "あ！えーと、そ、それは前に読んだ雑誌の山なんだけど…\nずっと片づけてなくて…だから、後で――",
  ui_story_5037_50371201_86_dialog_content = "雑誌の山がどうして丸くふくらんでるの？\n中に何か隠してる…？",
  ui_story_5037_50371201_87_dialog_content = "ちょっと待って――！",
  ui_story_5037_50371201_88_dialog_content = "ダメ師匠！？",
  ui_story_5037_50371201_89_dialog_content = "すぅ…すぅ…",
  ui_story_5037_50371201_90_dialog_content = "どうして師匠がこんなところで寝てるの？",
  ui_story_5037_50371201_91_dialog_content = "PlayerName、あたしにウソついたの！？",
  ui_story_5037_50371201_92_dialog_content = "ええと…その…",
  ui_story_5037_50371201_93_option_content = "正直に話す",
  ui_story_5037_50371201_94_dialog_content = "…分かった、正直に言うよ。\nさっきは君にウソをついてた。",
  ui_story_5037_50371201_95_dialog_content = "ごめん…",
  ui_story_5037_50371201_96_dialog_content = "べつに謝らなくていいよ。PlayerNameは悪気があって\nウソをついたんじゃないってことくらい、分かるもん。",
  ui_story_5037_50371201_97_option_content = "弁解する",
  ui_story_5037_50371201_98_dialog_content = "ぼ、僕が来る前にはもうここにいたんじゃないかな…？\nうん、きっとそうだ！",
  ui_story_5037_50371201_99_dialog_content = "PlayerName、顔にウソって書いてあるよ。",
  ui_story_5037_50371201_100_dialog_content = "まあでも、だいたい想像はつくけどね。",
  ui_story_5037_50371201_101_dialog_content = "どうせ師匠に泣きつかれたんでしょ？",
  ui_story_5037_50371201_102_dialog_content = "実は…",
  ui_story_5037_50371201_103_dialog_content = "けさ、ヴィックが押しかけてきて、\nここで少しゆっくり休みたいって言ったんだ。",
  ui_story_5037_50371201_104_dialog_content = "アイドルの練習が厳しくて、だいぶ疲れてたみたいだよ。\n横になって少しもしないうちに寝ちゃったんだ。",
  ui_story_5037_50371201_105_dialog_content = "…ちゃんとあたしに話すより、\nこっそりここに隠れて休むほうがいいなんて…",
  ui_story_5037_50371201_106_dialog_content = "うう…フィアだって、ちゃんと休みをあげるつもりだったのに！",
  ui_story_5037_50371201_107_dialog_content = "ヴィックが起きたら、ちゃんと話してみたら？",
  ui_story_5037_50371201_108_dialog_content = "はぁ…とりあえず、師匠はここで休ませておいてあげる。",
  ui_story_5037_50371201_109_dialog_content = "起きたら、戻って練習の続きをするように言っといて！",
  ui_story_5037_50371201_110_dialog_content = "そうだ、ダメ師匠が迷惑かけたお詫びに、\nあとでアイドル養成のコツを整理したものをあげるね。",
  ui_story_5037_50371201_111_dialog_content = "分かった、安心して！",
  ui_story_5037_50371201_112_dialog_content = "そうだ、言っとくけど…あたしが来たことは言わないでよ？",
  ui_story_5037_50371201_113_dialog_content = "どうして？",
  ui_story_5037_50371201_114_dialog_content = "だって…",
  ui_story_5037_50371201_115_dialog_content = "<size=45>ダメ師匠はロクデナシだもん！</size>",
  ui_story_5037_50371201_116_dialog_content = "え…！？",
  ui_story_5037_50371201_117_dialog_content = "あたしが見逃してあげたって知ったら、\nきっと図に乗るに決まってる！",
  ui_story_5037_50371201_118_dialog_content = "せっかく身についた生活習慣がくずれて、\n練習の時もスキを見てサボるようになっちゃうもん…",
  ui_story_5037_50371201_119_dialog_content = "いい？ダメ師匠みたいな人への唯一の対処法は、\n厳しく目を光らせて、情けをかけないことだよ！",
  ui_story_5037_50371201_120_dialog_content = "わ、分かったよ…",
  ui_story_5037_50371201_121_dialog_content = "ヴィックが目を覚ましたら、すぐ練習に戻らせるね！",
  ui_story_5037_50371301_1_dialog_content = "よりによって、こんな時に…",
  ui_story_5037_50371301_2_dialog_content = "んー、別に大したことじゃないだろ？",
  ui_story_5037_50371301_3_dialog_content = "そうやって平気でいられるのはダメ師匠くらいだよ！",
  ui_story_5037_50371301_4_dialog_content = "ねえPlayerName、ホントにそこまで深刻なの？",
  ui_story_5037_50371301_5_dialog_content = "うん、たぶん…",
  ui_story_5037_50371301_6_dialog_content = "これは相当、深刻な危機だよ！",
  ui_story_5037_50371301_7_dialog_content = "どう頑張っても、\nゴルディとヴィックのスキルが伸び悩んでるんだ。",
  ui_story_5037_50371301_8_dialog_content = "きっと…いわゆる「スランプ」ってやつだね！",
  ui_story_5037_50371301_9_dialog_content = "…それで、そのスランプを解消して最高の状態で\n「卒業コンサート」を迎えるために、私とフィアで思いついたことがあるの！",
  ui_story_5037_50371301_10_dialog_content = "ズバリ――プロデューサー交換よ！",
  ui_story_5037_50371301_11_dialog_content = "交換！？",
  ui_story_5037_50371301_12_dialog_content = "そう、PlayerNameがダメ師匠の練習を見て、\nあたしとゴルディお姉ちゃんがタッグを組むの！",
  ui_story_5037_50371301_13_dialog_content = "1日だけ交換して、それぞれ練習するんだよ！",
  ui_story_5037_50371301_14_dialog_content = "いつもと違う練習法とパートナーなら、\n何か気づくことがあるかもしれないでしょ。きっとスランプ解消に役立つわ。",
  ui_story_5037_50371301_15_dialog_content = "てことは、僕がヴィックの練習を見るの？",
  ui_story_5037_50371301_16_dialog_content = "おお？そりゃいい案じゃないか。\nこれで俺も少しは楽に――",
  ui_story_5037_50371301_17_dialog_content = "アイタタタタ！フィア、俺の足を蹴るなって！",
  ui_story_5037_50371301_18_dialog_content = "PlayerName、師匠がサボらないようにキャロも預けておくね！",
  ui_story_5037_50371301_19_dialog_content = "ルルル！",
  ui_story_5037_50371301_20_dialog_content = "もし師匠がサボろうとしたら、キャロがかんで\nしっかり練習するように注意してくれるから！安心して。",
  ui_story_5037_50371301_21_dialog_content = "アハハ、フィアは本当に気が利くね…",
  ui_story_5037_50371301_22_dialog_content = "それじゃ、これで決まりね。",
  ui_story_5037_50371301_23_dialog_content = "PlayerName、いつも私の練習を見てくれてる時みたいに、\nヴィックを指導してあげてね！",
  ui_story_5037_50371301_24_dialog_content = "あなたならできるわ！",
  ui_story_5037_50371301_25_dialog_content = "うん、任せて。",
  ui_story_5037_50371301_26_dialog_content = "じゃあ、あたしたちは行くね。バイバ～イ。",
  ui_story_5037_50371301_27_dialog_content = "さーて、じゃあ俺も休むとするか――",
  ui_story_5037_50371301_28_dialog_content = "うわあああ！！",
  ui_story_5037_50371301_29_dialog_content = "キャロ！放せ！俺の太ももなんてうまくないぞ！！",
  ui_story_5037_50371301_30_dialog_content = "ルルル！",
  ui_story_5037_50371301_31_dialog_content = "君がサボろうとしたから、\n練習させようとしてるんだね。",
  ui_story_5037_50371301_32_dialog_content = "はぁ…まったく、親みたいに育ててやったって言うのに、\nフィアと仲良くなったとたんに俺のことを忘れやがって…",
  ui_story_5037_50371301_33_dialog_content = "いいか？お前を育てて生きる術を教えてやったのは、\nこの俺――",
  ui_story_5037_50371301_34_dialog_content = "ぎゃあ――！！",
  ui_story_5037_50371301_35_dialog_content = "早く練習を始めた方がいいんじゃない…？\n放っておいたら、また噛まれそうだよ。",
  ui_story_5037_50371301_36_dialog_content = "うう、なんだっていつも俺ばかり…",
  ui_story_5037_50371301_37_dialog_content = "安心して、僕の立てる計画には適度な休憩も入れてあるから、\nそんなに大変じゃないよ。",
  ui_story_5037_50371301_38_dialog_content = "それじゃ、まずはボイストレーニングから始めようか。",
  ui_story_5037_50371301_39_dialog_content = "<color=#828282>しばらくして</color>",
  ui_story_5037_50371301_40_dialog_content = "♪みんな元気な春がやってきた♪",
  ui_story_5037_50371301_41_dialog_content = "♪動物たちも家からぴょこん♪",
  ui_story_5037_50371301_42_dialog_content = "♪森も荒れ野もあちこちに♪",
  ui_story_5037_50371301_43_dialog_content = "よし、これを歌い終わったら休憩にしよう。",
  ui_story_5037_50371301_44_dialog_content = "そりゃありがたい！やっと休めるぞ！",
  ui_story_5037_50371301_45_dialog_content = "ル…",
  ui_story_5037_50371301_46_dialog_content = "おいおい、キャロ。\n俺はサボってるんじゃないぞ、これは正当な休憩時間だ！",
  ui_story_5037_50371301_47_dialog_content = "そういえばずっと気になってたんだけど、\nどうして急にアイドルになろうと思ったの？",
  ui_story_5037_50371301_48_dialog_content = "ん？その質問は、そもそも根っこから間違ってるな。",
  ui_story_5037_50371301_49_dialog_content = "えっ？",
  ui_story_5037_50371301_50_dialog_content = "いいか、俺はアイドルなんかじゃない。\n俺の職業はただ1つ、珍獣の研究者だ！",
  ui_story_5037_50371301_51_dialog_content = "えっと…だったら、どうしてこんな対決に参加したの？",
  ui_story_5037_50371301_52_dialog_content = "もちろん、カネのためさ！それ以外ない！",
  ui_story_5037_50371301_53_dialog_content = "本当にお金目当てだったんだ…",
  ui_story_5037_50371301_54_dialog_content = "ヴィックが貧乏なのは僕も知ってるし、\n確かにシェオルさんが出すって言ってる賞金はそうとうだけど…",
  ui_story_5037_50371301_55_dialog_content = "だったらどうして、フィアまで参加してるの？",
  ui_story_5037_50371301_56_dialog_content = "それはな、そもそも宣伝ポスターを見たフィアが\n俺を参加させるって引っ張り出したからさ。",
  ui_story_5037_50371301_57_dialog_content = "珍獣を世話する金もまるで足りないからな…",
  ui_story_5037_50371301_58_dialog_content = "足りないって、どのぐらい？",
  ui_story_5037_50371301_59_dialog_content = "ビッカーとドラゴライオンの\n先月のおやつ代もまだ払えてない！",
  ui_story_5037_50371301_60_dialog_content = "そんなに大変なの！？",
  ui_story_5037_50371301_61_dialog_content = "いや、そうじゃない…\nお金が厳しいなら、おやつは控えればいいんじゃない？",
  ui_story_5037_50371301_62_dialog_content = "そりゃあダメだ！",
  ui_story_5037_50371301_63_dialog_content = "珍獣たちはみんな俺の仲間なんだ。\nあいつらに苦労させるワケにはいかない。",
  ui_story_5037_50371301_64_dialog_content = "普段はフィアとシーラが研究しながら働いて稼いでるから、\n支払いができないってことはないんだが…",
  ui_story_5037_50371301_65_dialog_content = "ちょっと前に、フィアを超希少種の調査に行かせたら、\n思ったより手間どっちまってな。",
  ui_story_5037_50371301_66_dialog_content = "それで収入が支出に追いつかなくなって、\n払えなくなったってワケだ！",
  ui_story_5037_50371301_67_dialog_content = "…その間、ヴィックは何してたの？",
  ui_story_5037_50371301_68_dialog_content = "俺か？もちろん珍獣の世話をしてたぞ。\nそれから、しっかり休んでたな。",
  ui_story_5037_50371301_69_dialog_content = "それって、ただダラダラしてたってことでしょ！",
  ui_story_5037_50371301_70_dialog_content = "フィアとシーラが苦労してる理由、\nよ～く分かった気がする…",
  ui_story_5037_50371301_71_dialog_content = "おいおい、俺だってこうして金を稼ぎに来てるだろ？\nしかもステージに上がるほうで！",
  ui_story_5037_50371301_72_dialog_content = "それに、今日の今日までちゃーんと頑張ってきた！",
  ui_story_5037_50371301_73_dialog_content = "うーん…そうだね。確かに君にしては珍しいのかも。\nてっきり途中で投げ出して、逃げ出すとばかり思ってたけど…",
  ui_story_5037_50371301_74_dialog_content = "珍獣たちの食事代が足りないってのは一大事なんだ。\n逃げ出せるワケないだろ！？",
  ui_story_5037_50371301_75_dialog_content = "珍獣たちのためなら、どんな苦労だって怖くないさ。",
  ui_story_5037_50371301_76_dialog_content = "それなりの報酬を出すって言うなら、フィアとシーラも一緒に\nPlayerNameの使いっ走りになってやってもいいぐらいだ！",
  ui_story_5037_50371301_77_dialog_content = "それは遠慮しておくよ。\nフィアとシーラにこれ以上迷惑かけるのはかわいそうだし…",
  ui_story_5037_50371301_78_dialog_content = "まったく、ヴィックを見てると時々、自分の弟子より\nモジャの方を可愛がってるんじゃないかって思えてくるよ。",
  ui_story_5037_50371301_79_dialog_content = "それは大間違いだぜ。\nフィアもシーラも俺の自慢の弟子だ！",
  ui_story_5037_50371301_80_dialog_content = "俺の持ってる珍獣の知識を全部受け継いだだけじゃない。\nあいつらはちゃんと自分で自分の面倒を見られるんだ。",
  ui_story_5037_50371301_81_dialog_content = "おまけに、強い。\n暗鬼に遭っても、ちっとも怖気づかないだろ？",
  ui_story_5037_50371301_82_dialog_content = "そう遠くないうちに、\nアストラ大陸全部の珍獣研究を任せられるようになるかもしれないな。",
  ui_story_5037_50371301_83_dialog_content = "そうなったら、君はどうするの？\nどこかで好きなだけ寝てる？",
  ui_story_5037_50371301_84_dialog_content = "おおっ、そりゃいい考えだ。\n参考にさせてもらうか…",
  ui_story_5037_50371301_85_dialog_content = "だが、その前に俺にもやらなきゃいけないことがあるんだ。",
  ui_story_5037_50371301_86_dialog_content = "この世界にはアストラ大陸以外にも、\nきっと別の大陸が存在する。",
  ui_story_5037_50371301_87_dialog_content = "俺はその新しい大陸で、もっとたくさんの珍獣を探して、\nそいつらの特徴やら生態やらを研究して、記録したいんだ。",
  ui_story_5037_50371301_88_dialog_content = "そんな壮大な夢を持ってたなんて…",
  ui_story_5037_50371301_89_dialog_content = "当たり前だろ。なんたって俺は――",
  ui_story_5037_50371301_90_dialog_content = "うぎゃあああ！！",
  ui_story_5037_50371301_91_dialog_content = "キャロ、なんで噛みつくんだ！？",
  ui_story_5037_50371301_92_dialog_content = "あ、休憩時間が終わってる。\nキャロが練習をまた始める時間だって教えてくれたんだ！",
  ui_story_5037_50371301_93_dialog_content = "キャロめ、フィアからヘンなことばっかり教わりやがって…\nあいつより厳しいじゃないか！",
  ui_story_5037_50371301_94_dialog_content = "…なあ、今日はPlayerNameが俺のプロデューサーだろ？\nだからさ、休憩時間をちょっとばかり延ばしてもらえないかなー、なんて…",
  ui_story_5037_50371301_95_dialog_content = "う～ん…",
  ui_story_5037_50371301_96_dialog_content = "代わりにモジャを1日貸してやる！なで放題だ！",
  ui_story_5037_50371301_97_dialog_content = "…分かった。君がそういうなら、今日の練習は――",
  ui_story_5037_50371301_98_option_content = "いつもの倍にしよう！",
  ui_story_5037_50371301_99_option_content = "いつもの3倍にしよう！",
  ui_story_5037_50371301_100_dialog_content = "ちょうどゴルディのために、\nスランプ解消の練習メニューを立ててたんだ。",
  ui_story_5037_50371301_101_dialog_content = "ちょっとキツすぎるかなと思って、ずっと試してなかったんだけど…\nヴィックが相手ならちょうどいいし、この機会に試してみよう！",
  ui_story_5037_50371301_102_dialog_content = "なに！？",
  ui_story_5037_50371301_103_dialog_content = "心配しないで。今後のゴルディの練習量を調整するために、\n効果を確かめるだけだから。",
  ui_story_5037_50371301_104_dialog_content = "もちろん、君自身のスキルアップにも役立つよ！",
  ui_story_5037_50371301_105_dialog_content = "フィアの苦労をムダにしないためにも、\n全力で練習してね！",
  ui_story_5037_50371301_106_dialog_content = "カンベンしてくれ――！！",
  ui_story_5037_50371401_1_dialog_content = "PlayerNameチームの緊急会議。\n3、2、1…アクション！",
  ui_story_5037_50371401_2_dialog_content = "これって、撮影する必要あるのかしら？",
  ui_story_5037_50371401_3_dialog_content = "もちろんよ！優れた監督たる者、\n貴重な素材は一つとして逃すわけにはいかないわ！",
  ui_story_5037_50371401_4_dialog_content = "そう…？",
  ui_story_5037_50371401_5_dialog_content = "では、第1回「プロデューサー速成講座」を始めるわ。",
  ui_story_5037_50371401_6_dialog_content = "…",
  ui_story_5037_50371401_7_dialog_content = "（隅っこに本が山のように積んである…）",
  ui_story_5037_50371401_8_dialog_content = "（これ、全部バイスとカレンが持ってきたのかな？）",
  ui_story_5037_50371401_9_dialog_content = "（2人とも表情が険しいし、なんだか不安になってきた…）",
  ui_story_5037_50371401_10_dialog_content = "2人とも、どうしてそんな怖い顔してるの…？",
  ui_story_5037_50371401_11_dialog_content = "PlayerNameが無事にプロデューサーになれるかどうかがかかってるのよ。\n真剣になって当然でしょ！",
  ui_story_5037_50371401_12_dialog_content = "その通りよ。いい加減なことはできないわ。",
  ui_story_5037_50371401_13_dialog_content = "そっか…色々とありがとう。\n本当なら、僕が自分ひとりで頑張らなきゃいけないのに…",
  ui_story_5037_50371401_14_dialog_content = "何言ってるの？PlayerNameの仲間として、\n私たちはいつだって協力を惜しまないわよ！",
  ui_story_5037_50371401_15_dialog_content = "あなたができるだけ早く「プロデューサー」業務を理解できるように、\nバイスと2人で分析をしてみたの。",
  ui_story_5037_50371401_16_dialog_content = "そうそう。「アイドル」から「プロデューサー」に関するものまで、\n必要な資料は全部そろえたわ。",
  ui_story_5037_50371401_17_dialog_content = "今日からここは、「プロデューサー速成講座」の教室よ！",
  ui_story_5037_50371401_18_dialog_content = "これは…ノートと新聞の切り抜き！？",
  ui_story_5037_50371401_19_dialog_content = "そう！カレンが図書館で歌手やダンサーの育成に関する本を\n一通り調べて、ノートにまとめてくれたの。",
  ui_story_5037_50371401_20_dialog_content = "私も影ノ街で出てる、ここ数年ぶんの新聞を全部１部ずつ買って、\nアイドルとプロデューサーに関する記事を収集したわ。",
  ui_story_5037_50371401_21_dialog_content = "す、すごい…！！",
  ui_story_5037_50371401_22_dialog_content = "でも、大変だったでしょ…？調べた資料全部をノートにまとめるなんて、\nいったいどれだけの時間が…",
  ui_story_5037_50371401_23_dialog_content = "ノートについては、たまたま通りかかった\nクロエとキーティンも手伝ってくれたわ。",
  ui_story_5037_50371401_24_dialog_content = "音楽に関する知識が豊富だから、\nずいぶん助かったわね。",
  ui_story_5037_50371401_25_dialog_content = "私もブランディに手伝ってもらったの。",
  ui_story_5037_50371401_26_dialog_content = "ほら、彼女はプロの記者でしょ？\n新聞とか報道とかに関しては私より詳しいもの！",
  ui_story_5037_50371401_27_dialog_content = "つまり、今ここにある資料は全部、\n皆があなたのために頑張った成果なのよ。",
  ui_story_5037_50371401_28_dialog_content = "本当にその通りだね…",
  ui_story_5037_50371401_29_dialog_content = "皆の労力に報いるためにも、絶対に頑張るよ！",
  ui_story_5037_50371401_30_dialog_content = "それじゃ、今日の会議についてもう少し詳しく説明するわね！",
  ui_story_5037_50371401_31_dialog_content = "この会議のもう1つの目的は、\nPlayerNameの育成プランを立てることよ。",
  ui_story_5037_50371401_32_dialog_content = "育成プラン？",
  ui_story_5037_50371401_33_dialog_content = "ええ、2つのプランを用意してあるわ。\n自分に合っていると思う方を選んで。",
  ui_story_5037_50371401_34_dialog_content = "1つ目のプランは、「ゼロから学ぶプロデューサー」よ。",
  ui_story_5037_50371401_35_dialog_content = "分厚いね！？",
  ui_story_5037_50371401_36_dialog_content = "プロデューサーに必要な基礎知識からより専門的な企画知識までを\n集めたものよ。\nただ、内容が煩雑になるから、学ぶのに相応の時間がかかるわ。",
  ui_story_5037_50371401_37_dialog_content = "もう1つのプランはどんな感じなの？",
  ui_story_5037_50371401_38_dialog_content = "もう1つのプランは「プロデューサー、そのプロになるために」よ。\n歴代の著名な学者が提唱した、時間の使い方に関するコツをまとめてあるの。",
  ui_story_5037_50371401_39_dialog_content = "ただ、それ相応の基礎がないと学ぶのは難しいわね。",
  ui_story_5037_50371401_40_dialog_content = "PlayerName、自分の状況に合わせて、いいと思う方を選んで！",
  ui_story_5037_50371401_41_dialog_content = "僕に合ったプランか…",
  ui_story_5037_50371401_42_dialog_content = "今はまだ新米プロデューサーだから――",
  ui_story_5037_50371401_43_option_content = "「ゼロから学ぶプロデューサー」にする",
  ui_story_5037_50371401_44_dialog_content = "基礎から学ぶのが一番だよね！",
  ui_story_5037_50371401_45_dialog_content = "私も同感よ。",
  ui_story_5037_50371401_46_dialog_content = "じゃあ、早速こっちのプランで\nプロデューサー業務について学びましょ！",
  ui_story_5037_50371401_47_dialog_content = "うん、頑張るよ！",
  ui_story_5037_50371401_48_dialog_content = "<color=#828282>しばらくして</color>",
  ui_story_5037_50371401_49_dialog_content = "プロデューサーの主な仕事は…\nスケジュール作成に企画…それと…",
  ui_story_5037_50371401_50_dialog_content = "…それから何だったっけ…？また忘れちゃった…",
  ui_story_5037_50371401_51_dialog_content = "PlayerName、少し休憩しましょ。",
  ui_story_5037_50371401_52_dialog_content = "頭に入れるべき知識はもう十分学んだはずよ。\nあとは、その知識を普段の実践に活かしていくだけね。",
  ui_story_5037_50371401_53_option_content = "「プロデューサー、プロになるために」にする",
  ui_story_5037_50371401_54_dialog_content = "そもそもチャレンジだらけなんだ。\nだったらいっそ、難しいところから始めるのもいいかもしれない！",
  ui_story_5037_50371401_55_dialog_content = "えっ、いきなり難しいところから始めるの！？",
  ui_story_5037_50371401_56_dialog_content = "あなたがそうしたいなら、こちらは全力でサポートするわ。",
  ui_story_5037_50371401_57_dialog_content = "う、うん…きっと大丈夫だよ！",
  ui_story_5037_50371401_58_dialog_content = "<color=#828282>しばらくして</color>",
  ui_story_5037_50371401_59_dialog_content = "難しい…",
  ui_story_5037_50371401_60_dialog_content = "PlayerNameには、このプランはちょっと難しかったわね…",
  ui_story_5037_50371401_61_dialog_content = "資料を整理してる時に思ったのだけれど、\n色々な要素が互いに関係しながら複雑に絡み合っているのよね。",
  ui_story_5037_50371401_62_dialog_content = "やっぱり段階を踏んで、\n少しずつ学んでいかなきゃいけなさそうだね…",
  ui_story_5037_50371401_63_dialog_content = "今日はもう遅いし、ここまでにしましょ。",
  ui_story_5037_50371401_64_dialog_content = "PlayerName、お疲れ様！",
  ui_story_5037_50371401_65_dialog_content = "お疲れ様。",
  ui_story_5037_50371401_66_dialog_content = "それはこっちのセリフだよ。こんなにたくさんの資料を集めて、\n僕なんかよりずっと大変だったよね？",
  ui_story_5037_50371401_67_dialog_content = "私たち3人の仲じゃない。そんな他人行儀はいらないわ。",
  ui_story_5037_50371401_68_dialog_content = "とにかく、早めに休んでね！",
  ui_story_5037_50371401_69_dialog_content = "うん、バイスとカレンもね！",
  ui_story_5037_50371401_70_dialog_content = "いえ、私たちの方はまだ用事があるから、出かけなくちゃいけないの。",
  ui_story_5037_50371401_71_dialog_content = "えっ、これから？でもどこに…？",
  ui_story_5037_50371401_72_dialog_content = "歌唱力で有名な光霊数名の話を聞きにいくのよ。\nステージ上で歌うコツを教えてもらおうかなと思って。",
  ui_story_5037_50371401_73_dialog_content = "具体的な表現の形は違っても、\n歌そのものの技術の多くはきっと共通しているでしょうから。",
  ui_story_5037_50371401_74_dialog_content = "そうした技術が、ゴルディにとってのヒントか何かになればと思ったの。",
  ui_story_5037_50371401_75_dialog_content = "でも2人とも、プラン作りだけでもう十分時間と労力を使ってるでしょ？",
  ui_story_5037_50371401_76_dialog_content = "いま本当に休む必要があるのは君たちの方だと思うよ…",
  ui_story_5037_50371401_77_dialog_content = "私なら心配いらないわ。まだまだ元気だから！",
  ui_story_5037_50371401_78_dialog_content = "ええ。なかなかできない体験だから、\nこれでも結構楽しんでいるのよ。",
  ui_story_5037_50371401_79_dialog_content = "新鮮なことばかりだからか、忙しくても疲れを感じないくらいに。",
  ui_story_5037_50371401_80_dialog_content = "そういうのは、PlayerNameも同じでしょ？",
  ui_story_5037_50371401_81_dialog_content = "確かに…",
  ui_story_5037_50371401_82_dialog_content = "プロデューサーをやるようになってからずっと、\nほぼ毎日朝から晩まで忙しくしてるけど…",
  ui_story_5037_50371401_83_dialog_content = "でも、毎日色々新鮮なことに触れられるから、\nちっとも疲れたって感じがしないんだ。",
  ui_story_5037_50371401_84_dialog_content = "地下から出てきて、皆と出会った頃と似た感覚かもしれない。",
  ui_story_5037_50371401_85_dialog_content = "あの頃も…暗鬼に追いかけられてるのに、\n少しも悲観的になったり、疲れを感じたりしなかった。",
  ui_story_5037_50371401_86_dialog_content = "ふふ、分かるわ。\n新しいことを始めた時の高揚感ってそういうものよね！",
  ui_story_5037_50371401_87_dialog_content = "うん！",
  ui_story_5037_50371401_88_dialog_content = "とはいえ、君たちばかりに負担はかけていられないよ。",
  ui_story_5037_50371401_89_dialog_content = "えっ？",
  ui_story_5037_50371401_90_dialog_content = "どうしてかしら？",
  ui_story_5037_50371401_91_dialog_content = "だって、僕たちはいつだって一緒だったでしょ？",
  ui_story_5037_50371401_92_dialog_content = "旅であろうと冒険であろうと、\n僕たちはいつだって仲間だ。",
  ui_story_5037_50371401_93_dialog_content = "だから、今日も一緒に行こう！",
  ui_story_5037_50371401_94_dialog_content = "でも――",
  ui_story_5037_50371401_95_dialog_content = "僕のことなら心配しないで。今まで通り、一緒に頑張ろうよ！",
  ui_story_5037_50371401_96_dialog_content = "…ええ、そうね。今まで通りに！",
  ui_story_5037_50371501_1_dialog_content = "PlayerNameチーム、臨時会議。\n3、2、1…アクション！",
  ui_story_5037_50371501_2_dialog_content = "ごめん、遅くなっちゃった！",
  ui_story_5037_50371501_3_dialog_content = "気にしないで！来てくれればそれでいいわ。",
  ui_story_5037_50371501_4_dialog_content = "あら？ゴルディは？",
  ui_story_5037_50371501_5_dialog_content = "シェオルさんと今後について話してるから、\nもうしばらくかかると思う。",
  ui_story_5037_50371501_6_dialog_content = "そう、残念ね…",
  ui_story_5037_50371501_7_dialog_content = "残念？",
  ui_story_5037_50371501_8_dialog_content = "実は、デビューコンサートの成功をお祝いしようと思っていたのよ。",
  ui_story_5037_50371501_9_dialog_content = "あなたとゴルディが来たら、一緒にお茶を飲みながら\n用意したお菓子でも食べようかと思ってたの。",
  ui_story_5037_50371501_10_dialog_content = "そうだったんだ…ありがとう！\n大丈夫、ゴルディには僕があとでお菓子を持って行くよ。",
  ui_story_5037_50371501_11_dialog_content = "分かったわ。とはいえ、ゴルディが来られないのは残念ね…",
  ui_story_5037_50371501_12_dialog_content = "皆で食べようと思って、頑張ってクッキーを焼いたから…",
  ui_story_5037_50371501_13_dialog_content = "何度も焦がしちゃったけど、最後にはちゃんと焼き上がったのよ。",
  ui_story_5037_50371501_14_dialog_content = "そっか…色々ありがとう…",
  ui_story_5037_50371501_15_dialog_content = "（そんなに頑張って焼いたなら、たぶん大丈夫だよね…？）",
  ui_story_5037_50371501_16_dialog_content = "デビューコンサートももう終わりだなんて、\n時間が経つのは早いわね。",
  ui_story_5037_50371501_17_dialog_content = "そうね。「プロデューサー速成講座」も開いてから\nもうずいぶんになるし…",
  ui_story_5037_50371501_18_dialog_content = "最初の頃は、皆あたふたしてたけど…",
  ui_story_5037_50371501_19_dialog_content = "今じゃもう、PlayerNameはゴルディのデビューコンサートを\n見事にやり遂げるくらいまでになったんだもの。",
  ui_story_5037_50371501_20_dialog_content = "もう一人前の、頼れるプロデューサーね。",
  ui_story_5037_50371501_21_dialog_content = "本当にそうね。この期間で明らかな進歩があったわ！",
  ui_story_5037_50371501_22_dialog_content = "へへ、ありがとう！なんだか照れちゃうな。",
  ui_story_5037_50371501_23_dialog_content = "おめでとう！",
  ui_story_5037_50371501_24_dialog_content = "おめでとう、PlayerName。",
  ui_story_5037_50371501_25_dialog_content = "ありがとう！",
  ui_story_5037_50371501_26_dialog_content = "それじゃ、お祝いの席を始めましょ！",
  ui_story_5037_50371501_27_dialog_content = "お茶が冷めちゃうわ！",
  ui_story_5037_50371501_28_dialog_content = "<color=#828282>ガサッ――</color>",
  ui_story_5037_50371501_29_dialog_content = "今、何か変な音がしなかった？",
  ui_story_5037_50371501_30_dialog_content = "え？そう？",
  ui_story_5037_50371501_31_dialog_content = "<color=#828282>ガサガサッ――</color>",
  ui_story_5037_50371501_32_dialog_content = "ほら、また聞こえたわ。\n楽器が置いてある、あの隅のほう。",
  ui_story_5037_50371501_33_dialog_content = "風で物音がしたのかな？",
  ui_story_5037_50371501_34_dialog_content = "<color=#828282>ガサッ――</color>",
  ui_story_5037_50371501_35_dialog_content = "…",
  ui_story_5037_50371501_36_dialog_content = "なにか、ドラムの後ろに隠れてるみたいね…？",
  ui_story_5037_50371501_37_dialog_content = "まさか…暗鬼？",
  ui_story_5037_50371501_38_dialog_content = "…探りを入れてみましょう。",
  ui_story_5037_50371501_39_dialog_content = "氷花よ――",
  ui_story_5037_50371501_40_dialog_content = "ル！ルルル！",
  ui_story_5037_50371501_41_dialog_content = "あら？もしかしてキャロ？",
  ui_story_5037_50371501_42_dialog_content = "いつもフィアと一緒のはずなのに、\nどうしてこんなところにいるんだろう？",
  ui_story_5037_50371501_43_dialog_content = "ルル…\n（フィアにPlayerNameチームの様子を探ってくるように言われたルル）",
  ui_story_5037_50371501_44_dialog_content = "ルルル！（こんなに人がたくさんいるなんて聞いてなかったルル）",
  ui_story_5037_50371501_45_dialog_content = "ルル、ル。（見つかったルル、スキを見て逃げなくてはルル）",
  ui_story_5037_50371501_46_dialog_content = "まさか、こちらの様子を探りに来たのかしら？",
  ui_story_5037_50371501_47_dialog_content = "ル、ルル！",
  ui_story_5037_50371501_48_dialog_content = "違うって言ってるみたいね。",
  ui_story_5037_50371501_49_dialog_content = "…それもそうね。キャロのことだから、\nきっと食べ物を探しているうちに迷いこんだのでしょう。",
  ui_story_5037_50371501_50_dialog_content = "フィアがあまりにもキツい練習をヴィックに強いるから、\nそれを見かねてこっそり逃げ出してきたのかな？",
  ui_story_5037_50371501_51_dialog_content = "ルルル！",
  ui_story_5037_50371501_52_dialog_content = "そうだって言ってるみたいだね。",
  ui_story_5037_50371501_53_dialog_content = "かわいそうに…毎日ヴィックの練習を見張って、\nきっと疲れちゃったのね…",
  ui_story_5037_50371501_54_dialog_content = "ル…",
  ui_story_5037_50371501_55_dialog_content = "ここで少し休ませてあげたらいいわ。\nお菓子もたくさんあるのだし、キャロにも分けてあげるのはどうかしら。",
  ui_story_5037_50371501_56_dialog_content = "うん、そうだね！あとでフィアのところに僕が送っていくよ。",
  ui_story_5037_50371501_57_dialog_content = "ルル～ルルル～！（よかった、情報を探りに来たってバレなかったルル）",
  ui_story_5037_50371501_58_dialog_content = "ルル！（しかもお菓子をもらえるルル。何をくれるのルル？）",
  ui_story_5037_50371501_59_dialog_content = "そういえば…フィアがこの前、\nキャロは動物クッキーが好きだって言ってたわね。",
  ui_story_5037_50371501_60_dialog_content = "私の焼いたクッキー、キャロに気に入ってもらえるかしら…",
  ui_story_5037_50371501_61_dialog_content = "（あ、こ、これは…！）",
  ui_story_5037_50371501_62_dialog_content = "（「あの時」と同じだ！）",
  ui_story_5037_50371501_63_dialog_content = "ルル！（なななな、なんだかイヤな予感がするルル！）",
  ui_story_5037_50371501_64_dialog_content = "ねえキャロ、このクッキー、私が焼いたの。\nよかったら食べてみて！",
  ui_story_5037_50371501_65_dialog_content = "白夜城のスイーツ店で売ってるのとは違って、\n見た目はよくないけど…でも、まったく同じ材料で作ってあるのよ！",
  ui_story_5037_50371501_66_dialog_content = "ルル、ル！（こ、こないでルル！）",
  ui_story_5037_50371501_67_dialog_content = "はい、あ～ん…",
  ui_story_5037_50371501_68_dialog_content = "ルルル！！",
  ui_story_5037_50371501_69_dialog_content = "逃げた！？",
  ui_story_5037_50371501_70_dialog_content = "わ、そっちには山積みの本が！",
  ui_story_5037_50371501_71_dialog_content = "キャロを捕まえなきゃ！キャロはぬるぬるしてるから、\n本が濡れちゃう！",
  ui_story_5037_50371501_72_dialog_content = "キャロ、止まって！",
  ui_story_5037_50371501_73_dialog_content = "ルルル！！",
  ui_story_5037_50371501_74_dialog_content = "（大変だ、キャロが本に一直線に向かってく！）",
  ui_story_5037_50371501_75_option_content = "専門書を守る",
  ui_story_5037_50371501_76_option_content = "雑誌を守る",
  ui_story_5037_50371501_77_dialog_content = "<color=#828282>ドン！！！</color>",
  ui_story_5037_50371501_78_dialog_content = "うわあっ！",
  ui_story_5037_50371501_79_dialog_content = "<size=45>イタッ！！</size>",
  ui_story_5037_50371501_80_dialog_content = "PlayerName！？",
  ui_story_5037_50371501_81_dialog_content = "だ、大丈夫…ちょっと、痛かっただけ…",
  ui_story_5037_50371501_82_dialog_content = "ル…",
  ui_story_5037_50371501_83_dialog_content = "ルルル～！",
  ui_story_5037_50371501_84_dialog_content = "あの子、ずいぶん足が速いのね…",
  ui_story_5037_50371501_85_dialog_content = "本のほうは？無事かしら？",
  ui_story_5037_50371501_86_dialog_content = "ケホッ、一部はちゃんと守ったから大丈夫。",
  ui_story_5037_50371501_87_dialog_content = "ノートと切り抜きも無事よ。",
  ui_story_5037_50371501_88_dialog_content = "他のは完全に濡れてしまったわね。",
  ui_story_5037_50371501_89_dialog_content = "けれど、落ち込んでいても仕方ないわ。\nまずは濡れてしまった本とそうでない本を分けましょう。",
  ui_story_5037_50371501_90_dialog_content = "1冊、2冊…",
  ui_story_5037_50371501_91_dialog_content = "こっちにある本は、乾かせばまた読めるようになりそうだよ。",
  ui_story_5037_50371501_92_dialog_content = "でも、文字が完全ににじんで\n読めなくなっちゃったのもいくつかあるね…",
  ui_story_5037_50371501_93_dialog_content = "確か、借りてきた本もあったわよね！？",
  ui_story_5037_50371501_94_dialog_content = "仕方ないわ。まずは借りた本のリストを作って、\n持ち主に謝罪と弁償をするしかないでしょうね。",
  ui_story_5037_50371501_95_dialog_content = "そうするしかないわね…",
  ui_story_5037_50371501_96_dialog_content = "僕の貯金で弁償できるかな…",
  ui_story_5037_50371501_97_dialog_content = "弁償代のことなら、私も出すわ。",
  ui_story_5037_50371501_98_dialog_content = "ええ。キャロを止められなかった責任がある以上、\n私も負担するつもりよ。",
  ui_story_5037_50371501_99_dialog_content = "だからPlayerName、心配しないで。\n私たちも一緒に弁償するから。ね！",
  ui_story_5037_50371501_100_dialog_content = "バイス、カレン…ありがとう。",
  ui_story_5037_50371501_101_dialog_content = "それと、もう1つ重要なこととして――",
  ui_story_5037_50371501_102_dialog_content = "今度フィアを見つけたら、きちんとキャロのしつけをするよう\n言わないといけないわね。",
  ui_story_5037_50371601_1_dialog_content = "PlayerNameチーム、最終会議。\n3、2、1…アクション！",
  ui_story_5037_50371601_2_dialog_content = "「最終会議」？そっか、もうそんな時期なんだね。",
  ui_story_5037_50371601_3_dialog_content = "そうよ。もう数日後には「卒業コンサート」だもの。",
  ui_story_5037_50371601_4_dialog_content = "時間が経つのは早いわね。本を大量に運び込んで\n「プロデューサー速成講座」を始めたのが昨日のことのようよ。",
  ui_story_5037_50371601_5_dialog_content = "そうだね…ところで、今日は何をするの？",
  ui_story_5037_50371601_6_dialog_content = "今日やるべきことは1つだけ――掃除と片付けよ！",
  ui_story_5037_50371601_7_dialog_content = "計画してた内容も全部学び終えて、\nPlayerNameはもう立派なプロデューサーになったわ！",
  ui_story_5037_50371601_8_dialog_content = "だから、「プロデューサー速成講座」もこれにておしまい！",
  ui_story_5037_50371601_9_dialog_content = "ええ。そういうことだから、今日は本を整理しましょう。",
  ui_story_5037_50371601_10_dialog_content = "借りてきた本をスムーズに返す下準備にもなるでしょうし。",
  ui_story_5037_50371601_11_dialog_content = "そっか、じゃあ僕も手伝うよ！",
  ui_story_5037_50371601_12_dialog_content = "こういうのは、一緒にやったほうが早いからね。",
  ui_story_5037_50371601_13_dialog_content = "ええ！",
  ui_story_5037_50371601_14_dialog_content = "<color=#828282>しばらくして</color>",
  ui_story_5037_50371601_15_dialog_content = "『計画から習慣へ――ゼロから学ぶ計画の立て方』は、\nどこに置いたらいい？",
  ui_story_5037_50371601_16_dialog_content = "それはこっちにお願い。",
  ui_story_5037_50371601_17_dialog_content = "そのシリーズはビビアン長官から借りたものなの。\n長官のオススメなのよ！",
  ui_story_5037_50371601_18_dialog_content = "これを読んだことでだんだんと計画的に時間を使えるようになったって、\n長官が言ってた本なのよ。",
  ui_story_5037_50371601_19_dialog_content = "そうなんだね。確かに役に立つことばかり書かれてて、\nすっごく参考になった記憶があるよ！",
  ui_story_5037_50371601_20_dialog_content = "PlayerName、手元にある『合唱技術300』をこっちにくれるかしら？",
  ui_story_5037_50371601_21_dialog_content = "うん、はい！",
  ui_story_5037_50371601_22_dialog_content = "これはキーティンから借りたんでしょ？",
  ui_story_5037_50371601_23_dialog_content = "どうして分かったの？",
  ui_story_5037_50371601_24_dialog_content = "だって、表紙はきれいだけど、\n中はイタズラ書きばかりだったから。",
  ui_story_5037_50371601_25_dialog_content = "特にひどいページなんて、目の下にクマをつくった僕の似顔絵まで\n描いてあったんだよ！！",
  ui_story_5037_50371601_26_dialog_content = "…ぷっ。",
  ui_story_5037_50371601_27_dialog_content = "確かに、あの子たちのやりそうなことね。",
  ui_story_5037_50371601_28_dialog_content = "もし気分を害したのなら、\n私から全部消すように言っておくわ。",
  ui_story_5037_50371601_29_dialog_content = "ううん、それはしなくていいよ…",
  ui_story_5037_50371601_30_dialog_content = "そんなことしたら、きっともっとひどい歌を作って、\n僕をバカにするんだろうなって想像がつくから…",
  ui_story_5037_50371601_31_dialog_content = "うん、やっぱりそのままにしておこう。",
  ui_story_5037_50371601_32_dialog_content = "あの子たちの口の悪さには、\n本当にひやひやさせられるものね。",
  ui_story_5037_50371601_33_dialog_content = "よし、これで本はだいたい片付いたのかな？",
  ui_story_5037_50371601_34_dialog_content = "分類のほうも全部できたわ！",
  ui_story_5037_50371601_35_dialog_content = "だけど、本の他にもまだノートがたくさん残ってるわね。",
  ui_story_5037_50371601_36_dialog_content = "このノートは…講座が始まってから今までの全記録が乗っているものね。",
  ui_story_5037_50371601_37_dialog_content = "ええ、1文字1文字が私たちの努力の証よ！",
  ui_story_5037_50371601_38_dialog_content = "ノートが山みたいにあるね…",
  ui_story_5037_50371601_39_dialog_content = "書いてる時は、こんな量になるとは思ってなかったな…\n大事だと思うことをメモしてただけだから…",
  ui_story_5037_50371601_40_dialog_content = "それがいつの間にか、こんなにたくさんたまってたんだね！",
  ui_story_5037_50371601_41_dialog_content = "塵が積もって山になったのね。",
  ui_story_5037_50371601_42_dialog_content = "ずいぶん長いことノートなんて取ってなかったから、\n学生時代に戻った気分だったわ！",
  ui_story_5037_50371601_43_dialog_content = "カレンと一緒に授業に出て、ノートをとって、ご飯を食べて…\nあの頃は毎日がのんびりと過ぎていってたよね。",
  ui_story_5037_50371601_44_dialog_content = "もちろん、試験前は別だけどね。",
  ui_story_5037_50371601_45_dialog_content = "学生時代かあ…僕には想像できないな。",
  ui_story_5037_50371601_46_dialog_content = "学校生活なんて、送ったことがないから。",
  ui_story_5037_50371601_47_dialog_content = "PlayerNameはずっと、ソラヴァンから色々教わってたのよね？",
  ui_story_5037_50371601_48_dialog_content = "そうすると、確かに誰かと一緒に勉強したり毎日を過ごしたりするのは、\nなかなか想像できないわよね…",
  ui_story_5037_50371601_49_dialog_content = "でもそうね、旅行と同じようなものよ。\n唯一の違いは…暗鬼と戦わなくて済むってことかしら？",
  ui_story_5037_50371601_50_dialog_content = "もし機会があれば、今度一緒に黎明学院へ見学にでもどうかしら。",
  ui_story_5037_50371601_51_dialog_content = "今回プロデューサーを体験したように、\n学校生活を体験してみるといいわ。",
  ui_story_5037_50371601_52_dialog_content = "いいね！あ、でも、試験はナシだよ！？",
  ui_story_5037_50371601_53_dialog_content = "ずっと忙しかったから、だいぶ疲れちゃってて…",
  ui_story_5037_50371601_54_dialog_content = "だから今一番やりたいことは、試験や審査のことを考えずに、\nゆっくり休むことなんだ！",
  ui_story_5037_50371601_55_option_content = "でも、まだ気は抜けない",
  ui_story_5037_50371601_56_dialog_content = "最後のコンサートに向けて、\nやらなきゃいけないことがまだたくさん残ってるからね。",
  ui_story_5037_50371601_57_dialog_content = "いま気を抜いたら、今までの努力がムダになっちゃうよ。",
  ui_story_5037_50371601_58_dialog_content = "PlayerNameは、いつだって新しいことに夢中になっているわよね。",
  ui_story_5037_50371601_59_dialog_content = "17年間ずっと地下で暮らしてたからね…",
  ui_story_5037_50371601_60_dialog_content = "だからこそ、どんなことでも試してみたいの？",
  ui_story_5037_50371601_61_dialog_content = "うん、そうなんだ！",
  ui_story_5037_50371601_62_option_content = "今すぐ横になりたいくらいだよ",
  ui_story_5037_50371601_63_dialog_content = "プロデューサーの仕事を始めたばかりの頃は\nすごく新鮮に感じたけど、今はもうだいぶ慣れてきて――",
  ui_story_5037_50371601_64_dialog_content = "毎日ずっと同じことの繰り返しだから、\n最近は達成感こそあっても、ちょっと退屈になる時があるんだ…",
  ui_story_5037_50371601_65_dialog_content = "分かるわ、その気持ち…",
  ui_story_5037_50371601_66_dialog_content = "どんなに面白いことでも、毎日繰り返してたら\n味気がなくなってしまうものよね。",
  ui_story_5037_50371601_67_dialog_content = "だからこそ、新しいことに挑戦し続けなければならないのよ。",
  ui_story_5037_50371601_68_dialog_content = "いずれにしても、プロデューサーになったことは\nとても貴重な経験だったよ。",
  ui_story_5037_50371601_69_dialog_content = "ゴルディのコンサートの手伝いができただけじゃなく、\n2人とこうして一緒に勉強できたんだから！",
  ui_story_5037_50371601_70_dialog_content = "こんな経験ができて、本当にうれしいよ！",
  ui_story_5037_50371601_71_dialog_content = "今のPlayerNameなら、このままプロデューサーを続けても\nきっと大きな業績を残せるでしょうね。",
  ui_story_5037_50371601_72_dialog_content = "ねえPlayerName、プロデューサー業と旅をすること、どっちが好き？",
  ui_story_5037_50371601_73_dialog_content = "もちろん…決まってるよ！",
  ui_story_5037_50371601_74_dialog_content = "！",
  ui_story_5037_50371601_75_dialog_content = "皆と一緒に旅をしている時が、一番楽しい！",
  ui_story_5037_50371701_1_dialog_content = "あれ、フロリナ？君が来てくれるなんて思わなかったよ！\nありがとう！",
  ui_story_5037_50371701_2_dialog_content = "でも、もしコンサートを観に来たのなら開催は数日後だよ。\nゴルディはまだ練習中なんだ。",
  ui_story_5037_50371701_3_dialog_content = "いえ、コンサートを聞きに来たわけじゃないわ。",
  ui_story_5037_50371701_4_dialog_content = "えっ？",
  ui_story_5037_50371701_5_dialog_content = "お手伝いにきたの。",
  ui_story_5037_50371701_6_dialog_content = "プロデューサーっていう仕事に取り組んでるんでしょ。\n新しい職業らしいわね。",
  ui_story_5037_50371701_7_dialog_content = "それで、友だちとして聞きにきたの――",
  ui_story_5037_50371701_8_dialog_content = "ねえ、何か手伝えることはない？",
  ui_story_5037_50371701_9_dialog_content = "そうだな…今は特にはないかな。",
  ui_story_5037_50371701_10_dialog_content = "…そう…",
  ui_story_5037_50371701_11_dialog_content = "（あれ？何だかガッカリしてる…？）",
  ui_story_5037_50371701_12_dialog_content = "（せっかく来たのに手伝うことがなくて、気落ちしてるのかな…？）",
  ui_story_5037_50371701_13_dialog_content = "いや…じ、実は手伝ってほしいんだ！",
  ui_story_5037_50371701_14_dialog_content = "そうなの？",
  ui_story_5037_50371701_15_dialog_content = "（えーと…何て言おう？）",
  ui_story_5037_50371701_16_dialog_content = "（ガッカリさせたくないけど、面倒もかけたくないし…）",
  ui_story_5037_50371701_17_dialog_content = "（そういえばフロリナは昔、生徒会長をやってたんだっけ。じゃあ――）",
  ui_story_5037_50371701_18_option_content = "編曲について聞く",
  ui_story_5037_50371701_19_dialog_content = "ゴルディが新しい曲を作ったんだけど、まだどんなコードやアレンジをつけるか\n決めてないんだ。何かいい案はないかな？",
  ui_story_5037_50371701_20_dialog_content = "曲のアレンジ…？そういうことは得意じゃないの。",
  ui_story_5037_50371701_21_dialog_content = "ただ、オペラならよく聴きに行くから、\n少しは音楽のことも分かってるつもりよ。できる限りのことはするわ！",
  ui_story_5037_50371701_22_dialog_content = "ありがとう！",
  ui_story_5037_50371701_23_option_content = "勉強の仕方について聞く",
  ui_story_5037_50371701_24_dialog_content = "ゴルディからよく歌について意見を求められるんだけど、\nあんまり詳しくなくて。",
  ui_story_5037_50371701_25_dialog_content = "どうやったら短期間でボーカル関連の知識を学んで、\nヒントになるような意見を言えるようになれるかな？",
  ui_story_5037_50371701_26_dialog_content = "それなら、あたしに聞いて正解ね。「系統的な学び方」については、\nかなりの心得があるの。全部教えてあげるわ。",
  ui_story_5037_50371701_27_dialog_content = "ありがとう、助かるよ！",
  ui_story_5037_50371701_28_dialog_content = "<color=#828282>しばらくして</color>",
  ui_story_5037_50371701_29_dialog_content = "――これで、私の知ってることは全部よ。",
  ui_story_5037_50371701_30_dialog_content = "あ、待って。さっきの部分で、よく分からないところがまだあるんだ。",
  ui_story_5037_50371701_31_dialog_content = "ええと、ノートには確か…",
  ui_story_5037_50371701_32_dialog_content = "ノート、よく取れてるわね。いい習慣だと思うな。",
  ui_story_5037_50371701_33_dialog_content = "僕は忘れっぽいから、勉強する時はいつもノートをとるようにしてるんだ。",
  ui_story_5037_50371701_34_dialog_content = "いつも付けている日記も同じようなものかな。\n自分が経験したことを忘れたくないから、日記に書いておくんだ。",
  ui_story_5037_50371701_35_dialog_content = "やっぱり、「記憶より記録の方が確か」だよね。",
  ui_story_5037_50371701_36_dialog_content = "そうね。じゃあ、これからも頑張ってね、空の末裔。",
  ui_story_5037_50371701_37_dialog_content = "努力こそが進歩の糧だから。",
  ui_story_5037_50371701_38_dialog_content = "努力こそが進歩の糧か…いい励ましの言葉だね。ありがとう！",
  ui_story_5037_50371701_39_dialog_content = "ううん、今のは励ましじゃないわ。",
  ui_story_5037_50371701_40_dialog_content = "励ましじゃないの…？",
  ui_story_5037_50371701_41_dialog_content = "これは、私自身の学生時代の総括みたいなものよ。",
  ui_story_5037_50371701_42_dialog_content = "「努力」さえすれば、平凡な者も非凡な成績を残すことができる。\nだから、「努力」を大切にするといいわ。",
  ui_story_5037_50371701_43_dialog_content = "そうだったんだ…うん、覚えておくよ！",
  ui_story_5037_50371701_44_dialog_content = "そういえば、フロリナはずっと旧時代の服のまま替えてないんだね。",
  ui_story_5037_50371701_45_dialog_content = "ええ、この服は軽くて動きやすいし、学生時代を思い出せるから。",
  ui_story_5037_50371701_46_dialog_content = "これを着ていると、自分に言い聞かせることができるの――",
  ui_story_5037_50371701_47_dialog_content = "いつ何時も学生だった頃と同じように、謙虚さと誠実さをもって努力を続け、\n大きな責任を担える人になるんだって。",
  ui_story_5037_50371701_48_dialog_content = "PlayerNameも試してみるといいわ。\nいい自己喚起になるわよ。",
  ui_story_5037_50371701_49_dialog_content = "ぼ、僕は遠慮しておくよ…",
  ui_story_5037_50371701_50_dialog_content = "この服が一番楽だからね！",
  ui_story_5037_50371701_51_dialog_content = "そう？それもいいわ、自分なりのやり方でやればいいもの。",
  ui_story_5037_50371701_52_dialog_content = "常に努力を忘れず、気を抜かなければ、\n何事もうまくいくはずよ。",
  ui_story_5037_50371701_53_dialog_content = "フロリナって、自分に厳しいんだね…",
  ui_story_5037_50371701_54_dialog_content = "厳しい？そうは思わないわ。",
  ui_story_5037_50371701_55_dialog_content = "私が目指しているのは、ヘイディ先輩のような、\nすべての人を助けることのできる人よ。",
  ui_story_5037_50371701_56_dialog_content = "先輩のように頼りがいのある人になれるのなら、\nどんなに大変なことでも頑張って挑戦したい。",
  ui_story_5037_50371701_57_dialog_content = "今の私じゃ、まだまだ先輩のような人には程遠いわ。",
  ui_story_5037_50371701_58_dialog_content = "ううん、フロリナはもう十分すごいと思うよ！",
  ui_story_5037_50371701_59_dialog_content = "ずっとあきらめずに頑張り続けること自体が、\nすでにとても立派なことだよ。",
  ui_story_5037_50371701_60_dialog_content = "僕も君みたいになれたらいいのに。",
  ui_story_5037_50371701_61_dialog_content = "じゃあ、一緒に目標目指して頑張りましょ。",
  ui_story_5037_50371701_62_dialog_content = "うん、頑張ろう！",
  ui_story_5037_50371701_63_dialog_content = "そうだ。ゴルディに水分補給をしっかりして、\n健康に気をつけるよう伝えておいてね。",
  ui_story_5037_50371701_64_dialog_content = "歌は長時間のどを使うわ。\n水を飲めば、のどを常に潤った状態で保てるの。",
  ui_story_5037_50371701_65_dialog_content = "ダンスもきつい負荷がかかる運動だから、\nちゃんと忘れずに水分補給をするようにって。",
  ui_story_5037_50371701_66_dialog_content = "分かった、ゴルディに伝えておくね！",
  ui_story_5037_50371701_67_dialog_content = "あと…あなたもよ、空の末裔。",
  ui_story_5037_50371701_68_dialog_content = "どんなに仕事が忙しくても、健康には気をつけるように。",
  ui_story_5037_50371701_69_dialog_content = "う、うん。分かったよ…",
  ui_story_5037_50371701_70_dialog_content = "これからも仕事がうまくいくよう、\n光の神がお守りくださることを祈っているわね。",
  ui_story_5037_50371701_71_dialog_content = "うん、ありがとう！",
  ui_story_5037_50371801_1_dialog_content = "今回はめずらしく自撮りよ～！セロロ、\nあたしとゴルディとPlayerNameのスリーショット、きれいに撮ってね！",
  ui_story_5037_50371801_2_dialog_content = "3、2、1…アクション！",
  ui_story_5037_50371801_3_dialog_content = "みなさーん、こんにちは！名監督リリカよ！",
  ui_story_5037_50371801_4_dialog_content = "今日はあたしが指導者として、人気アイドルのゴルディと\nそのプロデューサーPlayerNameと一緒に――",
  ui_story_5037_50371801_5_dialog_content = "演技の特訓をしようと思いまーす！",
  ui_story_5037_50371801_6_dialog_content = "ゴルディとPlayerNameも、あいさつをお願い！",
  ui_story_5037_50371801_7_dialog_content = "みなさん、こんにちは！",
  ui_story_5037_50371801_8_dialog_content = "こ、こんにちは…",
  ui_story_5037_50371801_9_dialog_content = "（この映像が今後たくさんの人の目に触れるのかと思うと、\nどうしても落ち着かないな…）",
  ui_story_5037_50371801_10_dialog_content = "今日の特訓のために、特別なゲームを用意してきたの！",
  ui_story_5037_50371801_11_dialog_content = "ゲーム？いいわね！私、ゲーム大好きなの！",
  ui_story_5037_50371801_12_dialog_content = "どんなゲームなの？",
  ui_story_5037_50371801_13_dialog_content = "そのゲームの名は、ずばり――「モノマネゲーム」よ！",
  ui_story_5037_50371801_14_dialog_content = "演技っていうのはね、衣装やメイク、セリフ、表情といった要素を\nすべて合わせることでできる最終成果物なの。",
  ui_story_5037_50371801_15_dialog_content = "その中で役者にできるのは、できる限り深く役柄を理解して、\nその役柄の言葉や表情を創り上げることよ。",
  ui_story_5037_50371801_16_dialog_content = "確かにその通りね！",
  ui_story_5037_50371801_17_dialog_content = "PlayerNameのお友だちをよ～く観察して、\nそれぞれの特徴をまとめてセリフを書いてみたの。",
  ui_story_5037_50371801_18_dialog_content = "今からやるゲームでは、まずゴルディに1人選んでもらって、\nその人の言動をマネしてもらいます。",
  ui_story_5037_50371801_19_dialog_content = "それを見て、PlayerNameにゴルディが誰のマネをしているのか、\n当ててもらうっていう流れよ！",
  ui_story_5037_50371801_20_dialog_content = "PlayerNameが見事当てられたら、ゴルディの演技は成功ってことね！",
  ui_story_5037_50371801_21_dialog_content = "へええ、面白そうね！",
  ui_story_5037_50371801_22_dialog_content = "なるほど、そういうゲームなんだね。",
  ui_story_5037_50371801_23_dialog_content = "ゴルディは役者としてはまだ新人だから、\nPlayerNameには選択肢の中から選んでもらおうと思うの。",
  ui_story_5037_50371801_24_dialog_content = "いずれにせよ、そう難しくはないわ。\n気軽にやりましょ！",
  ui_story_5037_50371801_25_dialog_content = "分かった！",
  ui_story_5037_50371801_26_dialog_content = "私の演技、楽しみにしててね！",
  ui_story_5037_50371801_27_dialog_content = "じゃあ、ゴルディ。\n早速このリストから1人選んで演技してみて。",
  ui_story_5037_50371801_28_dialog_content = "う～ん…この人にするわ！",
  ui_story_5037_50371801_29_dialog_content = "それじゃPlayerName、始めるわね。",
  ui_story_5037_50371801_30_dialog_content = "「よう、小僧！」",
  ui_story_5037_50371801_31_dialog_content = "（この感じ…よく知ってる、きっとあの人だ！）",
  ui_story_5037_50371801_32_dialog_content = "「俺と獲物を狙いにいく準備はできたか？」",
  ui_story_5037_50371801_33_dialog_content = "さあ、PlayerName。ゴルディが演じたのは誰でしょう！",
  ui_story_5037_50371801_34_option_content = "バートン？",
  ui_story_5037_50371801_35_dialog_content = "惜しい！不正解よ！",
  ui_story_5037_50371801_36_dialog_content = "正解はサメヤマでした～！",
  ui_story_5037_50371801_37_dialog_content = "うーん…ハズレちゃったか…",
  ui_story_5037_50371801_38_dialog_content = "私の演技がいけなかったのね？よし、次は頑張るわ！",
  ui_story_5037_50371801_39_option_content = "サメヤマ？",
  ui_story_5037_50371801_40_dialog_content = "正解！",
  ui_story_5037_50371801_41_dialog_content = "ゴルディの演技がよかった証拠ね！",
  ui_story_5037_50371801_42_dialog_content = "ゴルディ、いい演技だったよ。\n本当にサメヤマかと思っちゃった！",
  ui_story_5037_50371801_43_dialog_content = "今にも背中から赤いレンチを取り出すんじゃないかと思うくらいだったよ…",
  ui_story_5037_50371801_44_dialog_content = "今のは褒められたって受け取っていいのよね…？",
  ui_story_5037_50371801_45_option_content = "クレーケン？",
  ui_story_5037_50371801_46_dialog_content = "大ハズレ～！",
  ui_story_5037_50371801_47_dialog_content = "正解はサメヤマでした～！",
  ui_story_5037_50371801_48_dialog_content = "PlayerName、ゴルディの演技をちゃんと見なきゃ！",
  ui_story_5037_50371801_49_dialog_content = "ご、ごめん…",
  ui_story_5037_50371801_50_dialog_content = "気にしないで、私も頑張るわ！",
  ui_story_5037_50371801_51_dialog_content = "次のお題は難易度が上がるわよー！",
  ui_story_5037_50371801_52_dialog_content = "ゴルディ、この人を演じてみて！",
  ui_story_5037_50371801_53_dialog_content = "え？私とはかなり違うタイプね…でも、頑張るわ！",
  ui_story_5037_50371801_54_dialog_content = "「ボーヤ、何してるの？」",
  ui_story_5037_50371801_55_dialog_content = "（今度は誰だろう…？）",
  ui_story_5037_50371801_56_dialog_content = "「ねえ、ヒマでしょ？アフターヌーンティーを部屋までもってきてちょうだい。\n取りに行くの、めんどくさいわ」",
  ui_story_5037_50371801_57_dialog_content = "PlayerName、さあ、当ててみて！",
  ui_story_5037_50371801_58_option_content = "ミジャード？",
  ui_story_5037_50371801_59_dialog_content = "正解！",
  ui_story_5037_50371801_60_dialog_content = "本当に難しくなってるね…",
  ui_story_5037_50371801_61_dialog_content = "演技のほうも難しかったわ。ミジャードの表情や雰囲気って\nほかの人とは違うから、表現するのが大変なのよね…",
  ui_story_5037_50371801_62_dialog_content = "でも、当たったよ。\nつまり、君の演技がよかったってことだよ！",
  ui_story_5037_50371801_63_option_content = "ソルラドさん？",
  ui_story_5037_50371801_64_dialog_content = "確かに、あなたをボーヤって呼んでもいい歳だけど…",
  ui_story_5037_50371801_65_dialog_content = "でも残念！正解はミジャードでした～！",
  ui_story_5037_50371801_66_dialog_content = "う～ん…私の演技力、まだまだみたいね…",
  ui_story_5037_50371801_67_dialog_content = "いや、僕がちゃんと観察しきれてなかったせいだよ…",
  ui_story_5037_50371801_68_option_content = "タタ？",
  ui_story_5037_50371801_69_dialog_content = "ブッブー！タタはまだ子どもじゃない。\n「ボーヤ」なんて呼ぶわけないでしょー？",
  ui_story_5037_50371801_70_dialog_content = "ということで、正解はミジャードでした～！",
  ui_story_5037_50371801_71_dialog_content = "ほら、ミジャードってきれいな人なのに、\nオジサンみたいなこと言うでしょ…",
  ui_story_5037_50371801_72_dialog_content = "た、確かに…",
  ui_story_5037_50371801_73_dialog_content = "ミジャードに会うといつも、\nじっと見られてるような気がするんだよね…",
  ui_story_5037_50371801_74_dialog_content = "PlayerName、次の問題こそ一緒に頑張りましょ！",
  ui_story_5037_50371801_75_dialog_content = "さ～て、次は最後の問題よ！",
  ui_story_5037_50371801_76_dialog_content = "ゴルディ、この人を演じてみて！",
  ui_story_5037_50371801_77_dialog_content = "え！？だ、大丈夫かしら？",
  ui_story_5037_50371801_78_dialog_content = "大丈夫よ、思いきって演じてみて！",
  ui_story_5037_50371801_79_dialog_content = "じゃ、じゃあ…始めるわ！",
  ui_story_5037_50371801_80_dialog_content = "「PlayerName…」",
  ui_story_5037_50371801_81_dialog_content = "（え、もう始まってるの！？）",
  ui_story_5037_50371801_82_dialog_content = "「今日も一緒に頑張りましょ！」",
  ui_story_5037_50371801_83_dialog_content = "さあ、PlayerName、回答をどうぞ！",
  ui_story_5037_50371801_84_option_content = "リリカ？",
  ui_story_5037_50371801_85_dialog_content = "確かに似てるかも！でも、違うわ…",
  ui_story_5037_50371801_86_dialog_content = "え？そっか、違うんだ…",
  ui_story_5037_50371801_87_dialog_content = "PlayerName、正解は目の前よ！",
  ui_story_5037_50371801_88_dialog_content = "まさか…今のって、ゴルディ本人！？",
  ui_story_5037_50371801_89_dialog_content = "正解！",
  ui_story_5037_50371801_90_option_content = "ゴルディ？",
  ui_story_5037_50371801_91_dialog_content = "正解～！",
  ui_story_5037_50371801_92_dialog_content = "まさかPlayerNameが本当に当てるとは思わなかったわ！",
  ui_story_5037_50371801_93_dialog_content = "だってゴルディは、いつもさっきの演技みたいに元気いっぱいでしょ。",
  ui_story_5037_50371801_94_dialog_content = "ただ、分からないこととして…どうしてこの問題を出したの？",
  ui_story_5037_50371801_95_dialog_content = "プロデューサーの演技に対する感性ってね、\n担当するアイドルの演技の練習にも影響するの。",
  ui_story_5037_50371801_96_dialog_content = "優秀なプロデューサーには、アイドルが演じる役柄を理解すること以外にも\n重要なスキルが必要よ。それは――",
  ui_story_5037_50371801_97_dialog_content = "自分の担当するアイドル自身の特徴と実力を知ること！",
  ui_story_5037_50371801_98_dialog_content = "そうしてはじめて、\nそのアイドルにふさわしい練習メニューを組み立てられるのよ。",
  ui_story_5037_50371801_99_dialog_content = "つまり、最後のこの問題は――PlayerName、\nあなたに対する試験だったの！",
  ui_story_5037_50371801_100_dialog_content = "そういうことだったんだね、やっと分かったよ！",
  ui_story_5037_50371801_101_dialog_content = "ええ、私もいろんな収穫があったわ！",
  ui_story_5037_50371801_102_dialog_content = "演じる役によって、こんなにも違いがあるのね。\nやっぱり私、もっと頑張らなくちゃ！",
  ui_story_5037_50371801_103_dialog_content = "それじゃ、今日の練習はここまで。\n2人とも頑張ってね！",
  ui_story_5037_50371801_104_dialog_content = "ぜひ今日学んだことを実践してちょうだい！",
  ui_story_5037_50371801_105_dialog_content = "ええ！",
  ui_story_5037_50371801_106_dialog_content = "ありがとう、リリカ監督！",
  ui_story_5037_50371901_1_dialog_content = "雲島の巫女様かぁ…どんな人なのかしら？",
  ui_story_5037_50371901_2_dialog_content = "巫女様は歌と踊りに長けていて、優雅で神秘的で、\nさらには強大な光力術の使い手だって聞いたことがあるわ。",
  ui_story_5037_50371901_3_dialog_content = "うーん、想像がふくらんじゃうわね。",
  ui_story_5037_50371901_4_dialog_content = "あはは、すぐに会えるよ。",
  ui_story_5037_50371901_5_dialog_content = "だって今日は、巫女様に会うために頑張って時間を作って巨像まで来たのよ！",
  ui_story_5037_50371901_6_dialog_content = "本物の巫女様に踊りを教えてもらえるなんて、\n興奮で今にも心臓が飛び出しそうよ！",
  ui_story_5037_50371901_7_dialog_content = "<color=#828282>チリン――</color>",
  ui_story_5037_50371901_8_dialog_content = "お待たせして申し訳ございません。",
  ui_story_5037_50371901_9_dialog_content = "そんな、全然気にしないで！雲島から踊りを教えるために\nわざわざ来てくれたのだもの、むしろ感謝しかないわ！",
  ui_story_5037_50371901_10_dialog_content = "あなたがゴルディ様、でいらっしゃいますね？",
  ui_story_5037_50371901_11_dialog_content = "はい！初めまして、リンネさん。\n私はゴルディ、アイドル歌手をやっているわ。",
  ui_story_5037_50371901_12_dialog_content = "こんにちは。わたくしはリンネと申します。\n雲島の巫女をつとめております。",
  ui_story_5037_50371901_13_dialog_content = "今おっしゃった「あいどる歌手」…というのは、\n歌い手のことでしょうか？",
  ui_story_5037_50371901_14_dialog_content = "それとも少し違うかな…アイドルは歌以外にも、\nダンスやお芝居も学ぶのよ。",
  ui_story_5037_50371901_15_dialog_content = "そうでしたか。それで神楽を学ばれたい、ということでしたのですね。",
  ui_story_5037_50371901_16_dialog_content = "そうなの！リンネさん、ぜひ教えてもらってもいいかな？",
  ui_story_5037_50371901_17_dialog_content = "もちろんでございます。それではまず、\nわたくしが舞いを披露してご覧にいれましょう。",
  ui_story_5037_50371901_18_dialog_content = "ホントですか？この目で巫女様の神楽を見られるなんて、\nすっごくラッキーだわ！",
  ui_story_5037_50371901_19_dialog_content = "ふふ…",
  ui_story_5037_50371901_20_dialog_content = "<color=#828282>チリン――</color>",
  ui_story_5037_50371901_21_dialog_content = "<color=#828282>チリリン――</color>",
  ui_story_5037_50371901_22_dialog_content = "キレイ…",
  ui_story_5037_50371901_23_dialog_content = "鈴の音を聞きながらリンネさんの舞いを見ているだけで、\n心が洗われる気がするわ…",
  ui_story_5037_50371901_24_dialog_content = "今のは神楽の最も基本的な動きでございます。\nゴルディさんもどうぞ試してみてください。",
  ui_story_5037_50371901_25_dialog_content = "うん、早速やってみるわね！",
  ui_story_5037_50371901_26_dialog_content = "ええと…こんな感じかしら？",
  ui_story_5037_50371901_27_dialog_content = "ええ、大変お上手です。\n動きの基本がきちんとできていらっしゃいますね。",
  ui_story_5037_50371901_28_dialog_content = "えへへ、動きをマネすることにかけては自信があるの！",
  ui_story_5037_50371901_29_dialog_content = "ただ、私の踊る神楽には、何かが足りないような気がするのよね…",
  ui_story_5037_50371901_30_dialog_content = "確かにそうだね。リンネが踊っているときに感じる、\n心が洗われるような感覚が足りないのかな…？",
  ui_story_5037_50371901_31_dialog_content = "リンネさんは踊る時、\n何か特別な光力術でも使っていたりするの？",
  ui_story_5037_50371901_32_dialog_content = "いいえ、光力術は一切使っておりません。\nただ舞を舞っただけでございます。",
  ui_story_5037_50371901_33_dialog_content = "だったら、どこがいけなかったのかしら…？",
  ui_story_5037_50371901_34_dialog_content = "ゴルディ様、ぶしつけかとは存じますが…先程舞を舞ってらっしゃる間、\n何を考えていらしたのか教えていただいても？",
  ui_story_5037_50371901_35_dialog_content = "私が、考えていたこと…？",
  ui_story_5037_50371901_36_dialog_content = "そうね…いろんなことを考えてたわ。この動きで合ってるのかなとか、\n次の動きはなんだったかな、とか…",
  ui_story_5037_50371901_37_dialog_content = "神楽を踊るのは初めてだったから、\nつい間違っていないか心配になっちゃって。",
  ui_story_5037_50371901_38_dialog_content = "さようでございましたか。問題は、そこにあったのかもしれませんね。",
  ui_story_5037_50371901_39_dialog_content = "神楽は神に捧げる舞です。\nですから、舞っている間は全身全霊で、神を思っていなければなりません。",
  ui_story_5037_50371901_40_dialog_content = "そうして初めて、\n心に思っていることが舞として表れてくるのです。",
  ui_story_5037_50371901_41_dialog_content = "なるほど…あ！分かったわ！",
  ui_story_5037_50371901_42_dialog_content = "飲み込みが早いね！？",
  ui_story_5037_50371901_43_dialog_content = "つまり、私がいつもやってるコンサートと\n同じってことね！",
  ui_story_5037_50371901_44_dialog_content = "歌っている時や踊っている時、私もいつもファンのみんなを思ってる。\nみんなに喜びを届けたいって願いながら、ステージに立っているの。",
  ui_story_5037_50371901_45_dialog_content = "そうするとね、歌もダンスもうんとスムーズかつ自然になるのよ！",
  ui_story_5037_50371901_46_dialog_content = "形式や種類こそ違えども、\n同じ「舞」である限り共通点があるもの…",
  ui_story_5037_50371901_47_dialog_content = "よろしければ、今おっしゃっていた気持ちを踏まえて\nもう一度舞っていただけますか？",
  ui_story_5037_50371901_48_dialog_content = "はい！",
  ui_story_5037_50371901_49_dialog_content = "全身全霊で、ファンのことを思って…",
  ui_story_5037_50371901_50_dialog_content = "（すごい！さっきと全然違う！）",
  ui_story_5037_50371901_51_dialog_content = "（ただ、やっぱりリンネの舞いとは何かが違う気がするな…）",
  ui_story_5037_50371901_52_dialog_content = "リンネさん、PlayerName、どうだった？",
  ui_story_5037_50371901_53_option_content = "リンネの舞いに近づいた気がするよ！",
  ui_story_5037_50371901_54_dialog_content = "そう？ならよかった！",
  ui_story_5037_50371901_55_dialog_content = "いいえ、やはり違いがございました。",
  ui_story_5037_50371901_56_dialog_content = "えっ？",
  ui_story_5037_50371901_57_option_content = "ゴルディらしさのある舞いだったよ！",
  ui_story_5037_50371901_58_dialog_content = "えっ？",
  ui_story_5037_50371901_59_dialog_content = "ゴルディのほうが、はつらつとして軽快だった気がする。",
  ui_story_5037_50371901_60_dialog_content = "ゴルディ様とわたくしの舞いは、\nそれぞれ捧げる対象が異なるもの。",
  ui_story_5037_50371901_61_dialog_content = "ゴルディ様は人々に舞いを捧げていらっしゃる…\nつまり、彼らから寄せられた情熱への返礼として、舞われているのです。",
  ui_story_5037_50371901_62_dialog_content = "ですから、いかに同じ動きをしていても、それが伝える情感は\n舞手によって千差万別なのでございます。",
  ui_story_5037_50371901_63_dialog_content = "これは決して悪いことではなく、当然のこと。\nですから、心配には及びません。",
  ui_story_5037_50371901_64_dialog_content = "あなたの舞いとそこに込められた思いは、\nそもそも唯一無二のものなのですから。",
  ui_story_5037_50371901_65_dialog_content = "ええ！",
  ui_story_5037_50371901_66_dialog_content = "いろいろ教えてくれてありがとう、リンネさん！",
  ui_story_5037_50372001_1_dialog_content = "今日はいつもとは違う場所で練習よ。それじゃ、撮影を始めるわね！\nみんな、頑張ってね～！",
  ui_story_5037_50372001_2_dialog_content = "3、2、1…アクション！",
  ui_story_5037_50372001_3_dialog_content = "もう始まってますこと？コホン…",
  ui_story_5037_50372001_4_dialog_content = "それでは今から、ボーカル講座を始めさせていただくわ。",
  ui_story_5037_50372001_5_dialog_content = "ニナ先生、よろしくお願いします！",
  ui_story_5037_50372001_6_dialog_content = "やっぱり、よく分からない…",
  ui_story_5037_50372001_7_dialog_content = "今からするのってボイストレーニングだよね？\nどうしてレッスン室じゃなく、劇場でやるの？",
  ui_story_5037_50372001_8_dialog_content = "あら、PlayerName、いい質問ね。",
  ui_story_5037_50372001_9_dialog_content = "今回は練習ではなく、聴くことを主軸においていますの。",
  ui_story_5037_50372001_10_dialog_content = "聴くこと…？",
  ui_story_5037_50372001_11_dialog_content = "確かに、他の人の歌を聴くことも大切な練習の一環ね！",
  ui_story_5037_50372001_12_dialog_content = "ファンのみんなの好みを知ってこそ、\n多くの人に喜んでもらえる曲が作れるのよ！",
  ui_story_5037_50372001_13_dialog_content = "その通りでしてよ！流行の傾向を正確につかむこと、流行についていくこと、\nそして流行をリードすること…それこそがビジネスにおける要！",
  ui_story_5037_50372001_14_dialog_content = "例えば、本日観賞する『舞台の怪人』という劇は――",
  ui_story_5037_50372001_15_dialog_content = "永遠の命をもつ、ある舞台俳優の物語で…",
  ui_story_5037_50372001_16_dialog_content = "劇中に出てくる演目がそれぞれ影ノ街の各時代を表していて、\n演目の変化によって、影ノ街の歴史をつづっているの。",
  ui_story_5037_50372001_17_dialog_content = "へえ、すごく面白そうだね！",
  ui_story_5037_50372001_18_dialog_content = "つまり、それぞれの時代の流行文化も反映されているってことね！",
  ui_story_5037_50372001_19_dialog_content = "その通りよ。ゴルディに10点ね。",
  ui_story_5037_50372001_20_dialog_content = "ミノス、教材をお渡しして。",
  ui_story_5037_50372001_21_dialog_content = "かしこまりました、お嬢様。",
  ui_story_5037_50372001_22_dialog_content = "これは…？",
  ui_story_5037_50372001_23_dialog_content = "そちらはお嬢様が丹精を込めて用意された教材です。\nここ10数年に影ノ街で流行った曲目とオペラの台本をすべてそろえております。",
  ui_story_5037_50372001_24_dialog_content = "どうぞ、大切にしてくださいませ。",
  ui_story_5037_50372001_25_dialog_content = "う、うん…",
  ui_story_5037_50372001_26_dialog_content = "この授業では、その教材にあるすべての曲についてだけではなく、\nここ10数年の影ノ街の流行について知ることができてよ。",
  ui_story_5037_50372001_27_dialog_content = "それらを知ることでセンスはよりいっそう磨かれ、\nより流行に沿った曲が書けるようになりましてよ。",
  ui_story_5037_50372001_28_dialog_content = "ええと、ニナ、君の努力には感謝するけど…",
  ui_story_5037_50372001_29_dialog_content = "それにしたって、多すぎるでしょ！？",
  ui_story_5037_50372001_30_dialog_content = "まさか、今日1日で読めとか言い出さないよね…？",
  ui_story_5037_50372001_31_dialog_content = "全部読めですって？そんな必要はなくってよ。\nそれはあまりにも酷だもの。",
  ui_story_5037_50372001_32_dialog_content = "資料にある歌は、今日のお芝居の中で出てくるものばかりよ。",
  ui_story_5037_50372001_33_dialog_content = "私が整理した資料を参考に、\n各時代の流行文化の違いを理解してちょうだい。",
  ui_story_5037_50372001_34_dialog_content = "分かったわ、ありがとう！",
  ui_story_5037_50372001_35_dialog_content = "うん、一生懸命勉強するよ！",
  ui_story_5037_50372001_36_dialog_content = "さあ、お芝居が始まるわ。急いで席に着きましょ。",
  ui_story_5037_50372001_37_dialog_content = "皆様、こちらへどうぞ。",
  ui_story_5037_50372001_38_dialog_content = "お嬢様がお2人に貴賓席をご用意されております。",
  ui_story_5037_50372001_39_dialog_content = "舞台からこんなに近いなんて…\nここならきっと、舞台上の空気を間近に感じられるわ！",
  ui_story_5037_50372001_40_dialog_content = "<color=#828282>…</color>",
  ui_story_5037_50372001_41_dialog_content = "「朝の美しき景色の中、音楽が響き、時はいつの間にか過ぎていく」",
  ui_story_5037_50372001_42_dialog_content = "「美しいお嬢さん、私と踊ってくださいませんか？」",
  ui_story_5037_50372001_43_dialog_content = "この場面は影ノ街で最も古いお芝居の一幕を演じているの。\n『クリオとジェシカ』というお芝居でしてよ。",
  ui_story_5037_50372001_44_dialog_content = "これ、私も知ってるわ。\n小さい頃、リメイク版のお話を聞いたことがあるの！",
  ui_story_5037_50372001_45_dialog_content = "敵対する2つの家に生まれた男女が恋に落ちるという、\n悲しい恋の物語よね。",
  ui_story_5037_50372001_46_dialog_content = "その通りでしてよ。ご覧のように、\nこの時代の影ノ街の文化は白夜城の影響を強く受けていましたの。",
  ui_story_5037_50372001_47_dialog_content = "劇中には、白夜城貴族の生活習慣が\n数多く描かれていますのよ。そうね、例えば…",
  ui_story_5037_50372001_48_dialog_content = "（ニナとゴルディ、楽しそうに話してるなぁ…）",
  ui_story_5037_50372001_49_dialog_content = "（お芝居は面白いけど、白夜城や影ノ街の歴史には詳しくないし…）",
  ui_story_5037_50372001_50_dialog_content = "（んん、眠くなってきちゃったな…あまりよく分からないお芝居を見ると、\nどうしても眠気が…）",
  ui_story_5037_50372001_51_dialog_content = "（でも、ニナが一生懸命準備してくれたんだ…）",
  ui_story_5037_50372001_52_option_content = "頑張って眠気に勝つ",
  ui_story_5037_50372001_53_dialog_content = "（ダメだ、寝ちゃダメだ！\n最初から最後までちゃんと観なくちゃ！）",
  ui_story_5037_50372001_54_dialog_content = "（貴重な参考資料なんだから！）",
  ui_story_5037_50372001_55_dialog_content = "<color=#828282>何とか眠気を我慢し、芝居の鑑賞が終わった</color>",
  ui_story_5037_50372001_56_dialog_content = "影ノ街の文化って、こんなにも複雑な過程を経て今に至ってたのね。\n今日初めて知ったわ！",
  ui_story_5037_50372001_57_dialog_content = "僕も色々な知識を学べたよ！",
  ui_story_5037_50372001_58_dialog_content = "と言っても、ほとんどの内容は聞いていてよく分からなかったけど…",
  ui_story_5037_50372001_59_dialog_content = "心配する必要はなくってよ。\n教材には、重点となる箇所にマークがついているわ。",
  ui_story_5037_50372001_60_dialog_content = "あとは好きな時に開いて、復習すればいいわ。",
  ui_story_5037_50372001_61_dialog_content = "ニナさん、本当にいろいろありがとう！",
  ui_story_5037_50372001_62_option_content = "あきらめて寝る",
  ui_story_5037_50372001_63_dialog_content = "（がまんだ、がまん…すぅ…）",
  ui_story_5037_50372001_64_dialog_content = "<color=#828282>そして時はだいぶ過ぎ…</color>",
  ui_story_5037_50372001_65_dialog_content = "PlayerName？PlayerName！",
  ui_story_5037_50372001_66_dialog_content = "ゴルディ様、ここは私が。",
  ui_story_5037_50372001_67_dialog_content = "PlayerName様、起きてください！",
  ui_story_5037_50372001_68_dialog_content = "えっ！？",
  ui_story_5037_50372001_69_dialog_content = "PlayerName、寝ちゃったの？もうお芝居は終わったわよ。",
  ui_story_5037_50372001_70_dialog_content = "え！？終わったの！？",
  ui_story_5037_50372001_71_dialog_content = "ゴルディに説明することばかりに気をとられて、\nあなたの居眠りに気づかなかったわ…",
  ui_story_5037_50372001_72_dialog_content = "お嬢様のご好意を無駄になさるとは、\nなんと罪深いことを…",
  ui_story_5037_50372001_73_dialog_content = "ご、ごめん！",
  ui_story_5037_50372001_74_dialog_content = "僕がいけないんだ…",
  ui_story_5037_50372001_75_dialog_content = "よくってよ。",
  ui_story_5037_50372001_76_dialog_content = "お芝居を観ながら学ぶことができなかったのは、\n残念だったけれど…",
  ui_story_5037_50372001_77_dialog_content = "教材には、重点となる箇所にマークがついているわ。",
  ui_story_5037_50372001_78_dialog_content = "帰ってからじっくり教材を読めば、\n多少なりとも知識を学べましてよ。",
  ui_story_5037_50372001_79_dialog_content = "うん、きちんと真面目に読むよ。\n今度こそ居眠りしない！",
  ui_story_5037_50372001_80_dialog_content = "お芝居から何か学んでいただけたのなら、\n私も手伝った甲斐があるというものよ。",
  ui_story_5037_50372001_81_dialog_content = "流行文化の要は大衆の好みをつかめるかにかかっていましてよ。\nだから、外の世界に触れることがとても大切なの。",
  ui_story_5037_50372001_82_dialog_content = "私が教えて差し上げられるのはここまで。\nこの後は、2人の頑張り次第というところかしら。",
  ui_story_5037_50372001_83_dialog_content = "ありがとうニナさん、ミノスさん！",
  ui_story_5037_50372001_84_dialog_content = "2人とも、いろいろとありがとう！",
  ui_story_5037_50372101_1_dialog_content = "フェラール、僕とゴルディを指導するために\nわざわざ来てくれてありが――",
  ui_story_5037_50372101_2_dialog_content = "シーッ！",
  ui_story_5037_50372101_3_dialog_content = "あら？フェラールさん、ドアにへばりついて何してるの？",
  ui_story_5037_50372101_4_dialog_content = "PlayerName、ゴルディさん、\nちょっとの間だけ静かにしててくれないか…",
  ui_story_5037_50372101_5_dialog_content = "…",
  ui_story_5037_50372101_6_dialog_content = "…",
  ui_story_5037_50372101_7_dialog_content = "ふぅ…どうやら行ったみたいだな。",
  ui_story_5037_50372101_8_dialog_content = "またしつこく追いかけられてるの？",
  ui_story_5037_50372101_9_dialog_content = "そうさ…",
  ui_story_5037_50372101_10_dialog_content = "ここへ来る途中、前に助けたことのある人に\nちょっと挨拶しただけなんだが…",
  ui_story_5037_50372101_11_dialog_content = "こんにちは。",
  ui_story_5037_50372101_12_dialog_content = "あれ？フェラールじゃないか、この間はありがとう！\nほんとに助かったよ！",
  ui_story_5037_50372101_13_dialog_content = "その人が俺の名前を口にしたとたん、\nどんどん人が集まってきて…",
  ui_story_5037_50372101_14_dialog_content = "え、フェラールお兄ちゃん？\nこの間はありがとう！",
  ui_story_5037_50372101_15_dialog_content = "フェラールさん！！私、ファンなんです！！",
  ui_story_5037_50372101_16_dialog_content = "なんとか集まってきた人たちの輪から抜け出して、ぐるっと遠回りして\n誰もついてきてないのを確かめてから、ここに来たっていうわけなんだ…",
  ui_story_5037_50372101_17_dialog_content = "人気がありすぎるのも、考えものだね…",
  ui_story_5037_50372101_18_dialog_content = "うらやましいわ、\n私もフェラールさんみたいに人気者になりたい！",
  ui_story_5037_50372101_19_dialog_content = "いや…人気者ってのも苦労するぜ。",
  ui_story_5037_50372101_20_dialog_content = "苦労だなんて思わないわ！",
  ui_story_5037_50372101_21_dialog_content = "だって、もっとたくさんの人に\n私のダンスや歌を楽しんでもらいたいもの！",
  ui_story_5037_50372101_22_dialog_content = "キミがそう思うんなら、俺もどうこう言う気はないが…",
  ui_story_5037_50372101_23_dialog_content = "ただ、俺が他人から好かれるのは、\n特殊な体質のせいなんだ。",
  ui_story_5037_50372101_24_dialog_content = "だから、教えようにも教えられないのさ…",
  ui_story_5037_50372101_25_dialog_content = "えっ？",
  ui_story_5037_50372101_26_dialog_content = "それに俺自身、どうしてこんなに好かれるのか\n分かっちゃいないんだ。",
  ui_story_5037_50372101_27_dialog_content = "それに俺は、時間の大半をどうしたら他人の目を引かずに済むのか、\nさらにはどうしたら嫌われるのかってことの研究に費やしてきたからな。",
  ui_story_5037_50372101_28_dialog_content = "そうなの…",
  ui_story_5037_50372101_29_dialog_content = "そっか…じゃあ、どうしよう…",
  ui_story_5037_50372101_30_dialog_content = "…そうだわ！",
  ui_story_5037_50372101_31_dialog_content = "何か思いついたの？",
  ui_story_5037_50372101_32_dialog_content = "フェラールさんが他人から好かれない方法をずっと研究してきたのなら、\n私たちはその逆のことをやればいいのよ！",
  ui_story_5037_50372101_33_dialog_content = "つまり、フェラールに教えてもらったことの逆をやるの？",
  ui_story_5037_50372101_34_dialog_content = "そうすれば、他人に好かれない方法を\n他人に好かれる方法に変えられる…ってこと？",
  ui_story_5037_50372101_35_dialog_content = "その通りよ！さすが私のプロデューサー、理解が早いわね！",
  ui_story_5037_50372101_36_dialog_content = "本当にそれで大丈夫かな…？",
  ui_story_5037_50372101_37_dialog_content = "やってみなきゃ分からないでしょ？\nフェラールさん、よかったらその方法、私に教えて！",
  ui_story_5037_50372101_38_dialog_content = "分かった、キミがそう言うんなら…じゃあ、人目を引かないようにする方法と\n他人から嫌われる方法、どっちがいい？",
  ui_story_5037_50372101_39_dialog_content = "PlayerName、どっちがいいかしら？",
  ui_story_5037_50372101_40_dialog_content = "（逆のことをするわけだから、\n嫌われる方法のほうが効果が高いってことになるよね？）",
  ui_story_5037_50372101_41_option_content = "人目を引かないようにする方法",
  ui_story_5037_50372101_42_dialog_content = "人目を引かないようにするのは、ごく簡単なことさ。\n他のやつらと同じになればいいんだ。",
  ui_story_5037_50372101_43_dialog_content = "他の人と同じことをして、自分の特徴を隠せば、\n人の目を引かずに済むだろ。",
  ui_story_5037_50372101_44_dialog_content = "なんだか簡単そうね！",
  ui_story_5037_50372101_45_dialog_content = "普通、人の目を引かないようにする時って、\nどこにでもありそうな服を着て下を向いて歩くよね。",
  ui_story_5037_50372101_46_dialog_content = "あと、帽子で顔を隠したりとか！",
  ui_story_5037_50372101_47_dialog_content = "で、私はその逆をすればいいわけだから…顔を上げて堂々と歩きながら、\nダンスと歌を披露すればいいってことかしら？",
  ui_story_5037_50372101_48_dialog_content = "何だかおかしな感じもするけど、\nとはいえ君のダンスも歌もとても人目を惹くものだからね…",
  ui_story_5037_50372101_49_dialog_content = "たぶん、それでいいんじゃないかな！",
  ui_story_5037_50372101_50_option_content = "嫌われる方法",
  ui_story_5037_50372101_51_dialog_content = "と言っても、人に嫌われるってのは実はなかなか難しいんだ。",
  ui_story_5037_50372101_52_dialog_content = "俺もいろんな方法を試してみたんだ。コソコソと歩いてみたり、\nボロボロの服を着たり、顔を汚れたまんまにしてみたり…",
  ui_story_5037_50372101_53_dialog_content = "効果はなかなかだった。\n何度もコソ泥あつかいされはしたがな…",
  ui_story_5037_50372101_54_dialog_content = "けどこの体質のせいで、俺がフェラールだと分かった途端に\n全部用をなさなくなっちまったんだ。",
  ui_story_5037_50372101_55_dialog_content = "だいたい分かったわ。",
  ui_story_5037_50372101_56_dialog_content = "逆のことをすればいいわけだから、ぴんと背筋を伸ばして、\n服装もきちんとして、堂々としていればいいのね？",
  ui_story_5037_50372101_57_dialog_content = "それから、いつでも前向きな態度で、\nアイドル歌手らしいスマイルを絶やさずにいればいいのよね！",
  ui_story_5037_50372101_58_dialog_content = "そうだね！",
  ui_story_5037_50372101_59_dialog_content = "まあ結局のところ、どの方法をとるにしても\n「姿かたち」ってのは重要な要素だ。",
  ui_story_5037_50372101_60_dialog_content = "ゴルディさんはダンスが得意なんだろ？\nだったらどうすりゃいいのか、よく分かってるんじゃないか？",
  ui_story_5037_50372101_61_dialog_content = "確かにそうね！ダンスは「姿かたち」がとても重要なの。\n背筋が伸びているのと、背中を丸めて踊るのとではまったく違うわ！",
  ui_story_5037_50372101_62_dialog_content = "よしっ…フェラールさん、今日はありがとう！",
  ui_story_5037_50372101_63_dialog_content = "礼なんかいらないさ。俺に手伝えることがあれば、\n何でも言ってくれ。",
  ui_story_5037_50372101_64_dialog_content = "喜んで人助けするところも、\nフェラールが皆から好かれる大きな理由の一つだよね。",
  ui_story_5037_50372101_65_dialog_content = "そ、そうなのか…？",
  ui_story_5037_50372101_66_dialog_content = "だが、助けを必要としている人を放っておくなんて、\n俺にはできない…",
  ui_story_5037_50372101_67_dialog_content = "フェラールは今のままでいいんだよ。\n変わる必要なんてないよ！",
  ui_story_5037_50372101_68_dialog_content = "そうか、分かった。",
  ui_story_5037_50372101_69_dialog_content = "ありがとう、PlayerName。",
  ui_story_5037_50372101_70_dialog_content = "人を助けて、正義を貫く…\nうんうん、みんなから好かれて当然よね！",
  ui_story_5037_50372101_71_dialog_content = "PlayerName、私たちも急いで習ったことを実践しに行かなきゃ！",
  ui_story_5037_50372101_72_dialog_content = "今から！？",
  ui_story_5037_50372101_73_dialog_content = "鉄は熱いうちに打てっていうでしょ。\n今から街に出て――",
  ui_story_5037_50372101_74_dialog_content = "ゴルディさん、ちょっと待ってくれ！\nまだドアを開けないでくれ！",
  ui_story_5037_50372101_75_dialog_content = "えっ？",
  ui_story_5037_50372101_76_dialog_content = "<color=#828282>ギイ――</color>",
  ui_story_5037_50372101_77_dialog_content = "（外にこんなに人が！？）",
  ui_story_5037_50372101_78_dialog_content = "フェラールさんはこちらですか？",
  ui_story_5037_50372101_79_dialog_content = "さっき、誰かがフェラールお兄ちゃんのことを呼んでたのが聞こえたよ！",
  ui_story_5037_50372101_80_dialog_content = "ラルラル～！どうして逃げるんですか～！？",
  ui_story_5037_50372101_81_dialog_content = "み、みんな、落ち着いてくれ…",
  ui_story_5037_50372101_82_dialog_content = "会いたかった～！！！",
  ui_story_5037_50372101_83_dialog_content = "す、すばらしい魅力だわ！",
  ui_story_5037_50372101_84_dialog_content = "でも、人気がありすぎるのも確かに考えものね…",
  ui_story_5037_50372201_1_dialog_content = "「天才は、いつの日も孤独である。」",
  ui_story_5037_50372201_2_dialog_content = "「天才とは、孤独を糧とし、孤独の中で理想を追い求め、\n孤独を土壌として芸術の花を咲かせる。」",
  ui_story_5037_50372201_3_dialog_content = "「孤独は、彼らの敵ではない。仲間であり、友なのだ！」",
  ui_story_5037_50372201_4_dialog_content = "すばらしいわ！",
  ui_story_5037_50372201_5_dialog_content = "今のセリフは、『インタビュー・ウィズ・ムービーエンペラー』のよね？",
  ui_story_5037_50372201_6_dialog_content = "ありがとう、美しいお嬢さん。私の芝居のすばらしさが分かるということは、\n君もまたすばらしい芸術的感性の持ち主なのであろう！",
  ui_story_5037_50372201_7_dialog_content = "…カロン、ちょっと待って。\n先に説明してくれるかな――",
  ui_story_5037_50372201_8_dialog_content = "僕たちが席を外してたのはたったの10分だよ！？\nどうやってレッスン室に天空ノ谷のセットを造ったの！？",
  ui_story_5037_50372201_9_dialog_content = "我が友よ、そう驚くことはない。\n啓光の工兵はアストラ大陸で最も優秀なのだからな！",
  ui_story_5037_50372201_10_dialog_content = "工兵の使い方、間違ってないかな…",
  ui_story_5037_50372201_11_dialog_content = "このセット、ホントにすばらしいわ！\nレッスン室に入った瞬間、本物の天空ノ谷に来たのかと思わず錯覚したほどよ！",
  ui_story_5037_50372201_12_dialog_content = "我が友よ、どうか信じてくれたまえ。私のなすことはすべて、\nこちらのお嬢さんに芝居の極意をより効果的に伝えるべくしていることだ。",
  ui_story_5037_50372201_13_dialog_content = "本当に…？",
  ui_story_5037_50372201_14_dialog_content = "実践こそ真の知識というであろう。\n自ら芝居をしてこそ、芝居の何たるかを深く知ることができるのだ。",
  ui_story_5037_50372201_15_dialog_content = "セットだけでなく、私自ら脚本も用意したぞ。\nさあ2人とも、存分に芝居を楽しんでくれたまえ。",
  ui_story_5037_50372201_16_dialog_content = "いいの！？アイドルもお芝居の仕事をすることがあるから、助かるわ！",
  ui_story_5037_50372201_17_dialog_content = "プロの俳優さんに指導してもらえるなら、\n私の演技力もきっと大幅に伸びるに違いないわね！",
  ui_story_5037_50372201_18_dialog_content = "では、早速始めるとしようか！",
  ui_story_5037_50372201_19_dialog_content = "さあ、ご覧あれ。これが脚本だ。",
  ui_story_5037_50372201_20_dialog_content = "これは…",
  ui_story_5037_50372201_21_dialog_content = "セリフはちょっと違うけど、\nこれって『エイダと巨像』だよね？",
  ui_story_5037_50372201_22_dialog_content = "その通りだ。今回はあえて童話を題材にした脚本を選んでみたのだよ。",
  ui_story_5037_50372201_23_dialog_content = "童話はストーリーが単純で分かりやすい。\nゆえに、芝居の初心者にはちょうどよいだろうと踏んだのだ。",
  ui_story_5037_50372201_24_dialog_content = "そこまで考えてくれてたんだね！",
  ui_story_5037_50372201_25_dialog_content = "当然ではないか！私とて、右も左も分からぬ新人から\n今日の天才俳優の地位にまで登りつめたのだぞ！",
  ui_story_5037_50372201_26_dialog_content = "じゃあPlayerName、さっそく配役を決めましょ？",
  ui_story_5037_50372201_27_dialog_content = "うん、そうだね。\n僕は巨像に詳しいから、ウィンドウォーカー役をやるよ。",
  ui_story_5037_50372201_28_dialog_content = "じゃあ、私はエイダ役ね！",
  ui_story_5037_50372201_29_dialog_content = "エイダは好奇心が強くて、元気な子なのね。\nとてもかわいらしい役だわ！",
  ui_story_5037_50372201_30_dialog_content = "ナレーションとその他の役は私が演じるとしよう。",
  ui_story_5037_50372201_31_dialog_content = "さて、配役が決まったとあらば、早速始めようではないか！",
  ui_story_5037_50372201_32_dialog_content = "「静かな天空ノ谷に\n「ウィンドウォーカー」という名の巨像が停泊している。」",
  ui_story_5037_50372201_33_dialog_content = "「ウィンドウォーカーは空に強いあこがれを抱いていた。\nしかしナビゲーターがいないために、地上に停泊したままだった」",
  ui_story_5037_50372201_34_dialog_content = "「巨像は空のために生まれた存在だ！」",
  ui_story_5037_50372201_35_dialog_content = "「陸用の巨像もあれば、海にふさわしい巨像もある。\nだけど空こそが、巨像の帰るべき場所なんだ！」",
  ui_story_5037_50372201_36_dialog_content = "「ああ…ナビゲーターがいるって、どんな感じなんだろう…」",
  ui_story_5037_50372201_37_dialog_content = "「ナビゲーターって、きっと友達みたいな存在なんだと思うわ。」",
  ui_story_5037_50372201_38_dialog_content = "「うわぁ！誰！？どうして僕と会話できるんだ…？」",
  ui_story_5037_50372201_39_dialog_content = "「まさか幽霊！？空の末裔がこんな古びた巨像の停泊所に\n来るはずないよね…」",
  ui_story_5037_50372201_40_dialog_content = "「でも今、あなたの目の前にいるのはその空の末裔よ！」",
  ui_story_5037_50372201_41_dialog_content = "「そう言うと、エイダはウィンドウォーカーに近づき、\n花の咲いた彼の頭を眺め、そのまま手を伸ばしてなでたのだった。」",
  ui_story_5037_50372201_42_dialog_content = "（ん？頭をなでる？僕のもってる脚本には、\nそんなこと書いてないけど…）",
  ui_story_5037_50372201_43_dialog_content = "（どうしよう？続けた方がいいのかな？）",
  ui_story_5037_50372201_44_option_content = "続ける",
  ui_story_5037_50372201_45_dialog_content = "「ちょっとだけなでてみよ――」",
  ui_story_5037_50372201_46_dialog_content = "「ちょっと！空の末裔だからって、他人の話を盗み聞きしたり、\n初対面で頭をなでたりしていいわけじゃないからな！」",
  ui_story_5037_50372201_47_dialog_content = "「僕のきれいな頭は誰にも触らせないぞ！」",
  ui_story_5037_50372201_48_dialog_content = "「本当にきれいね。かわいらしいお花まで咲いてる。」",
  ui_story_5037_50372201_48X1_dialog_content = "カット――！",
  ui_story_5037_50372201_49_dialog_content = "見事だったぞ、PlayerName！",
  ui_story_5037_50372201_50_dialog_content = "えっ？",
  ui_story_5037_50372201_51_option_content = "質問する",
  ui_story_5037_50372201_52_dialog_content = "ちょっと待って。脚本にはそんなこと書いてないよ？",
  ui_story_5037_50372201_52X1_dialog_content = "カット――！",
  ui_story_5037_50372201_53_dialog_content = "確かに、脚本に今のセリフはない。",
  ui_story_5037_50372201_54_dialog_content = "私の脚本にもないわ…",
  ui_story_5037_50372201_55_dialog_content = "カロン、どういうこと？",
  ui_story_5037_50372201_56_dialog_content = "芝居には脚本がある。\nしかし、その芝居をするのはいつでも人なのだ。",
  ui_story_5037_50372201_57_dialog_content = "芝居では、予想外のこともいろいろと起こりうる。\nゆえに、終始脚本に沿って演じるわけではないのだ。",
  ui_story_5037_50372201_58_dialog_content = "つまり、優れた役者には臨機応変に対応する能力が必要ということだ！",
  ui_story_5037_50372201_59_dialog_content = "なるほど！",
  ui_story_5037_50372201_60_dialog_content = "確かにそうね！以前観たお芝居でも、\n実際のセリフが脚本と違っていることがあったわ。",
  ui_story_5037_50372201_61_dialog_content = "でも、役者さんたちはみんな自然にふるまっていて、\n観ている人にちっとも違和感を感じさせなかったの！",
  ui_story_5037_50372201_62_dialog_content = "うむ、そうした即興も芝居の一部だと言えよう。",
  ui_story_5037_50372201_63_dialog_content = "自らの演じる役を理解し、その役になりきる…\nそれでこそ、自然な人物として演じることができるのだ！",
  ui_story_5037_50372201_64_dialog_content = "ええ、しっかり理解したわ！",
  ui_story_5037_50372201_65_dialog_content = "今日教わったことを実践して、\n頑張って演技力を磨いていくわね！",
  ui_story_5037_50379901_1_dialog_content = "おかしい…",
  ui_story_5037_50379901_2_dialog_content = "絶対におかしい！",
  ui_story_5037_50379901_3_dialog_content = "ここ数日、バイスとカレンにずっと避けられてる…",
  ui_story_5037_50379901_4_dialog_content = "知らないうちに、何か気に障ることでもしちゃったのかな…？",
  ui_story_5037_50379901_5_dialog_content = "まさか、この間の…",
  ui_story_5037_50379901_6_option_content = "ブリッジでのことかな？",
  ui_story_5037_50379901_7_dialog_content = "うん、久しぶりに着てみたけど、\nやっぱりいい感じね。",
  ui_story_5037_50379901_8_dialog_content = "PlayerName、どう？いつもの啓光の制服と、\nどっちがいいかしら？",
  ui_story_5037_50379901_9_dialog_content = "うーん…そういうのはよく分からなくて。",
  ui_story_5037_50379901_10_dialog_content = "…",
  ui_story_5037_50379901_11_dialog_content = "あの時、「どっちもよく似合ってるよ」って言えばよかった！",
  ui_story_5037_50379901_12_option_content = "休憩室でのことかな？",
  ui_story_5037_50379901_13_dialog_content = "PlayerName！？",
  ui_story_5037_50379901_14_dialog_content = "早くあっちを向いて！\nどうしてここにいるの？",
  ui_story_5037_50379901_15_dialog_content = "め、目が覚めちゃって…それで、のどが渇いたなあって…",
  ui_story_5037_50379901_16_dialog_content = "今…何か見た？",
  ui_story_5037_50379901_17_dialog_content = "え？えっと…カレンがパジャマ姿で嬉しそうに鏡を見てたこと…とか？",
  ui_story_5037_50379901_18_dialog_content = "見間違いよ！",
  ui_story_5037_50379901_19_dialog_content = "あの時、「何も見てないよ」って言えばよかった！",
  ui_story_5037_50379901_20_dialog_content = "…でも、僕を避けるほどのことかな…？",
  ui_story_5037_50379901_21_dialog_content = "ああああ！いったい何が原因なんだろう？\n考えれば考えるほど分からなくなってきた！",
  ui_story_5037_50379901_22_dialog_content = "もうすぐ年越しだし、\nこんな気まずい空気のまま新年を迎えたくないな…",
  ui_story_5037_50379901_23_dialog_content = "…や、やっぱり、ハッキリ聞くのが一番だよね？",
  ui_story_5037_50379901_24_dialog_content = "<color=#e8d9bb>トントントン！</color>",
  ui_story_5037_50379901_25_dialog_content = "バイス、カレン、いる？",
  ui_story_5037_50379901_26_dialog_content = "<size=33>え？PlayerName！？\nこんな肝心なときにどうして…！？</size>",
  ui_story_5037_50379901_27_dialog_content = "<size=33>…急いで！早く！</size>",
  ui_story_5037_50379901_28_dialog_content = "PlayerName、ちょうどいい時に来たわね。",
  ui_story_5037_50379901_29_dialog_content = "ちょうど、カレンと一緒に呼びに行こうかなと思ってたところなの。\nさ、入って。",
  ui_story_5037_50379901_30_dialog_content = "ここのところ、ずっと僕を避けてたのに…\nずいぶんと急な変わりようだね？",
  ui_story_5037_50379901_31_dialog_content = "ええと、それは…すぐに分かるわ。",
  ui_story_5037_50379901_32_dialog_content = "…ねえ…どうして電気つけないの？\n真っ暗でちょっと怖いんだけど…",
  ui_story_5037_50379901_33_dialog_content = "真っ暗でないと、効果がないでしょう？",
  ui_story_5037_50379901_34_dialog_content = "こ、効果？効果って、なんのこと！？",
  ui_story_5037_50379901_35_dialog_content = "前をよく見ててちょうだい。\n始まるわよ。",
  ui_story_5037_50379901_36_dialog_content = "え？",
  ui_story_5037_50379901_38_dialog_content = "はあ、時間って本当に過ぎるのが早いわね…",
  ui_story_5037_50379901_39_dialog_content = "いつの間にか、また1年が過ぎちゃったわ。",
  ui_story_5037_50379901_40_dialog_content = "時が早く過ぎると感じるのは、いいことよ。",
  ui_story_5037_50379901_41_dialog_content = "充実した1年だったという、なによりの証拠だもの。",
  ui_story_5037_50379901_42_dialog_content = "ふふ、そうね。PlayerNameと一緒に冒険するようになって、\n毎日とっても充実してるわ！",
  ui_story_5037_50379901_43_dialog_content = "そう？じゃあ、テストしましょうか。",
  ui_story_5037_50379901_44_dialog_content = "この1年どこに行ったか、きちんと覚えているかしら？",
  ui_story_5037_50379901_45_dialog_content = "ふふ～ん、もちろん覚えてるわ！",
  ui_story_5037_50379901_46_dialog_content = "去年の今頃、私たちはものすごい吹雪の中を北境まで行ったのよね。",
  ui_story_5037_50379901_47_dialog_content = "オーロラの下で輝く氷の宮殿を見たのは、\nあの時が初めてだったわ！",
  ui_story_5037_50379901_48_dialog_content = "それから、初めて揚げた肉団子をイチゴジャムにつけて食べてみたけど…\nすっごくおいしかった！",
  ui_story_5037_50379901_49_dialog_content = "PlayerNameはその時ずっと鏡湖のほとりいて、\n女王陛下の過去を見たと言っていたわね…",
  ui_story_5037_50379901_50_dialog_content = "いったい、どんな過去だったのかしら？\n私も見てみたいわ。",
  ui_story_5037_50379901_51_dialog_content = "その後、華やかに飾られた蛍灯の木の下で、\n皆でカウントダウンをして新年を迎えたのよね！",
  ui_story_5037_50379901_52_dialog_content = "本当に懐かしいわ。",
  ui_story_5037_50379901_53_dialog_content = "…肉団子の味が？",
  ui_story_5037_50379901_54_dialog_content = "えへへ…",
  ui_story_5037_50379901_55_dialog_content = "北境から帰る途中、うっかり落ちてしまった「太古の都市」では…",
  ui_story_5037_50379901_56_dialog_content = "ロボットの攻撃を避けるためとはいえ、\n太古の服に着替えなければならなくなったのよね。",
  ui_story_5037_50379901_57_dialog_content = "ふふっ…PlayerNameのスカート姿、\n今でもハッキリ覚えているわ！",
  ui_story_5037_50379901_58_dialog_content = "その後、同じように太古の都市に閉じ込められてしまった仲間に\n出会ったのよね。",
  ui_story_5037_50379901_59_dialog_content = "最初は考え方の違いから、対立もしていたけど――",
  ui_story_5037_50379901_60_dialog_content = "最後には力を合わせて、\n太古の都市に住んでいた女の子2人を説得し…",
  ui_story_5037_50379901_61_dialog_content = "地下都市が壊滅する寸前、一緒に脱出することに成功したのよね。",
  ui_story_5037_50379901_62_dialog_content = "地下都市から戻った後、PlayerNameのところに\nあの都市から通信が届いたんだっけ。",
  ui_story_5037_50379901_63_dialog_content = "ええ。いつかまた、あの都市を見に行く機会があるかもしれないわね。",
  ui_story_5037_50379901_64_dialog_content = "そうね…でも、その後も私たちは足を休めることはなかったわ！",
  ui_story_5037_50379901_65_dialog_content = "手折りし花をわぎもに贈らん――",
  ui_story_5037_50379901_66_dialog_content = "玉雪の上に花落つる。",
  ui_story_5037_50379901_67_dialog_content = "依頼を受けて江富城へと足を運んで、そこの巫女様と知り合ったのよね。",
  ui_story_5037_50379901_68_dialog_content = "しかも、ちょうど「春日祭」の時期だったから、\n桜の花で町中が薄紅色に染まっていて…",
  ui_story_5037_50379901_69_dialog_content = "ただ、そんなお祭りの和やかな雰囲気の中…",
  ui_story_5037_50379901_70_dialog_content = "殺気が隠されていたなんて思いもしなかった。",
  ui_story_5037_50379901_71_dialog_content = "…積年の恨みの炎が昔日の華やかさを燃やし尽くしたあと…",
  ui_story_5037_50379901_72_dialog_content = "あの町に残されたのは――",
  ui_story_5037_50379901_73_dialog_content = "どんな別れだったのかしら…？",
  ui_story_5037_50379901_74_dialog_content = "私は行っていないから、その質問には答えられないわ。",
  ui_story_5037_50379901_75_dialog_content = "だって、あの時カレンは白夜城に戻っていたから…",
  ui_story_5037_50379901_76_dialog_content = "次は、絶対一緒に行きましょ！",
  ui_story_5037_50379901_77_dialog_content = "…んん？ちょっと待って？その後カレンはPlayerNameを誘って、\n白夜城にお芝居を観に行ったけれど…その時私、声を掛けられていないわ。",
  ui_story_5037_50379901_78_dialog_content = "正確には、行方不明になったグレーテルを探しに行ったのよ。",
  ui_story_5037_50379901_79_dialog_content = "手がかりをたどっていくうちに、\n私たちは「真実の館」というところにたどり着いたの。",
  ui_story_5037_50379901_80_dialog_content = "「真実の館」とはいっても、中にいたのは皆、\nおよそ人とは言い難い理性を失った人たちだったけれどね。",
  ui_story_5037_50379901_81_dialog_content = "断言できるわ…",
  ui_story_5037_50379901_82_dialog_content = "あの「お芝居」を観ずに済んだこと、幸運だったわね。",
  ui_story_5037_50379901_83_dialog_content = "え？そんな風に言われると、ますます興味が湧いちゃうわ！",
  ui_story_5037_50379901_84_dialog_content = "それはそうと、何か抜けてない…？",
  ui_story_5037_50379901_85_dialog_content = "PlayerNameがR・W砂漠に行った時のこと？\nあれは、あなたも行ったのではなかった？",
  ui_story_5037_50379901_86_dialog_content = "あ、そうだった…灼熱ラリーがあったわね！\nあの時は、PlayerNameがサメヤマにさらわれたかと思って…",
  ui_story_5037_50379901_87_dialog_content = "でも、私はラリーの最後になってやっと追いついたから…",
  ui_story_5037_50379901_88_dialog_content = "それまでPlayerNameが助手席でどんな風景を見て…",
  ui_story_5037_50379901_89_dialog_content = "きれいなお姉さんの昔話をどんな顔で聞いていたのか…",
  ui_story_5037_50379901_90_dialog_content = "細かいことはよく知らないの。",
  ui_story_5037_50379901_91_dialog_content = "私がはっきり覚えてるのは、\nR・Wのバーベキューが意外においしかったってことだけね！",
  ui_story_5037_50379901_92_dialog_content = "あら。どうやらトップクラスの美食家へと、\nまた1歩近づいたみたいね。",
  ui_story_5037_50379901_93_dialog_content = "カレン、あなたもそう思う！？",
  ui_story_5037_50379901_94_dialog_content = "やっぱり私には、料理の才能があるんだわ！",
  ui_story_5037_50379901_95_dialog_content = "PlayerName、今度また新メニューを考えるから、\n楽しみにしててね！",
  ui_story_5037_50379901_96_dialog_content = "そういえば、PlayerNameは私たちがいない間に、\nプロの執事を雇ったこともあったわね。",
  ui_story_5037_50379901_97_dialog_content = "その時に…",
  ui_story_5037_50379901_98_dialog_content = "きっと、たくさんの珍味やおいしいものを食べたのでしょうね。",
  ui_story_5037_50379901_99_dialog_content = "最初は、私たちがそばにいなくて大丈夫かしらって\n心配してたけど…",
  ui_story_5037_50379901_100_dialog_content = "今思えば、PlayerNameにも\n一人でやっていく力は十分あったのよね。",
  ui_story_5037_50379901_101_dialog_content = "天空ノ庭の主として、お客さんをもてなしたり…",
  ui_story_5037_50379901_102_dialog_content = "天空ノ庭をきちんと管理したりと、ちゃんとできてるもの！",
  ui_story_5037_50379901_103_dialog_content = "PlayerNameの管理能力は確かに大きく進歩しているわ。",
  ui_story_5037_50379901_104_dialog_content = "ただ、やはりまだそばに誰かいないと駄目よ。",
  ui_story_5037_50379901_105_dialog_content = "そうでないと、だまされていることにも気づかず、\n人助けばかりしてしまうわ。",
  ui_story_5037_50379901_106_dialog_content = "PlayerNameの場合、相手は珍獣の研究者だったから\n運が良かったけどね…",
  ui_story_5037_50379901_107_dialog_content = "実際に何があったのかは…",
  ui_story_5037_50379901_108_dialog_content = "『珍獣探して大冒険』を読むしかないわね。",
  ui_story_5037_50379901_109_dialog_content = "そのことについては、フィアから何度も聞いたわ。",
  ui_story_5037_50379901_110_dialog_content = "えっ？いつ？",
  ui_story_5037_50379901_111_dialog_content = "一緒にハーバーシティに行った時、\n私たちもフィアに会ったでしょう？",
  ui_story_5037_50379901_112_dialog_content = "あ、あの時ね！",
  ui_story_5037_50379901_113_dialog_content = "一緒にエメラルド号のカーニバルに参加できて、\n本当に楽しかったわ！",
  ui_story_5037_50379901_114_dialog_content = "ただ、まさか…",
  ui_story_5037_50379901_115_dialog_content = "にぎやかなカーニバルの裏に、\n城主エルビスが長年計画していた陰謀が隠されていたんなんてね…",
  ui_story_5037_50379901_116_dialog_content = "エルビスがどんな思いであんなことをしたのか、\n後になって知ったけれど…",
  ui_story_5037_50379901_117_dialog_content = "それでも城主たるもの、あんな無茶なことをすべきではないわ。",
  ui_story_5037_50379901_118_dialog_content = "エルビスは最後、自らを犠牲にして\nハーバーシティの民を災難から救ったけれど…",
  ui_story_5037_50379901_119_dialog_content = "あの事件で思ったの。人というのは単純な「良い」、「悪い」で\n判断できないのかもしれない…と。",
  ui_story_5037_50379901_120_dialog_content = "ジェノは、エルビスを目覚めさせる方法を見つけたのかしら。",
  ui_story_5037_50379901_121_dialog_content = "エルビスが目覚めたら、\n私自ら彼を白夜城に連れ帰り、審判にかけるわ。",
  ui_story_5037_50379901_122_dialog_content = "…そうね。",
  ui_story_5037_50379901_123_dialog_content = "ハーバーシティから戻ったあと、\nPlayerNameは連続殺人犯を追うワタリに会って…",
  ui_story_5037_50379901_124_dialog_content = "一緒に手がかりをたどって、\n「楽園」と呼ばれた町――ユーフォリアに行ったのよね。",
  ui_story_5037_50379901_125_dialog_content = "ユーフォリアはかつて「楽園」と呼ばれていたけれど、\n最近では多くの闇組織がうごめく深い霧に覆われた町になっていた。",
  ui_story_5037_50379901_126_dialog_content = "毎日のように殺しや盗み、さらには殺し合いが起こっていたわ。",
  ui_story_5037_50379901_127_dialog_content = "でも、そんな泥沼のような環境の中でも、\nアジサイは変わらず美しい花を咲かせていた。",
  ui_story_5037_50379901_128_dialog_content = "きっとそう遠くないうちに、ユーフォリアはまた「楽園」に戻るわよね。",
  ui_story_5037_50379901_129_dialog_content = "そうして、ユーフォリアから戻ってまもなく…",
  ui_story_5037_50379901_130_dialog_content = "私とPlayerNameは開業したばかりの、\n「アンデルセンのゴーストハウス」に遊びに行ったんだっけ。",
  ui_story_5037_50379901_131_dialog_content = "そうそう、そこでひょんなことから、\n探索ドキュメンタリ―の撮影に参加することになったのよね。",
  ui_story_5037_50379901_132_dialog_content = "最初はただのゴーストハウスだったはずなのに、\n本当に身の毛のよだつ恐ろしい体験をするとは思わなかったわ。",
  ui_story_5037_50379901_133_dialog_content = "ゴーストハウスに、正真正銘の叫び声が響いたのよね！",
  ui_story_5037_50379901_134_dialog_content = "私の一番好きだったホラー映画監督がまさか…\n暗鬼を使って、凄惨なシーンを撮影してたなんて思わなかったわ！",
  ui_story_5037_50379901_135_dialog_content = "あの時は、用事で行けなくてよかったわ。",
  ui_story_5037_50379901_136_dialog_content = "あれ？怖いもの知らずのカレンも、もしかしてオバケが怖いの？",
  ui_story_5037_50379901_137_dialog_content = "いいえ。ただ、私が行っていたら…\n本当に怖い思いをするのは女幽霊の方だったでしょうね。",
  ui_story_5037_50379901_138_dialog_content = "あはは、カレンが？どのへんが怖…",
  ui_story_5037_50379901_139_dialog_content = "…",
  ui_story_5037_50379901_140_dialog_content = "<size=45>きゃあああ！！オバケ！！</size>",
  ui_story_5037_50379901_141_dialog_content = "ほら、こういうことよ。",
  ui_story_5037_50379901_142_dialog_content = "い、今のは…本当にカレン…？\nまさか、カレンがオバケだったりして！？",
  ui_story_5037_50379901_143_dialog_content = "これくらいのコスプレなんて、皆やってるでしょう？",
  ui_story_5037_50379901_144_dialog_content = "そ、そうね…",
  ui_story_5037_50379901_145_dialog_content = "コホンッ、本題に戻りましょ！",
  ui_story_5037_50379901_146_dialog_content = "PlayerName、今年ももうすぐ終わりね。",
  ui_story_5037_50379901_147_dialog_content = "今年体験したことを記録したいと思って、\nバイスと2人でこのビデオを用意したのよ。",
  ui_story_5037_50379901_148_dialog_content = "ねえPlayerName、新しい年になったあとも…",
  ui_story_5037_50379901_149_dialog_content = "一緒に、冒険しましょうね！",
  ui_story_5037_50379901_151_dialog_content = "バイス、カレン…",
  ui_story_5037_50379901_152_dialog_content = "このところ、ずっとコソコソしてたのは…\n今のビデオを準備してたからなの？",
  ui_story_5037_50379901_153_dialog_content = "ふふふ、あなたを驚かそうと思って！",
  ui_story_5037_50379901_154_dialog_content = "今日は今年最後の日よ。\n特別な日は、お祝いをするものでしょう？",
  ui_story_5037_50379901_155_dialog_content = "直接話してくれてもよかったのに…",
  ui_story_5037_50379901_156_dialog_content = "わざわざビデオを撮るなんて、大変だったでしょ？",
  ui_story_5037_50379901_157_dialog_content = "ツアードッグさんに絵を描いてもらうのに、\nたくさんお金を使っちゃったから…",
  ui_story_5037_50379901_158_dialog_content = "せっかくだもの、いいビデオにしたかったの！",
  ui_story_5037_50379901_159_dialog_content = "年越しなら、特別な雰囲気を出してこそでしょう？",
  ui_story_5037_50379901_160_dialog_content = "…それに、直接だと言いにくいこともあるわ。",
  ui_story_5037_50379901_161_dialog_content = "それとも…ビデオ、気に入らなかった？",
  ui_story_5037_50379901_162_option_content = "気に入ったよ！",
  ui_story_5037_50379901_163_option_content = "すっごく気に入ったよ！",
  ui_story_5037_50379901_164_dialog_content = "はぁ…はぁ…はぁ…",
  ui_story_5037_50379901_165_dialog_content = "ギリギリ間に合ったー！ローラ、遅刻じゃないよね？",
  ui_story_5037_50379901_166_dialog_content = "ローラ？この時期は北境にいるんじゃ…？",
  ui_story_5037_50379901_167_dialog_content = "バイスお姉ちゃんとカレンお姉ちゃんに誘われたの！\n今年はPlayerNameのところで年越ししようって。",
  ui_story_5037_50379901_168_dialog_content = "え？そうなの？",
  ui_story_5037_50379901_169_dialog_content = "ええ、それと…",
  ui_story_5037_50379901_170_dialog_content = "みんな、出てきて！",
  ui_story_5037_50379901_171_dialog_content = "PlayerName、元気そうだね！",
  ui_story_5037_50379901_172_dialog_content = "PlayerName、いつ猫なんて飼ったの？\nポンタとロンタが驚いちゃってたよ！",
  ui_story_5037_50379901_173_dialog_content = "ルビー姉、猫はあたしが捕まえるわ！",
  ui_story_5037_50379901_174_dialog_content = "ベビーちゃんをイジメないで！",
  ui_story_5037_50379901_175_dialog_content = "メェ～！",
  ui_story_5037_50379901_176_dialog_content = "メイ、レノーアが、ベビーちゃんを守ります。",
  ui_story_5037_50379901_177_dialog_content = "アイタタ…ま、また転んでしまいました。\nそれにしても…どうしてこんなところにヘビが？",
  ui_story_5037_50379901_178_dialog_content = "シャー！",
  ui_story_5037_50379901_179_dialog_content = "エリカ、アルバの言葉を学んでもムダよ。\n蛇の言葉は宇宙の言葉じゃないのよ…",
  ui_story_5037_50379901_180_dialog_content = "フフ、ボーヤ、なんだかにぎやかにしてるわね？",
  ui_story_5037_50379901_181_dialog_content = "大変だわ！",
  ui_story_5037_50379901_182_dialog_content = "え？",
  ui_story_5037_50379901_183_dialog_content = "もうすぐカウントダウンよ。\n皆、急いで準備して！",
  ui_story_5037_50379901_184_dialog_content = "ヨウ、いい加減に食べるのはよせ…始まるぞ。",
  ui_story_5037_50379901_185_dialog_content = "モグモグ…ゴクン。はいはーい！",
  ui_story_5037_50379901_186_dialog_content = "カウントダウン、スタート！",
